const script=[{"id": 1, "speaker": "舞台提示", "text": "晚清，1898年9月11日至21日，戊戌政变前后10天北京法源寺", "page": 2, "y": 1222, "col": 0, "kind": "stage", "chapter": 0}, {"id": 2, "speaker": "舞台提示", "text": "[舞台：法源寺院内，伫立石碑、石杵、石墩、条案。隐约可见周遭庙宇林立。舞台两侧摆放整齐的中式座椅、衣架，架子挂有和尚们穿戴衣物。", "page": 2, "y": 1427, "col": 0, "kind": "stage", "chapter": 0}, {"id": 3, "speaker": "舞台提示", "text": "[灯光：照亮舞台环境与和尚们。", "page": 2, "y": 1634, "col": 0, "kind": "stage", "chapter": 0}, {"id": 4, "speaker": "舞台提示", "text": "[幕外：鸟鸣、鸽哨、撞钟声，夹杂寺庙诵经的声音，明朗清净。", "page": 2, "y": 1686, "col": 0, "kind": "stage", "chapter": 0}, {"id": 5, "speaker": "舞台提示", "text": "[年轻和尚们，或在背诵经文，或在记述佛教知识与寺庙历史", "page": 2, "y": 1789, "col": 0, "kind": "stage", "chapter": 0}, {"id": 6, "speaker": "舞台提示", "text": "[四位女居士，在帮忙整理架子上的衣服，或整理香案。", "page": 2, "y": 1892, "col": 0, "kind": "stage", "chapter": 0}, {"id": 7, "speaker": "和尚1", "text": "菩萨道众生、觉有情、大觉有情、道心众生。", "page": 2, "y": 1997, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 8, "speaker": "和尚2", "text": "任持自性、轨生物解。佛教，广义地说，是一种宗教", "page": 2, "y": 2048, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 9, "speaker": "和尚3", "text": "佛不是神。佛是了悟宇宙真理和真相的觉悟者", "page": 2, "y": 238, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 10, "speaker": "和尚4", "text": "佛为西元前六世纪印度人，名为悉达多，姓为乔达摩，是位王子。", "page": 2, "y": 341, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 11, "speaker": "和尚5", "text": "释迦牟尼的时代，是我们的春秋时代，与孔子同时。", "page": 2, "y": 444, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 12, "speaker": "和尚1", "text": "释迦牟尼提出众生平等，他接近平民。", "page": 2, "y": 548, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 13, "speaker": "和尚2", "text": "佛，教导众生断除内心烦恼，以求正见和解脱", "page": 2, "y": 600, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 14, "speaker": "和尚3", "text": "佛，教导我们“诸恶莫作，诸善奉行”", "page": 2, "y": 702, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 15, "speaker": "众和尚", "text": "佛，从没有教授人民以怎样的实际行动反抗统治者", "page": 2, "y": 755, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 16, "speaker": "舞台提示", "text": "[幕外：一声磬响。", "page": 2, "y": 858, "col": 1, "kind": "stage", "chapter": 0}, {"id": 17, "speaker": "舞台提示", "text": "[灯光：隐去和尚们。", "page": 2, "y": 910, "col": 1, "kind": "stage", "chapter": 0}, {"id": 18, "speaker": "舞台提示", "text": "[多媒体：法源寺观音阁前的清净院落。", "page": 2, "y": 961, "col": 1, "kind": "stage", "chapter": 0}, {"id": 19, "speaker": "舞台提示", "text": "〔灯光：再起。", "page": 2, "y": 1013, "col": 1, "kind": "stage", "chapter": 0}, {"id": 20, "speaker": "舞台提示", "text": "[和尚们变换方位，继续背诵。", "page": 2, "y": 1065, "col": 1, "kind": "stage", "chapter": 0}, {"id": 21, "speaker": "和尚2", "text": "当修佛心，远离有形。", "page": 2, "y": 1117, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 22, "speaker": "和尚3", "text": "一者礼敬诸佛，二者称赞如来，三者广修供养，四者忏悔业障，五者随喜功德。", "page": 2, "y": 1168, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 23, "speaker": "和尚1", "text": "六者请转法轮，七者请佛住世，八者常随佛学，九者恒顺众生，十者普皆回向。", "page": 2, "y": 1272, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 24, "speaker": "和尚1", "text": "以出世的精神，做人世的事情，气魄自是不凡。", "page": 2, "y": 1374, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 25, "speaker": "和尚4", "text": "超越一切对峙，本体即现象，现象即本体", "page": 2, "y": 1479, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 26, "speaker": "舞台提示", "text": "[普净法师，走出。", "page": 2, "y": 1531, "col": 1, "kind": "stage", "chapter": 0}, {"id": 27, "speaker": "舞台提示", "text": "[谭嗣同，走出。", "page": 2, "y": 1582, "col": 1, "kind": "stage", "chapter": 0}, {"id": 28, "speaker": "普净", "text": "寺庙有形，佛门无形。我叫普净，法源寺现任方丈。", "page": 2, "y": 1634, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 29, "speaker": "谭嗣同", "text": "当修佛心，远离有形我叫谭嗣同。", "page": 2, "y": 1737, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 30, "speaker": "普净", "text": "法源寺在北京西城牛街附近，宣武门外教子胡同东南侧。", "page": 2, "y": 1789, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 31, "speaker": "谭嗣同", "text": "我生在北京宣武门外烂漫胡同寓所，家离法源寺很近。", "page": 2, "y": 1893, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 32, "speaker": "普净", "text": "法源寺是唐太宗李世民东征高丽为死难将士们修建的。武则天时期完成工程，赐名悯忠寺。", "page": 2, "y": 1996, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 33, "speaker": "谭嗣同", "text": "我长大后经常在这家庙里走动。看见的是清朝雍正皇帝重修寺庙时改名的法源寺。", "page": 3, "y": 240, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 34, "speaker": "普净", "text": "我是1921年这座寺庙的方丈", "page": 3, "y": 343, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 35, "speaker": "谭嗣同", "text": "我死的时候是1898年，我的灵，就停在这儿。", "page": 3, "y": 395, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 36, "speaker": "舞台提示", "text": "[异禀小师父，走出", "page": 3, "y": 498, "col": 0, "kind": "stage", "chapter": 0}, {"id": 37, "speaker": "舞台提示", "text": "[诸位和尚与居士在礼佛", "page": 3, "y": 550, "col": 0, "kind": "stage", "chapter": 0}, {"id": 38, "speaker": "普净", "text": "寺庙是个好道场，祈福、许愿，讨论鬼神、僧俗、出人、仕隐。", "page": 3, "y": 601, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 39, "speaker": "谭嗣同", "text": "寺庙是个好道场，超度、忏悔，讨论生死、朝野、家国、君臣", "page": 3, "y": 704, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 40, "speaker": "普净", "text": "人我、是非、情理", "page": 3, "y": 807, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 41, "speaker": "谭嗣同", "text": "常变、去留、因果、经世济民。", "page": 3, "y": 859, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 42, "speaker": "普净", "text": "今天，我给你讲讲晚清。寺庙前任方丈佘云大和尚生前支持过戊戌变法，是谭嗣同好友，我小时候见过谭嗣同", "page": 3, "y": 910, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 43, "speaker": "舞台提示", "text": "[普净，似乎看到谭嗣同", "page": 3, "y": 1065, "col": 0, "kind": "stage", "chapter": 0}, {"id": 44, "speaker": "谭嗣同", "text": "我见过你吗？", "page": 3, "y": 1116, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 45, "speaker": "异禀", "text": "师父，谭嗣同在和您说话。", "page": 3, "y": 1168, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 46, "speaker": "普净", "text": "闭嘴，这是牌位。", "page": 3, "y": 1219, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 47, "speaker": "舞台提示", "text": "[幕外：开门声，一阵风声", "page": 3, "y": 1271, "col": 0, "kind": "stage", "chapter": 0}, {"id": 48, "speaker": "普净", "text": "他很会讲佛法。", "page": 3, "y": 1322, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 49, "speaker": "谭嗣同", "text": "我死之前，请求停灵法源寺，请求佘云大和尚为我超度。出世、人世，为众生舍身。此即“回向”人间，这种“回向”后的舍身，才是真正的佛教", "page": 3, "y": 1374, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 50, "speaker": "舞台提示", "text": "[普净与拿着香炉的异禀小师父，走向谭", "page": 3, "y": 1580, "col": 0, "kind": "stage", "chapter": 0}, {"id": 51, "speaker": "普净", "text": "今天给大和尚上香，也给谭嗣同和他死难的朋友们上柱香。", "page": 3, "y": 1683, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 52, "speaker": "舞台提示", "text": "[普净，给谭嗣同敬香", "page": 3, "y": 1786, "col": 0, "kind": "stage", "chapter": 0}, {"id": 53, "speaker": "普净", "text": "（对异禀）我对晚清这段历史，一直很感兴趣", "page": 3, "y": 1838, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 54, "speaker": "舞台提示", "text": "[普净，走进大雄宝殿。", "page": 3, "y": 1941, "col": 0, "kind": "stage", "chapter": 0}, {"id": 55, "speaker": "舞台提示", "text": "[异禀，叫了一声“师父”，回看谭嗣同", "page": 3, "y": 1992, "col": 0, "kind": "stage", "chapter": 0}, {"id": 56, "speaker": "异禀", "text": "义士，我对晚清，也很感兴趣", "page": 3, "y": 2045, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 57, "speaker": "谭嗣同", "text": "你很有悟性。", "page": 3, "y": 2095, "col": 0, "kind": "dialogue", "chapter": 0}, {"id": 58, "speaker": "异禀", "text": "（笑）我有异禀", "page": 3, "y": 241, "col": 1, "kind": "dialogue", "chapter": 0}, {"id": 59, "speaker": "舞台提示", "text": "[异禀，跟随师父普净，走进大雄宝殿", "page": 3, "y": 293, "col": 1, "kind": "stage", "chapter": 0}, {"id": 60, "speaker": "舞台提示", "text": "[幕外：惠普法师唱诵“南无阿弥陀佛”音乐响起", "page": 3, "y": 344, "col": 1, "kind": "stage", "chapter": 0}, {"id": 61, "speaker": "舞台提示", "text": "[多媒体：出现字幕“第一章节自报家门情何以堪”", "page": 3, "y": 447, "col": 1, "kind": "stage", "chapter": 1}, {"id": 62, "speaker": "舞台提示", "text": "[灯光：照亮谭嗣同", "page": 3, "y": 550, "col": 1, "kind": "stage", "chapter": 1}, {"id": 63, "speaker": "谭嗣同", "text": "我知道我为什么爱来法源寺……", "page": 3, "y": 602, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 64, "speaker": "舞台提示", "text": "[幕外：一声磬响", "page": 3, "y": 653, "col": 1, "kind": "stage", "chapter": 1}, {"id": 65, "speaker": "舞台提示", "text": "[多媒体：大雄宝殿内", "page": 3, "y": 705, "col": 1, "kind": "stage", "chapter": 1}, {"id": 66, "speaker": "舞台提示", "text": "[和尚、居士们在上香、行礼。", "page": 3, "y": 757, "col": 1, "kind": "stage", "chapter": 1}, {"id": 67, "speaker": "舞台提示", "text": "[舞台构成前、后空间。", "page": 3, "y": 808, "col": 1, "kind": "stage", "chapter": 1}, {"id": 68, "speaker": "谭嗣同", "text": "我想做个觉悟的人。勘破生老病死，勘破政治棋局，勘破人伦俗世，勘破道德文章，勘破社会伦纲，勘破历史千载，勘破宇宙万象。穿越历史，横亘古今。看破生死，看穿人鬼。我知道我离这种境界还有一点儿距离。我出生的地方离法源寺很近，所以我经常到庙里走动。父亲谭继洵时任户部主事，后来升迁至湖北省省长，清朝管这叫“从二品大员”，所以我是一个不折不扣的，官二代。我所处的这个时代，正是沉疴百年的晚清帝国。彼时的文化和人心，沉沦到了亡国的边缘。戊戌年，我33岁，想以我的个人之躯，打破数亿国民的意识桎梏，就像在集体潜意识的湖面上，投下一枚石子，抑或用生命迸射那一亮的闪电，去惊醒深睡的人，睁眼看看这国家，保全自己是目前大多数人的选择，可我，想选择一条极少有人去走的道路——殉", "page": 3, "y": 860, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 69, "speaker": "舞台提示", "text": "[多媒体：恢复寺庙院墙，出现“殉”字。", "page": 3, "y": 1838, "col": 1, "kind": "stage", "chapter": 1}, {"id": 70, "speaker": "舞台提示", "text": "[灯光：照亮上场的杨锐、刘光第林旭", "page": 3, "y": 1889, "col": 1, "kind": "stage", "chapter": 1}, {"id": 71, "speaker": "杨锐", "text": "我是杨锐。戊戌变法重要人物之一我是四川绵竹人。", "page": 3, "y": 1941, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 72, "speaker": "舞台提示", "text": "[多媒体：大雄宝殿内，悬挂着“法海真源”匾额。", "page": 3, "y": 2044, "col": 1, "kind": "stage", "chapter": 1}, {"id": 73, "speaker": "刘光第", "text": "刘光第，戊戌变法重要人物之一我是四川自贡人。", "page": 4, "y": 249, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 74, "speaker": "林旭", "text": "林旭，戊戌变法重要人物之一我是福建人", "page": 4, "y": 352, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 75, "speaker": "舞台提示", "text": "[林旭，向谭嗣同揖手", "page": 4, "y": 402, "col": 0, "kind": "stage", "chapter": 1}, {"id": 76, "speaker": "林旭", "text": "复生兄！", "page": 4, "y": 454, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 77, "speaker": "舞台提示", "text": "[谭嗣同、刘光第、锐、林旭，四位章京，陆续落座", "page": 4, "y": 504, "col": 0, "kind": "stage", "chapter": 1}, {"id": 78, "speaker": "谭嗣同", "text": "我们四个砍头时间，一致。", "page": 4, "y": 607, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 79, "speaker": "四章京", "text": "（合）1898年9月28日", "page": 4, "y": 658, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 80, "speaker": "舞台提示", "text": "[康有为，上场", "page": 4, "y": 708, "col": 0, "kind": "stage", "chapter": 1}, {"id": 81, "speaker": "舞台提示", "text": "[梁启超，上场", "page": 4, "y": 759, "col": 0, "kind": "stage", "chapter": 1}, {"id": 82, "speaker": "舞台提示", "text": "[四位章京，与诸位和尚、居士，分坐庙里两侧。", "page": 4, "y": 810, "col": 0, "kind": "stage", "chapter": 1}, {"id": 83, "speaker": "普净", "text": "我喜欢乾隆皇帝题的这副匾额“法海真源”，至今悬挂法源寺内。未来法源寺会是中国佛学院所在地", "page": 4, "y": 913, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 84, "speaker": "异禀", "text": "师父，您真有远见。", "page": 4, "y": 1067, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 85, "speaker": "谭嗣同", "text": "培养和尚的地方。", "page": 4, "y": 1118, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 86, "speaker": "刘光第", "text": "培养大根器之人。", "page": 4, "y": 1169, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 87, "speaker": "林旭", "text": "培养未来全国寺庙的方丈、住持、监院", "page": 4, "y": 1221, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 88, "speaker": "杨锐", "text": "有修为的大德智者", "page": 4, "y": 1272, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 88001, "speaker": "普净", "text": "我一点儿不替我们寺庙感到惭愧，因为能到法源寺修行，是想做和尚的、想成为好修行人的僧人们的人生幸事", "page": 4, "y": 1272, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 89, "speaker": "异禀", "text": "师父，您怎么对着空气说话", "page": 4, "y": 1476, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 90, "speaker": "普净", "text": "这是牌位，拜拜牌位。", "page": 4, "y": 1527, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 91, "speaker": "四章京", "text": "给诸位法师问好！", "page": 4, "y": 1578, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 92, "speaker": "舞台提示", "text": "[普净、异禀，给四章京行礼。", "page": 4, "y": 1628, "col": 0, "kind": "stage", "chapter": 1}, {"id": 93, "speaker": "康有为", "text": "法源寺，有历朝历代的皇帝光顾，唐宋元明清，辽、金的少数民族皇帝也来此庙", "page": 4, "y": 1680, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 94, "speaker": "异禀", "text": "我想了解康有为", "page": 4, "y": 1782, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 95, "speaker": "梁启超", "text": "最后一个走动法源寺的皇帝是光绪", "page": 4, "y": 1834, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 96, "speaker": "异禀", "text": "我想了解梁启超", "page": 4, "y": 1885, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 97, "speaker": "普净", "text": "都是戊戌变法重要人物。你想了解戊戌变法？", "page": 4, "y": 1936, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 98, "speaker": "异禀", "text": "我想了解晚清。", "page": 4, "y": 2038, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 99, "speaker": "普净", "text": "晚清这段历史讲述的是家国、君臣、出世、人隐。", "page": 4, "y": 2088, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 100, "speaker": "舞台提示", "text": "[四章京离开座位，与康有为、梁启超相聚", "page": 4, "y": 299, "col": 1, "kind": "stage", "chapter": 1}, {"id": 101, "speaker": "异禀", "text": "师父，他们还活着吗？", "page": 4, "y": 402, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 101001, "speaker": "普净", "text": "你看不见吗？", "page": 4, "y": 402, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 102, "speaker": "异禀", "text": "活着", "page": 4, "y": 504, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 103, "speaker": "普净", "text": "你关注生！", "page": 4, "y": 555, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 104, "speaker": "异禀", "text": "您讲述死！", "page": 4, "y": 606, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 105, "speaker": "普净", "text": "极端的国难", "page": 4, "y": 657, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 106, "speaker": "谭嗣同", "text": "极端的生死", "page": 4, "y": 708, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 107, "speaker": "梁启超", "text": "极端的失败", "page": 4, "y": 758, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 108, "speaker": "康有为", "text": "极端的成功", "page": 4, "y": 809, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 109, "speaker": "普净", "text": "在极端的两极寻找常态，发现平衡这些变法维新人士，住家离法源寺很近", "page": 4, "y": 861, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 110, "speaker": "康有为", "text": "我叫康有为，（广东话）我是广东人", "page": 4, "y": 963, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 111, "speaker": "梁启超", "text": "（广东话）我也是广东人。", "page": 4, "y": 1014, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 112, "speaker": "康有为", "text": "（广东话）自己人", "page": 4, "y": 1065, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 113, "speaker": "梁启超", "text": "（广东话）自己人。", "page": 4, "y": 1117, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 114, "speaker": "康有为", "text": "戊戌年，我到北京长住，就住在菜市口米市胡同43号“南海会馆”", "page": 4, "y": 1168, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 115, "speaker": "梁启超", "text": "我叫梁启超，我成家在北京，就住在陶然亭边上，粉房琉璃街“新会会馆”", "page": 4, "y": 1270, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 116, "speaker": "普净", "text": "他们常到庙里走动。谭、梁二位虔诚信佛", "page": 4, "y": 1373, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 117, "speaker": "舞台提示", "text": "[幕外：一声磬响", "page": 4, "y": 1423, "col": 1, "kind": "stage", "chapter": 1}, {"id": 118, "speaker": "异禀", "text": "师父，我想知道他们为什么生？为什么死？", "page": 4, "y": 1475, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 119, "speaker": "梁启超", "text": "我选择“生”，看见现世，推动发展", "page": 4, "y": 1526, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 120, "speaker": "康有为", "text": "我即是老。我不承认我老，越老越有味道．：、老了可以回看历史，传扬文化，评点我们选择“病”。国家病了，人也就病了。", "page": 4, "y": 1576, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 121, "speaker": "杨锐", "text": "国病、人病，还有心病", "page": 4, "y": 1832, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 122, "speaker": "谭嗣同", "text": "我选择“死”，冥阳一隔，穿人自由。（对普净）你说！", "page": 4, "y": 1884, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 123, "speaker": "普净", "text": "正是。庙堂高耸，人间戏场！幕外：京戏锣鼓声响起", "page": 4, "y": 1986, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 124, "speaker": "舞台提示", "text": "[四章京，走回座位。", "page": 4, "y": 2088, "col": 1, "kind": "stage", "chapter": 1}, {"id": 125, "speaker": "舞台提示", "text": "[众和尚，走回座位。", "page": 5, "y": 240, "col": 0, "kind": "stage", "chapter": 1}, {"id": 126, "speaker": "康有为", "text": "等等，我有话说。", "page": 5, "y": 291, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 127, "speaker": "梁启超", "text": "我也有话说。我会成为推动中国现代社会发展的，开山巨匠。", "page": 5, "y": 343, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 128, "speaker": "舞台提示", "text": "[普净，看见异禀发呆痴想", "page": 5, "y": 445, "col": 0, "kind": "stage", "chapter": 1}, {"id": 129, "speaker": "普净", "text": "你在做什么？", "page": 5, "y": 497, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 130, "speaker": "异禀", "text": "我在听康有为说话", "page": 5, "y": 548, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 131, "speaker": "康有为", "text": "哈佛大学、耶鲁大学、普林斯顿大学、康奈尔大学，第一华人教授，一位姓余的先生……", "page": 5, "y": 599, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 132, "speaker": "舞台提示", "text": "[异禀，对康有为说。", "page": 5, "y": 753, "col": 0, "kind": "stage", "chapter": 1}, {"id": 133, "speaker": "异禀", "text": "老师，您说的都是英文。", "page": 5, "y": 805, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 134, "speaker": "梁启超", "text": "康老师说的是中文。", "page": 5, "y": 856, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 135, "speaker": "康有为", "text": "我说什么不重要。", "page": 5, "y": 908, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 136, "speaker": "梁启超", "text": "对，不重要！", "page": 5, "y": 959, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 137, "speaker": "康有为", "text": "但对中国很重要。", "page": 5, "y": 1011, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 138, "speaker": "梁启超", "text": "很重要。", "page": 5, "y": 1062, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 139, "speaker": "康有为", "text": "这不是戏，这是震动中华的大事件。", "page": 5, "y": 1113, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 140, "speaker": "普净", "text": "拿话筒。", "page": 5, "y": 1165, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 141, "speaker": "梁启超", "text": "我来。", "page": 5, "y": 1216, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 142, "speaker": "异禀", "text": "为什么？", "page": 5, "y": 1268, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 143, "speaker": "梁启超", "text": "我是他学生。", "page": 5, "y": 1319, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 144, "speaker": "舞台提示", "text": "[梁启超，将话筒递给康有为。", "page": 5, "y": 1371, "col": 0, "kind": "stage", "chapter": 1}, {"id": 145, "speaker": "舞台提示", "text": "[康有为，站定，轻嗽了两声，开始发言", "page": 5, "y": 1423, "col": 0, "kind": "stage", "chapter": 1}, {"id": 146, "speaker": "康有为", "text": "哈佛大学、耶鲁大学、普林斯顿大学、康奈尔大学，第一华人教授，一位姓余的先生在论述中国传统政治与文化的时候，把士大夫分为两个壁垒分明的阶层：职业官僚，和以弘道自命的士人。二者结合最好的，当属清代楷模——曾国藩。结合不好的，当属晚清士人康有为。我想，我可以反驳余先生的观点吗？康有为，一个以重建治道自命，苦心钻研政体，当属宰相之才，无奈沦落“体制外”的，你说的，名士知识分子。康有为，从来自负宏大的目标与责任，认定弘道护国，治国兴邦、兴利除弊，圣徒使命，非他一人。康有为，自幼通天理，好易学，苦读圣贤之书，师从九江大儒朱次琦，以圣人转世自居。康有为，青年游历香港、内地，研读大乘佛教经典，弘扬“普济救世”之论。康有为，作为圣贤与救世的结合体，深情热爱着几千年的古国帝制，热情体恤着民族苍生！我曾用我卓越的学识和区区个人之体，救助过愁云惨淡、强风劲吹满目疮痍的大清！我七次上书朝廷，第一次六千字，第二次一万七千字，第三次一万五千九百四十一字，我见到了，皇上！", "page": 5, "y": 1473, "col": 0, "kind": "dialogue", "chapter": 1}, {"id": 147, "speaker": "舞台提示", "text": "[幕外：一阵锣鼓声。", "page": 5, "y": 805, "col": 1, "kind": "stage", "chapter": 1}, {"id": 148, "speaker": "舞台提示", "text": "[光绪，上场", "page": 5, "y": 856, "col": 1, "kind": "stage", "chapter": 1}, {"id": 149, "speaker": "康有为", "text": "我面对皇上慷慨激昂，宣示立场，是“坦荡荡”的君子。余先生，你却说我，自身有性格缺陷，与这种圣徒式的使命感相违逆，时而是“长戚戚”的小人。康有为这种人的标准形态是委以使命感的时候，他会一筹莫展，障碍难行对于这样的人，你们称呼他为“名士”我还是想以一个事实击溃你的说法，那就是三十年前……现在是？", "page": 5, "y": 908, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 150, "speaker": "异禀", "text": "1921年。", "page": 5, "y": 1371, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 151, "speaker": "康有为", "text": "那就是三十年前", "page": 5, "y": 1423, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 152, "speaker": "异禀", "text": "1898", "page": 5, "y": 1474, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 153, "speaker": "康有为", "text": "我强烈主张的那一场震动中华的“维新变法”", "page": 5, "y": 1526, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 154, "speaker": "舞台提示", "text": "[幕外：京剧锣鼓点响起。", "page": 5, "y": 1627, "col": 1, "kind": "stage", "chapter": 1}, {"id": 155, "speaker": "舞台提示", "text": "[多媒体：颐和园“仁寿殿”内", "page": 5, "y": 1679, "col": 1, "kind": "stage", "chapter": 1}, {"id": 156, "speaker": "异禀", "text": "皇上驾到！", "page": 5, "y": 1731, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 157, "speaker": "异禀", "text": "（招呼师兄弟）师兄弟，搬椅子！", "page": 5, "y": 1782, "col": 1, "kind": "dialogue", "chapter": 1}, {"id": 158, "speaker": "舞台提示", "text": "[多媒体：字幕“第二章节圣人觐见明定", "page": 5, "y": 1833, "col": 1, "kind": "stage", "chapter": 2}, {"id": 159, "speaker": "舞台提示", "text": "[康有为，急忙跪倒。", "page": 5, "y": 1937, "col": 1, "kind": "stage", "chapter": 2}, {"id": 160, "speaker": "舞台提示", "text": "[灯光：集中照亮光绪和康有为。", "page": 5, "y": 1988, "col": 1, "kind": "stage", "chapter": 2}, {"id": 161, "speaker": "光绪", "text": "我们见面一个时辰，你对外，却说了一生。", "page": 5, "y": 2040, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 162, "speaker": "康有为", "text": "这一个小时让中国历史有了意义！（问异禀）是一个小时还是一个时辰？", "page": 5, "y": 2091, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 163, "speaker": "异禀", "text": "内务府有记载，一个时辰。一个时辰是两个小时", "page": 6, "y": 294, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 164, "speaker": "光绪", "text": "朕为你夜不能寐，就怕见面不对路", "page": 6, "y": 398, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 165, "speaker": "异禀", "text": "你不能这样看皇上，你只能看皇上的下巴颏。", "page": 6, "y": 449, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 166, "speaker": "康有为", "text": "我的长相，让您失望了？！", "page": 6, "y": 551, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 167, "speaker": "光绪", "text": "你的颜值，的确不高。", "page": 6, "y": 604, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 168, "speaker": "康有为", "text": "你说我再能说，见到皇上总有一些紧张，人总会有一些性格缺陷。", "page": 6, "y": 654, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 169, "speaker": "光绪", "text": "赐座。", "page": 6, "y": 758, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 170, "speaker": "异禀", "text": "皇上给你赐座呢", "page": 6, "y": 809, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 171, "speaker": "康有为", "text": "谢皇上！", "page": 6, "y": 860, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 172, "speaker": "舞台提示", "text": "[康有为，见异禀坐在椅子上，对异禀说。", "page": 6, "y": 912, "col": 0, "kind": "stage", "chapter": 2}, {"id": 173, "speaker": "康有为", "text": "你还不起来", "page": 6, "y": 963, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 174, "speaker": "舞台提示", "text": "[康有为，小心地走到椅子边，激动着。", "page": 6, "y": 1014, "col": 0, "kind": "stage", "chapter": 2}, {"id": 175, "speaker": "康有为", "text": "太珍贵了。", "page": 6, "y": 1066, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 176, "speaker": "舞台提示", "text": "[康有为，坐下。", "page": 6, "y": 1117, "col": 0, "kind": "stage", "chapter": 2}, {"id": 177, "speaker": "光绪", "text": "朕问你，如何兴利？如何挣钱？如何为朝廷财政开源？", "page": 6, "y": 1169, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 178, "speaker": "康有为", "text": "臣拿不出靠谱的方案。谁操过这么大的盘子，我又没有实际的行政运营经验。", "page": 6, "y": 1272, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 179, "speaker": "光绪", "text": "你今天谈的基本是你前面上书朝廷的那些奏章，没有超出范围。有没有新的想法。", "page": 6, "y": 1374, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 180, "speaker": "康有为", "text": "变法！", "page": 6, "y": 1477, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 181, "speaker": "异禀", "text": "变戏法。", "page": 6, "y": 1529, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 182, "speaker": "康有为", "text": "臣不会变戏法，臣只会变法。苟日新，日日新，又日新，变法的关键在于维新当然！更在于皇上的决心！", "page": 6, "y": 1581, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 183, "speaker": "光绪", "text": "朕，实际上是不解渴的", "page": 6, "y": 1734, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 184, "speaker": "康有为", "text": "臣有罪", "page": 6, "y": 1786, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 185, "speaker": "舞台提示", "text": "[康有为，急跪在地", "page": 6, "y": 1836, "col": 0, "kind": "stage", "chapter": 2}, {"id": 186, "speaker": "光绪", "text": "朕给你一个官职吧", "page": 6, "y": 1889, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 187, "speaker": "康有为", "text": "军机大臣！", "page": 6, "y": 1940, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 188, "speaker": "光绪", "text": "总理衙门章京上行走。", "page": 6, "y": 1992, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 189, "speaker": "康有为", "text": "就这么小一个官吗？！", "page": 6, "y": 2043, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 190, "speaker": "异禀", "text": "我听着这官挺大的！", "page": 6, "y": 2094, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 191, "speaker": "光绪", "text": "你才只是个进士。", "page": 6, "y": 243, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 192, "speaker": "康有为", "text": "臣不正搞公车上书嘛，功名是小，维新乃大！", "page": 6, "y": 294, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 193, "speaker": "光绪", "text": "这已经是朕给你的最大官了。", "page": 6, "y": 346, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 194, "speaker": "舞台提示", "text": "[康有为，站起来", "page": 6, "y": 397, "col": 1, "kind": "stage", "chapter": 2}, {"id": 195, "speaker": "康有为", "text": "我可以不做官！但您要让我来主持变法。", "page": 6, "y": 449, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 196, "speaker": "光绪", "text": "中国古代的政治格局，是一套非常完善的政治体系", "page": 6, "y": 500, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 197, "speaker": "康有为", "text": "所以，我想直接绕过官僚阶层，直达天庭，直达皇上您的身边", "page": 6, "y": 604, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 198, "speaker": "光绪", "text": "这是太困难的一件事了。", "page": 6, "y": 707, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 199, "speaker": "异禀", "text": "皇上让你跪下！", "page": 6, "y": 758, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 200, "speaker": "舞台提示", "text": "[康有为，跪下", "page": 6, "y": 809, "col": 1, "kind": "stage", "chapter": 2}, {"id": 201, "speaker": "光绪", "text": "朕早想见你，但你是个六品小官，要让大臣们去见，然后由他们向我汇报。国事维艰，你还有其他具体想法吗？", "page": 6, "y": 861, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 202, "speaker": "康有为", "text": "很简单，把一三品以上，反对变法的都杀掉。变法就可进行。", "page": 6, "y": 1015, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 203, "speaker": "光绪", "text": "就是你这句话，荣禄禀告太后，朝中对你存在两极的看法。", "page": 6, "y": 1117, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 204, "speaker": "康有为", "text": "我知道，恭亲王一直阻挠我，直到他去世。臣与君，才得以见面！", "page": 6, "y": 1220, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 205, "speaker": "光绪", "text": "太漫长的一次等待。", "page": 6, "y": 1323, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 206, "speaker": "康有为", "text": "我还让您失望了，我长得不够英俊", "page": 6, "y": 1374, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 207, "speaker": "光绪", "text": "赐座！", "page": 6, "y": 1426, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 208, "speaker": "康有为", "text": "谢皇上！", "page": 6, "y": 1477, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 209, "speaker": "舞台提示", "text": "[光绪与康有为，并排而坐。", "page": 6, "y": 1528, "col": 1, "kind": "stage", "chapter": 2}, {"id": 210, "speaker": "光绪", "text": "你的文字，太好了！你是个绝顶聪明的读书人。", "page": 6, "y": 1580, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 211, "speaker": "康有为", "text": "君与臣相互仰慕六年之久。", "page": 6, "y": 1683, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 212, "speaker": "光绪", "text": "说你的想法", "page": 6, "y": 1734, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 213, "speaker": "康有为", "text": "皇上，臣找到了一个机会。", "page": 6, "y": 1786, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 214, "speaker": "光绪", "text": "讲！", "page": 6, "y": 1837, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 215, "speaker": "舞台提示", "text": "[康有为，移动椅子靠近光绪", "page": 6, "y": 1888, "col": 1, "kind": "stage", "chapter": 2}, {"id": 216, "speaker": "康有为", "text": "就是在中国漫长的政治演化中有这样一个机会，皇帝会不断地重用自己身边的秘书班子，替代外朝宰相的权利。", "page": 6, "y": 1940, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 217, "speaker": "光绪", "text": "朕对他们本来就不信任。", "page": 6, "y": 2094, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 218, "speaker": "康有为", "text": "这些人做了官，不是贪污腐败，就是觊觎皇位。", "page": 7, "y": 241, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 219, "speaker": "光绪", "text": "对那些高官，历朝的皇帝，都有警具之心", "page": 7, "y": 344, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 220, "speaker": "康有为", "text": "明朝就不设宰相，大学士都是官居五品", "page": 7, "y": 396, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 221, "speaker": "光绪", "text": "雍正皇帝，不信外朝官员，设立军机处", "page": 7, "y": 447, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 222, "speaker": "康有为", "text": "就是在您办公室边上，搞个小房子。", "page": 7, "y": 498, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 223, "speaker": "光绪", "text": "找几个亲近人，咱们办事", "page": 7, "y": 550, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 224, "speaker": "康有为", "text": "是咱们商量妥了，让他们去办。", "page": 7, "y": 600, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 225, "speaker": "光绪", "text": "这不还是军机处嘛！", "page": 7, "y": 652, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 226, "speaker": "康有为", "text": "我们可以搞个变法机构！在皇帝身边直接听命思考，商议改革措施", "page": 7, "y": 703, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 227, "speaker": "光绪", "text": "到了皇上身边，你就有权利了。", "page": 7, "y": 806, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 228, "speaker": "康有为", "text": "先开制度局，再开懋勤殿，绕过军机处，直达中枢", "page": 7, "y": 857, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 229, "speaker": "光绪", "text": "你只能做制度建议。你当不了正根的宰相，就当个秘书头子吧", "page": 7, "y": 960, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 230, "speaker": "康有为", "text": "完美！", "page": 7, "y": 1062, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 231, "speaker": "舞台提示", "text": "[幕外：音乐深沉地响起", "page": 7, "y": 1113, "col": 0, "kind": "stage", "chapter": 2}, {"id": 232, "speaker": "舞台提示", "text": "[普净、异禀，搬上两支话筒", "page": 7, "y": 1165, "col": 0, "kind": "stage", "chapter": 2}, {"id": 233, "speaker": "康有为", "text": "提倡民主思想", "page": 7, "y": 1216, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 234, "speaker": "光绪", "text": "这是康有为，对朕说的第一句话。", "page": 7, "y": 1267, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 235, "speaker": "康有为", "text": "平等看待世界，做观念的强人！", "page": 7, "y": 1318, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 236, "speaker": "光绪", "text": "这是康有为对朕说的第二句话，这是你的科学观吗？", "page": 7, "y": 1370, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 237, "speaker": "康有为", "text": "这是臣，康有为的“看法”！它不是科学，也不是伪科学，它是彰显着大清改革精神的中国知识分子强烈的犹如地震般的震动和反响！我的目的，是向着两千年顽固的封建帝制，下刀子！皇上，您可以把臣的头拿去。", "page": 7, "y": 1472, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 238, "speaker": "光绪", "text": "光绪二十四年四月二十八，晨早五时，颐和园仁寿殿内，窗外鸟鸣初歇，晨光乍现", "page": 7, "y": 1780, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 239, "speaker": "康有为", "text": "大殿内有些初夏的微凉，我与皇上四目交投，他清俊的脸庞，斜睨着目光对我说“", "page": 7, "y": 1882, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 240, "speaker": "光绪", "text": "让顽固守旧的分子和封建官制受到一次前所未有的威胁和挑战", "page": 7, "y": 1985, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 241, "speaker": "康有为", "text": "我大呼，“皇上，开宗明义，圣裁！”皇上轻声说．．", "page": 7, "y": 2087, "col": 0, "kind": "dialogue", "chapter": 2}, {"id": 242, "speaker": "光绪", "text": "但是，不是推翻", "page": 7, "y": 295, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 243, "speaker": "舞台提示", "text": "[光绪，转身往后中央区走，凌乱的椅子挡住光绪的脚步", "page": 7, "y": 346, "col": 1, "kind": "stage", "chapter": 2}, {"id": 244, "speaker": "舞台提示", "text": "[异禀，搬走椅子，帮助光绪清平道路", "page": 7, "y": 449, "col": 1, "kind": "stage", "chapter": 2}, {"id": 245, "speaker": "舞台提示", "text": "[多媒体：中南海“勤政殿”内", "page": 7, "y": 500, "col": 1, "kind": "stage", "chapter": 2}, {"id": 246, "speaker": "舞台提示", "text": "[光绪，在后区坐下。", "page": 7, "y": 552, "col": 1, "kind": "stage", "chapter": 2}, {"id": 247, "speaker": "舞台提示", "text": "[康有为，下跪，灯光澄澈", "page": 7, "y": 603, "col": 1, "kind": "stage", "chapter": 2}, {"id": 248, "speaker": "光绪", "text": "朕颁布“明定国是诏”。国事不定，号令不行。流弊所致，徒蹈积习。朕今特明白宣誓，上下一心，盛行经论，破故有之陋习，立济世之新学，变法维新。努力发奋，大振皇基！", "page": 7, "y": 654, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 249, "speaker": "舞台提示", "text": "[灯光：收掉光绪光区。", "page": 7, "y": 911, "col": 1, "kind": "stage", "chapter": 2}, {"id": 250, "speaker": "康有为", "text": "皇上圣明！臣终于盼到了大清维新的曙光！", "page": 7, "y": 962, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 251, "speaker": "舞台提示", "text": "[幕外：音乐停止", "page": 7, "y": 1013, "col": 1, "kind": "stage", "chapter": 2}, {"id": 252, "speaker": "康有为", "text": "皇上有谋，臣必有略。朝中有儒，民间必有士。呵护新政，康有为在所不辞！", "page": 7, "y": 1064, "col": 1, "kind": "dialogue", "chapter": 2}, {"id": 253, "speaker": "舞台提示", "text": "[幕外：一声磬响。", "page": 7, "y": 1166, "col": 1, "kind": "stage", "chapter": 2}, {"id": 254, "speaker": "舞台提示", "text": "[舞台：恢复法源寺内", "page": 7, "y": 1218, "col": 1, "kind": "stage", "chapter": 2}, {"id": 255, "speaker": "舞台提示", "text": "[康有为，与上场的袁世凯，打了个照面", "page": 7, "y": 1269, "col": 1, "kind": "stage", "chapter": 2}, {"id": 256, "speaker": "舞台提示", "text": "[多媒体：字幕“第三章节冤仇未必业债何生”", "page": 7, "y": 1320, "col": 1, "kind": "stage", "chapter": 3}, {"id": 257, "speaker": "袁世凯", "text": "他们忘了戊戌变法一个重要人物，我，袁世凯", "page": 7, "y": 1423, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 258, "speaker": "康有为", "text": "小师父，有面粉吗？", "page": 7, "y": 1525, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 259, "speaker": "异禀", "text": "没有，有拓片用的滑石粉。", "page": 7, "y": 1577, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 260, "speaker": "康有为", "text": "给我", "page": 7, "y": 1628, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 261, "speaker": "舞台提示", "text": "[康有为，把滑石粉泼到袁世凯脸上。", "page": 7, "y": 1679, "col": 1, "kind": "stage", "chapter": 3}, {"id": 262, "speaker": "袁世凯", "text": "我就是以这样一副形象，粉墨登场的", "page": 7, "y": 1730, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 263, "speaker": "异禀", "text": "你是个坏人", "page": 7, "y": 1782, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 264, "speaker": "袁世凯", "text": "偏见！我是戊戌变法重要人物之一", "page": 7, "y": 1832, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 265, "speaker": "康有为", "text": "你是出卖变法重要人物，没有之一", "page": 7, "y": 1884, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 266, "speaker": "袁世凯", "text": "道德评判无法衡量政治棋局！", "page": 7, "y": 1935, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 267, "speaker": "康有为", "text": "你玷污了中华道德之标准也！", "page": 7, "y": 1986, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 268, "speaker": "袁世凯", "text": "我毕竟是中华历史上称过帝的人。", "page": 7, "y": 2038, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 269, "speaker": "康有为", "text": "你是一个袁大头，是一块钱！", "page": 7, "y": 2089, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 270, "speaker": "袁世凯", "text": "你还能不能放下个人恩怨好好说话！", "page": 8, "y": 233, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 271, "speaker": "康有为", "text": "你就是一块钱。", "page": 8, "y": 285, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 272, "speaker": "袁世凯", "text": "我是戊戌变法重要人物之一！", "page": 8, "y": 336, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 273, "speaker": "康有为", "text": "你是出卖变法重要人物，没有之一", "page": 8, "y": 389, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 274, "speaker": "袁世凯", "text": "我是河南项城人。", "page": 8, "y": 440, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 275, "speaker": "舞台提示", "text": "[幕外：“河南八板”响起", "page": 8, "y": 492, "col": 0, "kind": "stage", "chapter": 3}, {"id": 276, "speaker": "袁世凯", "text": "（河南话）俺，袁世凯。我跟你康有为相识二十一年，共为好友三年。1895年8月，你办强学会的时候，在河南会馆我们初相识，西学东进之风，狂吼般侵蚀大清，对西方宪政的认识，你我亦有相近之处。袁某钦佩你胆力才华，谏言大清！你激昂的学识，给我渺茫的仕途，点亮了一盏灯。我按月薪水二十两，支持“强学会”一次性拿出了五百两。我是靠两年的俸禄支持维新变法。就是因为我认为大清不改，不能有出路！再这样下去，大清，就“去球”了！", "page": 8, "y": 543, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 277, "speaker": "康有为", "text": "昔强学之会，饮酒高谈，坐以齿序，公呼吾为大哥……", "page": 8, "y": 1163, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 278, "speaker": "袁世凯", "text": "（河南话）吾与公，兄弟交也。", "page": 8, "y": 1266, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 279, "speaker": "康有为", "text": "（河南话）你记得我当时的异常激动！", "page": 8, "y": 1318, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 280, "speaker": "袁世凯", "text": "（河南话）你不顾劝阻，信任了俺", "page": 8, "y": 1369, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 281, "speaker": "康有为", "text": "（河南话）我信任了你这个“鳖孙”，你这个窃取神器、取代清廷的人民“鳖孙”！我串音了，全乱了！（广东话）我是广东人，我是南海康有为。", "page": 8, "y": 1421, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 282, "speaker": "舞台提示", "text": "[幕外：广东音乐《雨打芭蕉》响起", "page": 8, "y": 1627, "col": 0, "kind": "stage", "chapter": 3}, {"id": 283, "speaker": "康有为", "text": "然后，就出现了一场倾覆生命的密谋！", "page": 8, "y": 1680, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 284, "speaker": "舞台提示", "text": "[多媒体：字幕“一场倾覆生命的密谋”", "page": 8, "y": 1730, "col": 0, "kind": "stage", "chapter": 3}, {"id": 285, "speaker": "康有为", "text": "一场倾覆生命的密谋！", "page": 8, "y": 1782, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 286, "speaker": "舞台提示", "text": "[幕外：一声剑气的声响", "page": 8, "y": 1834, "col": 0, "kind": "stage", "chapter": 3}, {"id": 287, "speaker": "舞台提示", "text": "[谭嗣同，走出。亮出手枪", "page": 8, "y": 1886, "col": 0, "kind": "stage", "chapter": 3}, {"id": 288, "speaker": "舞台提示", "text": "[袁世凯，拔出手枪，对准谭嗣同", "page": 8, "y": 1937, "col": 0, "kind": "stage", "chapter": 3}, {"id": 289, "speaker": "康有为", "text": "卓如，老师嗓子哑了，你来。", "page": 8, "y": 1989, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 290, "speaker": "舞台提示", "text": "[梁启超，拿枪对准袁世凯", "page": 8, "y": 2040, "col": 0, "kind": "stage", "chapter": 3}, {"id": 291, "speaker": "舞台提示", "text": "[袁世凯，转身架住康有为", "page": 8, "y": 2092, "col": 0, "kind": "stage", "chapter": 3}, {"id": 292, "speaker": "舞台提示", "text": "[舞台上的一切，是异禀的想象。", "page": 8, "y": 233, "col": 1, "kind": "stage", "chapter": 3}, {"id": 293, "speaker": "康有为", "text": "（广东话）一场倾覆生命的密谋！", "page": 8, "y": 284, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 294, "speaker": "普净", "text": "（山东话）异禀，你想得这么激烈吗？", "page": 8, "y": 336, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 295, "speaker": "异禀", "text": "（重庆话）是的，师父。", "page": 8, "y": 389, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 296, "speaker": "袁世凯", "text": "小师父，哪儿人？", "page": 8, "y": 440, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 297, "speaker": "异禀", "text": "（重庆话）我重庆的", "page": 8, "y": 492, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 298, "speaker": "谭嗣同", "text": "（问普净）您呢？", "page": 8, "y": 543, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 299, "speaker": "普净", "text": "（山东话）山东的。", "page": 8, "y": 595, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 300, "speaker": "舞台提示", "text": "[四人，继续对峙。", "page": 8, "y": 647, "col": 1, "kind": "stage", "chapter": 3}, {"id": 301, "speaker": "袁世凯", "text": "（河南话）你们说皆因是我的密谋与出卖，变法失利！你问问那个对面站着的人，你不找我，我能这么倒霉吗？我怎么能让后世一直骂我！你就是我的克星，你知道吗？", "page": 8, "y": 698, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 302, "speaker": "谭嗣同", "text": "好名、恶名都是出名，历史给过你承担的机会", "page": 8, "y": 956, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 303, "speaker": "袁世凯", "text": "（河南话）你能代表历史吗？一个要推翻政府的狂徒，能代表历史吗？！", "page": 8, "y": 1059, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 304, "speaker": "舞台提示", "text": "[梁启超，救下康有为。", "page": 8, "y": 1162, "col": 1, "kind": "stage", "chapter": 3}, {"id": 305, "speaker": "舞台提示", "text": "[袁世凯与谭嗣同对峙。", "page": 8, "y": 1214, "col": 1, "kind": "stage", "chapter": 3}, {"id": 306, "speaker": "普净", "text": "（对异禀）异禀，那后来呢？", "page": 8, "y": 1266, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 307, "speaker": "异禀", "text": "谭嗣同，给了袁世凯一枪", "page": 8, "y": 1318, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 308, "speaker": "舞台提示", "text": "[幕外：枪声。", "page": 8, "y": 1369, "col": 1, "kind": "stage", "chapter": 3}, {"id": 309, "speaker": "普净", "text": "他拿的不是刀吗？", "page": 8, "y": 1421, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 310, "speaker": "异禀", "text": "不是，是枪", "page": 8, "y": 1473, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 311, "speaker": "普净", "text": "再往后，怎么进展？", "page": 8, "y": 1525, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 312, "speaker": "异禀", "text": "我特别不愿意，袁世凯，又给了谭嗣同一枪。", "page": 8, "y": 1576, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 313, "speaker": "舞台提示", "text": "[幕外：枪声。那不是开枪，是一场出卖。", "page": 8, "y": 1627, "col": 1, "kind": "stage", "chapter": 3}, {"id": 314, "speaker": "异禀", "text": "出卖和开枪是一模一样的，没有区别的", "page": 8, "y": 1731, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 315, "speaker": "普净", "text": "异禀，你该醒醒啦。", "page": 8, "y": 1782, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 316, "speaker": "异禀", "text": "我不！", "page": 8, "y": 1834, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 317, "speaker": "舞台提示", "text": "[袁世凯、谭嗣同，走到台前话筒", "page": 8, "y": 1886, "col": 1, "kind": "stage", "chapter": 3}, {"id": 318, "speaker": "袁世凯", "text": "你为什么找到我？", "page": 8, "y": 1937, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 319, "speaker": "谭嗣同", "text": "因为你可以改变历史", "page": 8, "y": 1989, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 320, "speaker": "袁世凯", "text": "我兵力不足七千，我改变不了历史，你高看我了。", "page": 8, "y": 2041, "col": 1, "kind": "dialogue", "chapter": 3}, {"id": 321, "speaker": "谭嗣同", "text": "维新派阵营里，人人希望有所作为。", "page": 9, "y": 242, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 322, "speaker": "袁世凯", "text": "但是，这些人里，没有一位是实权派人物。", "page": 9, "y": 294, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 323, "speaker": "谭嗣同", "text": "权力、兵力，政变的能力，要掌握在自己手里，方是成就作为的前提。", "page": 9, "y": 345, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 324, "speaker": "袁世凯", "text": "谭章京，手下连一支敢死队都没有，你的成功概率几乎是零。", "page": 9, "y": 448, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 325, "speaker": "谭嗣同", "text": "官场里有维新倾向且握有实权的，是湖南巡抚陈宝箴大人。", "page": 9, "y": 550, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 326, "speaker": "袁世凯", "text": "但陈大人只是倾向而已，且势单力孤真是“天公无语对枯棋”", "page": 9, "y": 653, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 327, "speaker": "谭嗣同", "text": "你作为新军统帅！", "page": 9, "y": 756, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 328, "speaker": "袁世凯", "text": "我作为新军统帅！", "page": 9, "y": 807, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 329, "speaker": "谭嗣同", "text": "带着一张假面具。", "page": 9, "y": 858, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 330, "speaker": "袁世凯", "text": "面具下有谁能看出我的忠诚和隐忍。", "page": 9, "y": 910, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 331, "speaker": "谭嗣同", "text": "开明在外，保守在里，骑墙之徒。", "page": 9, "y": 961, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 332, "speaker": "袁世凯", "text": "是我，是历史，让谭章京这个正四品大员提早结束了政治生涯。", "page": 9, "y": 1012, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 333, "speaker": "舞台提示", "text": "[幕外：一记锣声。", "page": 9, "y": 1115, "col": 0, "kind": "stage", "chapter": 3}, {"id": 334, "speaker": "谭嗣同", "text": "你杀的是我的肉身，我将英名驻世，后代传扬", "page": 9, "y": 1166, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 335, "speaker": "袁世凯", "text": "我的孽缘，我的好名声，死在了戊戌年9月28日", "page": 9, "y": 1269, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 336, "speaker": "舞台提示", "text": "[袁世凯，坐在康有为身边。", "page": 9, "y": 1371, "col": 0, "kind": "stage", "chapter": 3}, {"id": 337, "speaker": "谭嗣同", "text": "我要面对的，是陈腐的政治制度。我要挑战的，是陈腐制度下庞大的利益集团！", "page": 9, "y": 1424, "col": 0, "kind": "dialogue", "chapter": 3}, {"id": 338, "speaker": "舞台提示", "text": "[幕外：一阵锣鼓声响起", "page": 9, "y": 1526, "col": 0, "kind": "stage", "chapter": 3}, {"id": 339, "speaker": "舞台提示", "text": "[多媒体：字幕“第四章节慈容懿旨于情于理”", "page": 9, "y": 1577, "col": 0, "kind": "stage", "chapter": 4}, {"id": 340, "speaker": "舞台提示", "text": "[幕外：闪电、雷雨声响起", "page": 9, "y": 1680, "col": 0, "kind": "stage", "chapter": 4}, {"id": 341, "speaker": "舞台提示", "text": "[灯光：变化为老旧的宫廷照片效果。", "page": 9, "y": 1731, "col": 0, "kind": "stage", "chapter": 4}, {"id": 342, "speaker": "舞台提示", "text": "[慈禧，坐在榻上。恭亲王、荣禄、李鸿章、李莲英，站立两厢。", "page": 9, "y": 1782, "col": 0, "kind": "stage", "chapter": 4}, {"id": 343, "speaker": "舞台提示", "text": "[多媒体：雨水连连。", "page": 9, "y": 1885, "col": 0, "kind": "stage", "chapter": 4}, {"id": 344, "speaker": "舞台提示", "text": "[幕外：野猫的叫声。", "page": 9, "y": 1937, "col": 0, "kind": "stage", "chapter": 4}, {"id": 345, "speaker": "舞台提示", "text": "[慈禧，看了一眼异禀，异禀吓得摔了一跤，跑向师父", "page": 9, "y": 1987, "col": 0, "kind": "stage", "chapter": 4}, {"id": 346, "speaker": "异禀", "text": "师父，我害怕。", "page": 9, "y": 2091, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 347, "speaker": "普净", "text": "害怕什么？", "page": 9, "y": 242, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 348, "speaker": "异禀", "text": "慈禧", "page": 9, "y": 294, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 349, "speaker": "普净", "text": "清政府从不宣传慈禧的生活，不知道慈禧的性格，不了解慈禧的兴趣爱好，只是懿旨、慈览和讲话。所以，老佛爷的民间野史泛滥，让人浮想联翩，百姓们是非连绵。我们也不例外。", "page": 9, "y": 344, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 350, "speaker": "舞台提示", "text": "[李莲英、恭亲王，擦着额头上雨水。", "page": 9, "y": 601, "col": 1, "kind": "stage", "chapter": 4}, {"id": 351, "speaker": "异禀", "text": "师父，您见过慈禧？没有。", "page": 9, "y": 653, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 352, "speaker": "袁世凯", "text": "我见过。", "page": 9, "y": 755, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 353, "speaker": "康有为", "text": "她是镇压戊戌变法重要人物，不是之一她是一个妖魔。诡诈阴险，权利心极重，杀人不眨眼", "page": 9, "y": 806, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 354, "speaker": "袁世凯", "text": "您没见过她老人家，就这么编排她。", "page": 9, "y": 960, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 355, "speaker": "康有为", "text": "她杀了我的亲弟弟康广仁。", "page": 9, "y": 1012, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 356, "speaker": "舞台提示", "text": "[康广仁，下场口出现", "page": 9, "y": 1063, "col": 1, "kind": "stage", "chapter": 4}, {"id": 357, "speaker": "舞台提示", "text": "[幕外：一声雷鸣。", "page": 9, "y": 1114, "col": 1, "kind": "stage", "chapter": 4}, {"id": 358, "speaker": "康有为", "text": "菜市口六君子人头落地。国仇家恨于一身，我对她恨之人骨。", "page": 9, "y": 1166, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 359, "speaker": "袁世凯", "text": "所以你编排她", "page": 9, "y": 1269, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 360, "speaker": "康有为", "text": "是的。", "page": 9, "y": 1320, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 361, "speaker": "林旭", "text": "泼妇。", "page": 9, "y": 1372, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 362, "speaker": "舞台提示", "text": "[众臣，看三章京。", "page": 9, "y": 1423, "col": 1, "kind": "stage", "chapter": 4}, {"id": 363, "speaker": "刘光第", "text": "恶妇。", "page": 9, "y": 1475, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 364, "speaker": "康有为", "text": "荡妇！一个阻挠变法把中国推向黑暗的罪魁。", "page": 9, "y": 1526, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 365, "speaker": "舞台提示", "text": "[异禀，随着康有为，念念有词，被普净打断", "page": 9, "y": 1627, "col": 1, "kind": "stage", "chapter": 4}, {"id": 366, "speaker": "异禀", "text": "妖妇。", "page": 9, "y": 1680, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 367, "speaker": "李莲英", "text": "（指异禀）不许在宫里打妄语。", "page": 9, "y": 1731, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 368, "speaker": "普净", "text": "异禀，不要在庙里打妄语。绮语、异语都叫妄语。", "page": 9, "y": 1782, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 369, "speaker": "康有为", "text": "我这叫，臆断", "page": 9, "y": 1885, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 370, "speaker": "普净", "text": "在近代中国，慈禧太后是被多重妖魔化的政治人物。", "page": 9, "y": 1936, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 371, "speaker": "袁世凯", "text": "（指康有为）你还说她生活放浪。", "page": 9, "y": 2039, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 372, "speaker": "杨锐", "text": "一生共有八、九位情人", "page": 9, "y": 2090, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 373, "speaker": "林旭", "text": "恭亲王奕訢、荣禄。", "page": 10, "y": 241, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 374, "speaker": "刘光第", "text": "李鸿章、太监李莲英等。", "page": 10, "y": 293, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 375, "speaker": "异禀", "text": "（对四位大臣）几位爷爷，您们都回去吧。", "page": 10, "y": 344, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 376, "speaker": "李鸿章", "text": "你想了解历史？不能以几种或某种历史观看待她她是一个女人。", "page": 10, "y": 396, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 377, "speaker": "四大臣", "text": "（合）一个非凡的女人。", "page": 10, "y": 499, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 378, "speaker": "舞台提示", "text": "[幕外：雨停，转鸟鸣和畅", "page": 10, "y": 550, "col": 0, "kind": "stage", "chapter": 4}, {"id": 379, "speaker": "舞台提示", "text": "[灯光；集中在慈禧身上。", "page": 10, "y": 602, "col": 0, "kind": "stage", "chapter": 4}, {"id": 380, "speaker": "舞台提示", "text": "[异禀，走向慈禧。", "page": 10, "y": 653, "col": 0, "kind": "stage", "chapter": 4}, {"id": 381, "speaker": "舞台提示", "text": "[多媒体：颐和园内", "page": 10, "y": 705, "col": 0, "kind": "stage", "chapter": 4}, {"id": 382, "speaker": "慈禧", "text": "想听哪段？是想看戊戌变法？还是想听我说话。", "page": 10, "y": 757, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 383, "speaker": "异禀", "text": "我想听您说话", "page": 10, "y": 861, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 384, "speaker": "舞台提示", "text": "[多媒体：“大清版图”，版图上有华夏江山盈然", "page": 10, "y": 911, "col": 0, "kind": "stage", "chapter": 4}, {"id": 385, "speaker": "慈禧", "text": "我身后是一片惶惶然的大清版图。山川、河流、高原、森林、平原、矿产、盆地、园林、庭院、溪水、长江、黄河。幅员辽阔，万里延绵，一幅江山如画。", "page": 10, "y": 1014, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 386, "speaker": "李莲英", "text": "老佛爷，您看那枝春梅", "page": 10, "y": 1220, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 387, "speaker": "李鸿章", "text": "老佛爷，您看那群喜鹊", "page": 10, "y": 1272, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 388, "speaker": "舞台提示", "text": "[幕外：喜鹊鸣叫。", "page": 10, "y": 1323, "col": 0, "kind": "stage", "chapter": 4}, {"id": 389, "speaker": "舞台提示", "text": "[多媒体：“大清版图”恢复。", "page": 10, "y": 1374, "col": 0, "kind": "stage", "chapter": 4}, {"id": 390, "speaker": "荣禄", "text": "太后，您看这幅窗帘。是不是该换一幅了？", "page": 10, "y": 1426, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 391, "speaker": "李莲英", "text": "这是窗帘吗？那是咱大清版图。", "page": 10, "y": 1478, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 392, "speaker": "荣禄", "text": "怎么能拿版图当窗帘呢？", "page": 10, "y": 1529, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 393, "speaker": "李莲英", "text": "那本来就不是窗帘。", "page": 10, "y": 1581, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 394, "speaker": "荣禄", "text": "这也太旧了！找苏州木渎镇的绣娘再绣一幅。", "page": 10, "y": 1633, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 395, "speaker": "舞台提示", "text": "[众人，回望“大清版图”", "page": 10, "y": 1735, "col": 0, "kind": "stage", "chapter": 4}, {"id": 396, "speaker": "慈禧", "text": "大清！植桑、耕田、人民、炊烟，一个美好清明的大园子。爱国己任，爱民己出，列祖列宗！可是糟蹋了。就像是禽兽糟蹋了一位平静温良的女人，蹂躏长了，她不就成了婊子了吗？！还得涂胭脂抹粉，当婊子立牌坊，还不准哭，哭两声还得揍你。你说是吧，荣禄？", "page": 10, "y": 1787, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 397, "speaker": "荣禄", "text": "太后，要搞得这么不舒服，那就得先打禽兽啊", "page": 10, "y": 241, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 398, "speaker": "李鸿章", "text": "我与禽兽相处多年，实在痛苦不堪挥着拳头打了两下子甲午海战，战败了。还是多派几个人去周旋吧，不要打了，又打不过。", "page": 10, "y": 344, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 399, "speaker": "荣禄", "text": "拯救危局必须要练成劲旅！开设武备特科，选拔人才！一年操练；一年后，参军服役；两年后，挑出聪明的送到武备学堂，学习枪炮、骑术、战术、工程知识；三年后，督抚考试，送到京师大学堂；再学三年，然后兵部录用，考出武进士，派往各军营担任将官，改变军中陋习。", "page": 10, "y": 498, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 400, "speaker": "李鸿章", "text": "我听着都慢", "page": 10, "y": 860, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 401, "speaker": "李莲英", "text": "李大人，维新派倒是快，康有为快！", "page": 10, "y": 911, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 402, "speaker": "李鸿章", "text": "所以坊间传言，我是康党。", "page": 10, "y": 962, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 403, "speaker": "荣禄", "text": "您看您自己说了吧", "page": 10, "y": 1014, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 404, "speaker": "李鸿章", "text": "我就是康党。太后，我大清积重难返，就像个臃肿的胖子，拖累得人精疲力尽。我就快消极了，我回贤良寺去了。", "page": 10, "y": 1065, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 405, "speaker": "李莲英", "text": "两位大人，还是没人去解救温良平静的大清", "page": 10, "y": 1220, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 406, "speaker": "舞台提示", "text": "[李鸿章、荣禄，没有反应。", "page": 10, "y": 1323, "col": 1, "kind": "stage", "chapter": 4}, {"id": 407, "speaker": "慈禧", "text": "李大人，贤良寺里蚊子多吧？", "page": 10, "y": 1374, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 408, "speaker": "李鸿章", "text": "秉太后，我和晟一法师研制了一款沉香驱蚊，给您带了两盒，交给李总管了。", "page": 10, "y": 1426, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 409, "speaker": "李莲英", "text": "〈对慈禧）要是晟一法师做的我准交给您，要是他做的，我还怕招蚊子呢！", "page": 10, "y": 1529, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 410, "speaker": "荣禄", "text": "李大人送的东西你怎么能随意处理？", "page": 10, "y": 1632, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 411, "speaker": "李莲英", "text": "我跟他有矛盾", "page": 10, "y": 1684, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 412, "speaker": "舞台提示", "text": "[李鸿章，咳嗽了几声。", "page": 10, "y": 1735, "col": 1, "kind": "stage", "chapter": 4}, {"id": 413, "speaker": "慈禧", "text": "你咳嗽，该吃雪梨，可你又胃寒", "page": 10, "y": 1786, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 414, "speaker": "李鸿章", "text": "承蒙太后挂记，最近饮食尚可，只是腿软日甚。误国者李鸿章告退。", "page": 10, "y": 1838, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 415, "speaker": "舞台提示", "text": "[李鸿章，欲跪", "page": 10, "y": 1941, "col": 1, "kind": "stage", "chapter": 4}, {"id": 416, "speaker": "慈禧", "text": "不要跪了。", "page": 10, "y": 1993, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 417, "speaker": "李莲英", "text": "李大人，太后心疼你腿软。", "page": 10, "y": 2044, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 418, "speaker": "李鸿章", "text": "谢太后。", "page": 10, "y": 2096, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 419, "speaker": "李莲英", "text": "送李大人。", "page": 11, "y": 245, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 420, "speaker": "舞台提示", "text": "[李鸿章，下场，坐到台侧座位。", "page": 11, "y": 295, "col": 0, "kind": "stage", "chapter": 4}, {"id": 421, "speaker": "慈禧", "text": "你们对变法之事可有进言？", "page": 11, "y": 347, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 422, "speaker": "恭亲王", "text": "变法可取，但需必要手段、根基和策略还有缜密的实施方案，和方向性。要学习争取，亦学会妥协。避免一厢情愿和一意孤行", "page": 11, "y": 398, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 423, "speaker": "荣禄", "text": "恭亲王，你这个也很慢", "page": 11, "y": 604, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 424, "speaker": "恭亲王", "text": "太后，请您多拨些军饷，富国强兵，但是切不可随意开战。我大清每一次对外构衅，必多吃一次亏。", "page": 11, "y": 656, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 425, "speaker": "李莲英", "text": "什么是构衅", "page": 11, "y": 810, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 426, "speaker": "恭亲王", "text": "就是结梁子。创深之剧痛，薄海惊心！", "page": 11, "y": 862, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 427, "speaker": "李莲英", "text": "渤海？渤海湾吗？", "page": 11, "y": 913, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 428, "speaker": "荣禄", "text": "就是水浅还掀大浪！底子薄还想挑事儿！", "page": 11, "y": 965, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 429, "speaker": "异禀", "text": "掌嘴。", "page": 11, "y": 1016, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 430, "speaker": "舞台提示", "text": "[李莲英，掌嘴", "page": 11, "y": 1068, "col": 0, "kind": "stage", "chapter": 4}, {"id": 431, "speaker": "李莲英", "text": "哦……", "page": 11, "y": 1119, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 432, "speaker": "恭亲王", "text": "悉请朝廷坚持定见，外修和好，内图富强，或可渐有转机。臣先请告退", "page": 11, "y": 1170, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 433, "speaker": "李莲英", "text": "送恭亲王。", "page": 11, "y": 1273, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 434, "speaker": "舞台提示", "text": "[恭亲王，走下。", "page": 11, "y": 1325, "col": 0, "kind": "stage", "chapter": 4}, {"id": 435, "speaker": "舞台提示", "text": "[慈禧，示意李莲英给荣禄赐座", "page": 11, "y": 1376, "col": 0, "kind": "stage", "chapter": 4}, {"id": 436, "speaker": "李莲英", "text": "（对异禀）给荣禄大人赐座，这椅子谁搬啊？", "page": 11, "y": 1428, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 437, "speaker": "异禀", "text": "（指李莲英）你！", "page": 11, "y": 1480, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 438, "speaker": "李莲英", "text": "我啊？", "page": 11, "y": 1531, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 439, "speaker": "异禀", "text": "对，你去。", "page": 11, "y": 1583, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 440, "speaker": "李莲英", "text": "淘气！", "page": 11, "y": 1634, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 441, "speaker": "舞台提示", "text": "[李莲英，步伐缓慢地走着。", "page": 11, "y": 1685, "col": 0, "kind": "stage", "chapter": 4}, {"id": 442, "speaker": "异禀", "text": "算啦，您年龄太大啦，（指荣禄）你去。", "page": 11, "y": 1736, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 443, "speaker": "荣禄", "text": "我是被赐座的！", "page": 11, "y": 1788, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 444, "speaker": "异禀", "text": "李鸿章，搬椅子。", "page": 11, "y": 1839, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 445, "speaker": "李鸿章", "text": "我最近日渐腿软。", "page": 11, "y": 1891, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 446, "speaker": "异禀", "text": "算啦。师兄弟，搬椅子！", "page": 11, "y": 1943, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 447, "speaker": "舞台提示", "text": "[和尚1，一套拳法后，搬椅子给荣禄。", "page": 11, "y": 1994, "col": 0, "kind": "stage", "chapter": 4}, {"id": 448, "speaker": "荣禄", "text": "（对和尚I)不错，直接保送到武备学堂。", "page": 11, "y": 2045, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 449, "speaker": "慈禧", "text": "（问荣禄）你打算哪日起身？", "page": 11, "y": 2097, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 450, "speaker": "荣禄", "text": "今日是七月二十七，变法93天。朝廷现在情势复杂，臣虽心系太后，可是近日，英俄交恶，恐有战端，累及大沽，亦当早回天津守备。臣想明日动身", "page": 11, "y": 245, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 451, "speaker": "慈禧", "text": "坐火车不坐？", "page": 11, "y": 450, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 452, "speaker": "荣禄", "text": "火车虽快，但臣想要先到小站督察袁世凯练兵事务，火车就不坐了。", "page": 11, "y": 503, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 453, "speaker": "慈禧", "text": "袁世凯今年四十岁。是熟悉练兵，还是熟悉军务？", "page": 11, "y": 605, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 454, "speaker": "李莲英", "text": "戊戌年袁世凯三十九岁。", "page": 11, "y": 708, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 455, "speaker": "袁世凯", "text": "感谢李总管记得我的岁数，但太后您竟然说出了我的虚岁，您说我四十岁我就四十岁", "page": 11, "y": 759, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 456, "speaker": "李莲英", "text": "说得好，太后爱听。", "page": 11, "y": 914, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 457, "speaker": "异禀", "text": "奶奶，（指李莲英）这个爷爷也给他个座吧。", "page": 11, "y": 965, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 458, "speaker": "李莲英", "text": "谢太后，师兄弟，搬椅子。", "page": 11, "y": 1016, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 459, "speaker": "舞台提示", "text": "[和尚1，又一套拳法，搬椅子给李莲英，险些撞倒李总管。", "page": 11, "y": 1068, "col": 1, "kind": "stage", "chapter": 4}, {"id": 460, "speaker": "李莲英", "text": "小师父，太莽撞了。", "page": 11, "y": 1171, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 461, "speaker": "普净", "text": "这个小师父也太莽撞。这些人里，只有袁世凯见过太后。为了见太后，荣禄大人推荐袁世凯看一本曾纪泽大人写的《曾惠敏公日记》，书中详细记录了曾纪泽出使英法前，被太后召见，她老人家说话的方式甚是逻辑。异禀，你演一遍", "page": 11, "y": 1222, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 462, "speaker": "舞台提示", "text": "[异禀，扮演曾纪泽，打开写有曾纪泽的扇子，跪倒在慈禧面前。你打算哪日起身？", "page": 11, "y": 1531, "col": 1, "kind": "stage", "chapter": 4}, {"id": 463, "speaker": "曾纪泽", "text": "臣因公私诸事，须早些出都，拟于九月初四，启程", "page": 11, "y": 1686, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 464, "speaker": "慈禧", "text": "走天津不走？", "page": 11, "y": 1788, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 465, "speaker": "曾纪泽", "text": "须从天津经过，与李鸿章大人商量诸事。", "page": 11, "y": 1840, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 466, "speaker": "慈禧", "text": "李鸿章熟悉洋务，你可与他将诸事细细讨论。", "page": 11, "y": 1892, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 467, "speaker": "异禀", "text": "师父，我想听奶奶自己说。您们几位爷爷都回去吧", "page": 11, "y": 1995, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 468, "speaker": "舞台提示", "text": "[异禀，向慈禧磕头。", "page": 11, "y": 2097, "col": 1, "kind": "stage", "chapter": 4}, {"id": 469, "speaker": "舞台提示", "text": "[四位大臣，回到侧座位。", "page": 12, "y": 237, "col": 0, "kind": "stage", "chapter": 4}, {"id": 470, "speaker": "舞台提示", "text": "[普净，示意异禀过去。", "page": 12, "y": 288, "col": 0, "kind": "stage", "chapter": 4}, {"id": 471, "speaker": "舞台提示", "text": "[舞台：灯光凝聚在慈禧身上。", "page": 12, "y": 340, "col": 0, "kind": "stage", "chapter": 4}, {"id": 472, "speaker": "慈禧", "text": "上海有耽搁否？你携带人员系到上海再奏否？天津到上海要走多少日子？你先到英国？先到法国9国书已办齐交与你否？去住房如何定局？你有事要办的，当与随行大臣随时讨论你出洋后，奏报如何递来？你随行员齐，均须留意管束，不可在外国多事，令洋人轻视你能懂外国语言文字？通行语言。系英国的？法国的？你既能通语言文字，自然便当多了，可不倚仗通事、翻译了。办洋务甚不容易，闻福建又有焚毁教堂房屋之案，将来必又淘气。可不是么，我们此仇何能一日忘记，但是要慢慢自强起来。你方才的话说得很明白，断非杀一人、烧一屋就算报了仇的。这些人明白这理的少。你替国家办这等事，将来这些人必有骂你的时候，你却要任劳任怨。曾国藩真是公忠体国之人。也是国家气运不好，曾国藩就去世了。现在各处大吏总是瞻徇的多。他们都是好的，但都是老班子，新的都赶不上。你现在在总理衙门居住？你办事很细心。你带同文馆学生去否？他们都好否？递国书日子，系由你定？系由他们外国人定？你没到过外国，这些路径事势想必是你听得的？", "page": 12, "y": 393, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 473, "speaker": "舞台提示", "text": "[异禀，给慈禧下跪", "page": 12, "y": 2045, "col": 0, "kind": "stage", "chapter": 4}, {"id": 474, "speaker": "曾纪泽", "text": "（接话）有翻看书籍的，也有问得的。", "page": 12, "y": 2097, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 475, "speaker": "慈禧", "text": "你在香港登船，那船安全否？", "page": 12, "y": 236, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 476, "speaker": "曾纪泽", "text": "臣坐法国轮船，轮船总有载人卸货等事，也只能坐这艘船了。", "page": 12, "y": 288, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 477, "speaker": "舞台提示", "text": "[慈禧，停顿了片刻。", "page": 12, "y": 391, "col": 1, "kind": "stage", "chapter": 4}, {"id": 478, "speaker": "慈禧", "text": "你，跪安吧", "page": 12, "y": 443, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 479, "speaker": "舞台提示", "text": "[幕外：一阵锣鼓声。", "page": 12, "y": 495, "col": 1, "kind": "stage", "chapter": 4}, {"id": 480, "speaker": "舞台提示", "text": "[慈禧，走到侧座。", "page": 12, "y": 547, "col": 1, "kind": "stage", "chapter": 4}, {"id": 481, "speaker": "普净", "text": "感激这本日记，从中学习到太后的语言方式及行思方式，真是本好书。", "page": 12, "y": 599, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 482, "speaker": "众和尚", "text": "太后要是这么个说话方式，那我们的理解全部要调整。再颠覆一个我们的民间想法。我这儿有一本慈禧最爱看的《格致汇编》杂志。", "page": 12, "y": 702, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 483, "speaker": "舞台提示", "text": "[幕外：马勒《第五交响曲》响起。", "page": 12, "y": 907, "col": 1, "kind": "stage", "chapter": 4}, {"id": 484, "speaker": "舞台提示", "text": "[灯光：瞬起", "page": 12, "y": 959, "col": 1, "kind": "stage", "chapter": 4}, {"id": 485, "speaker": "舞台提示", "text": "[舞台：慈禧皇太后，光绪皇帝，分别坐在两把椅子上。", "page": 12, "y": 1011, "col": 1, "kind": "stage", "chapter": 4}, {"id": 486, "speaker": "舞台提示", "text": "[光绪，读一本杂志《格致汇编》。", "page": 12, "y": 1114, "col": 1, "kind": "stage", "chapter": 4}, {"id": 487, "speaker": "舞台提示", "text": "[多媒体：伦敦水晶宫首届世界博览会的幻灯片。", "page": 12, "y": 1166, "col": 1, "kind": "stage", "chapter": 4}, {"id": 488, "speaker": "光绪", "text": "1851年，首次万国博览举行于伦敦，盛况空前。世界二十五国之观者，麇集“水晶宫”巍巍穹顶之下。但见展品十万余，尽列眼前。出自世界各方一万四千人之手。此皆人类文明之冠冕也。其中大半之数，尽属英国，乃该国工业革命之硕果。如大功率蒸汽机、高速汽轮船、起重机、机床，及先进炼钢法、隧道和桥梁模型诸般，眼花缭乱。大英帝国世界工厂之位，非虚得也。英国臣民，成千上万蜂拥而进，泪光莹然，欢欣鼓舞之至。", "page": 12, "y": 1270, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 489, "speaker": "舞台提示", "text": "[多媒体：维多利亚女王照片。", "page": 12, "y": 1838, "col": 1, "kind": "stage", "chapter": 4}, {"id": 490, "speaker": "舞台提示", "text": "[慈禧，偏头看着。", "page": 12, "y": 1890, "col": 1, "kind": "stage", "chapter": 4}, {"id": 491, "speaker": "光绪", "text": "维多利亚女王亲临水晶宫，剪彩博览会，喜极而语：荣光、荣光、无尽的荣光。其不由得不喜！此正维多利亚开辟之时代，天佑英国！国运盛极，前无古人，为有史以来最大之帝国也", "page": 12, "y": 1942, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 492, "speaker": "舞台提示", "text": "[幕外：音乐收，停止。", "page": 13, "y": 290, "col": 0, "kind": "stage", "chapter": 4}, {"id": 493, "speaker": "舞台提示", "text": "[慈禧，摸了摸她没有王冠的旗头。", "page": 13, "y": 342, "col": 0, "kind": "stage", "chapter": 4}, {"id": 494, "speaker": "慈禧", "text": "她如今贵庚几何？", "page": 13, "y": 393, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 495, "speaker": "光绪", "text": "七十有九。", "page": 13, "y": 445, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 496, "speaker": "慈禧", "text": "岁数可以比不上，国力也比不上，是吗？", "page": 13, "y": 497, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 497, "speaker": "光绪", "text": "岁数可以赶上！国力嘛，当然也必须赶上。", "page": 13, "y": 548, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 497001, "speaker": "慈禧", "text": "你很幽默。", "page": 13, "y": 548, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 498, "speaker": "光绪", "text": "那我再给您念一段别的。", "page": 13, "y": 650, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 499, "speaker": "舞台提示", "text": "[多媒体：维多利亚女王换成日本天皇。", "page": 13, "y": 701, "col": 0, "kind": "stage", "chapter": 4}, {"id": 500, "speaker": "舞台提示", "text": "[幕外：日本音乐响起。", "page": 13, "y": 752, "col": 0, "kind": "stage", "chapter": 4}, {"id": 501, "speaker": "光绪", "text": "《日本明治辩证考》。明治天皇，于紫宸殿，立誓约五条。一，破除旧习，倡导维新；二，开议会，通达下情；三，上下一心，推行新政；四，国民一体；五，采万国之良法。日本之盛，由此而始。更有能臣伊藤博文，订立日本宪法，组织国会，兴办工业，引进西方先进技术，国力日强，终于在甲午一役，与清廷决战，一举而胜……", "page": 13, "y": 804, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 501001, "speaker": "慈禧", "text": "你念得很兴奋。", "page": 13, "y": 804, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 502, "speaker": "舞台提示", "text": "[慈禧，起身坐回中间椅子。", "page": 13, "y": 1265, "col": 0, "kind": "stage", "chapter": 4}, {"id": 503, "speaker": "光绪", "text": "不敢", "page": 13, "y": 1317, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 504, "speaker": "慈禧", "text": "你想学他们？", "page": 13, "y": 1368, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 505, "speaker": "光绪", "text": "您怎么看？", "page": 13, "y": 1420, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 506, "speaker": "慈禧", "text": "康有为这本《明治辩证考》写得清楚，你也念得明白。你想学明治维新哪一条？", "page": 13, "y": 1470, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 507, "speaker": "舞台提示", "text": "[康有为，走到舞台前区。", "page": 13, "y": 1573, "col": 0, "kind": "stage", "chapter": 4}, {"id": 508, "speaker": "光绪", "text": "引进欧美工业技术。", "page": 13, "y": 1625, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 509, "speaker": "康有为", "text": "洋务运动早日本明治维新七年，甲午一战而溃，提醒大清不能只学技术", "page": 13, "y": 1676, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 510, "speaker": "舞台提示", "text": "[康有为，走到椅子处落座。", "page": 13, "y": 1779, "col": 0, "kind": "stage", "chapter": 4}, {"id": 511, "speaker": "异禀", "text": "师父，康先生，坐这儿合适嘛？", "page": 13, "y": 1830, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 512, "speaker": "普净", "text": "不合适。", "page": 13, "y": 1881, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 513, "speaker": "异禀", "text": "你过去！", "page": 13, "y": 1933, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 514, "speaker": "舞台提示", "text": "[康有为，随即起身走过舞台", "page": 13, "y": 1984, "col": 0, "kind": "stage", "chapter": 4}, {"id": 515, "speaker": "慈禧", "text": "还有？", "page": 13, "y": 2035, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 516, "speaker": "光绪", "text": "发展现代化军队。", "page": 13, "y": 2087, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 517, "speaker": "舞台提示", "text": "[袁世凯，起身。", "page": 13, "y": 239, "col": 1, "kind": "stage", "chapter": 4}, {"id": 518, "speaker": "袁世凯", "text": "集合'", "page": 13, "y": 291, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 519, "speaker": "袁世凯", "text": "我袁世凯在天津小站，运用德国练兵技术，督练北洋新军，里面有几个不错的年轻军官。", "page": 13, "y": 342, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 520, "speaker": "舞台提示", "text": "[和尚们，列队，形成大清军人阵营，陆续答到。天津，曹锟。河北，王士珍。河北河间，冯国璋安徽合肥，段祺瑞。河南，徐世昌。", "page": 13, "y": 496, "col": 1, "kind": "stage", "chapter": 4}, {"id": 521, "speaker": "袁世凯", "text": "也是俺的老乡，报数！", "page": 13, "y": 855, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 522, "speaker": "众人", "text": "（合月、2、3、4、5！", "page": 13, "y": 906, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 523, "speaker": "袁世凯", "text": "口号！", "page": 13, "y": 958, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 524, "speaker": "众人", "text": "（含糊地，合）晚清晚清，晚清完胜！", "page": 13, "y": 1009, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 525, "speaker": "袁世凯", "text": "从他们脸上我看到的是大清的未来。", "page": 13, "y": 1060, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 526, "speaker": "众人", "text": "（合）大清的希望！", "page": 13, "y": 1112, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 527, "speaker": "舞台提示", "text": "[异禀，喊口号将众人带回。", "page": 13, "y": 1163, "col": 1, "kind": "stage", "chapter": 4}, {"id": 528, "speaker": "慈禧", "text": "这些不是都有了吗？还有？", "page": 13, "y": 1214, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 529, "speaker": "舞台提示", "text": "[康有为、四章京每人上书，手中扇子依次打开。（合）提倡文明开化。（合）支持民生民主化〈合）鼓励文教自由化", "page": 13, "y": 1265, "col": 1, "kind": "stage", "chapter": 4}, {"id": 530, "speaker": "林旭", "text": "提倡生活欧洲化", "page": 13, "y": 1677, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 531, "speaker": "谭嗣同", "text": "反对封建专制化。（合）皇上，你给太后念这段的用意不在于此吧。", "page": 13, "y": 1728, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 532, "speaker": "慈禧", "text": "说关键", "page": 13, "y": 1933, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 533, "speaker": "光绪", "text": "关键在于……", "page": 13, "y": 1984, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 534, "speaker": "舞台提示", "text": "[维新派人士，起身形成知识分子阵营。", "page": 13, "y": 2035, "col": 1, "kind": "stage", "chapter": 4}, {"id": 535, "speaker": "谭嗣同", "text": "关键在于……", "page": 13, "y": 2087, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 536, "speaker": "众人", "text": "（合）我脚下这片支离破碎的山河", "page": 14, "y": 243, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 537, "speaker": "舞台提示", "text": "[多媒体：恢复“大清版图”", "page": 14, "y": 294, "col": 0, "kind": "stage", "chapter": 4}, {"id": 538, "speaker": "谭嗣同", "text": "它有万里长城的雄浑气势", "page": 14, "y": 345, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 539, "speaker": "刘光第", "text": "有日照金山的边境风光。", "page": 14, "y": 396, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 540, "speaker": "康有为", "text": "有大漠孤烟直的苍莽戈壁。", "page": 14, "y": 447, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 541, "speaker": "梁启超", "text": "还有懵懵懂懂未能掌握生死的", "page": 14, "y": 499, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 542, "speaker": "梁林合", "text": "四万万华夏同胞", "page": 14, "y": 550, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 543, "speaker": "谭嗣同", "text": "少年时，我师从刘人熙、欧阳中鹄等人，研习儒学经典，年轻时骑马出塞，游历西北，得见百姓疾苦。年方而立，遭遇甲午海战，国家失败的惨景，使我对新兴资产阶级思想，有了点儿新的认识", "page": 14, "y": 602, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 544, "speaker": "舞台提示", "text": "[谭嗣同，坐到光绪对面的椅子上。", "page": 14, "y": 859, "col": 0, "kind": "stage", "chapter": 4}, {"id": 545, "speaker": "普净", "text": "异禀，谭嗣同坐这儿合适吗？", "page": 14, "y": 910, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 546, "speaker": "异禀", "text": "合适！大哥！你就坐那儿！", "page": 14, "y": 961, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 547, "speaker": "谭嗣同", "text": "我开始写一本叫做《仁学》的书，竭我所能将大乘佛教观点与西方科学、哲学、宗教冶于一炉，希望建立一种对人民对国家有着崭新作用的应用之学。我是为勘破生死而来，为四万万同胞乘愿而至。我愿意协同光绪皇帝放手一搏。我现在北京城南，北半截胡同，浏阳会馆内，急切呼唤这个国家的崛起。", "page": 14, "y": 1013, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 548, "speaker": "舞台提示", "text": "[谭嗣同，起身走回原座位。", "page": 14, "y": 1423, "col": 0, "kind": "stage", "chapter": 4}, {"id": 549, "speaker": "舞台提示", "text": "[梁启超，走出。", "page": 14, "y": 1475, "col": 0, "kind": "stage", "chapter": 4}, {"id": 550, "speaker": "梁启超", "text": "关键在于，我渴望摧毁这个腐朽不堪的旧世界！华夏苍老的政府，基奠丰厚，历史悠久。这个古国，年迈老朽，包袱沉重，无法轻装。如果不换血，它将无法举力行走在地大物博又疆域辽阔的大清版图内。我不知道康先生说的君主立宪制度能不能救中国？", "page": 14, "y": 1527, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 551, "speaker": "舞台提示", "text": "[康有为，起身欲拿走梁启超前话筒。", "page": 14, "y": 1886, "col": 0, "kind": "stage", "chapter": 4}, {"id": 552, "speaker": "梁启超", "text": "先生，我在思考。我心中，有两个自我在激烈地争执。一个说，改良，社会进步，人民安康，待有志男儿来动手拯救。另一个自我说，大清积重难返，无药可救，革命，才是它唯一的出路！我相信达尔文，相信进化论，相信科学与民主是社会发展的公理必然。这个瞬息万变的世界，没有什么是亘古不变，包括我和我的信仰，乃至，予我以信仰的老师们。我目前在北京南海会馆，老师康圣人家中。急待唤醒吾国四千年之大梦", "page": 14, "y": 1937, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 553, "speaker": "舞台提示", "text": "[袁世凯，起身。", "page": 14, "y": 603, "col": 1, "kind": "stage", "chapter": 4}, {"id": 554, "speaker": "异禀", "text": "（对袁世凯）你是坏人，你站起来干嘛？", "page": 14, "y": 654, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 555, "speaker": "袁世凯", "text": "偏见。", "page": 14, "y": 705, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 556, "speaker": "舞台提示", "text": "[袁世凯，走出，向慈禧行礼。", "page": 14, "y": 756, "col": 1, "kind": "stage", "chapter": 4}, {"id": 557, "speaker": "袁世凯", "text": "关键在于，我蜿蜒长城枯毁，泱泱商困民穷。我在李鸿章大人提出的富国强民的基础上改动了一个字，富国强兵！军队是人民的铜墙铁壁，国家的万里长城。可大清遇到的这帮洋孙子，已经不走长城了！他们军备先进、技术精良、逻辑严明、精进勇猛，打我们毫不手软！我们必须筑造新一代的万里长城！就是培养现代化的军队！李鸿章大人是我的恩师！", "page": 14, "y": 808, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 558, "speaker": "舞台提示", "text": "[袁世凯，走向李鸿章。", "page": 14, "y": 1270, "col": 1, "kind": "stage", "chapter": 4}, {"id": 559, "speaker": "袁世凯", "text": "李大人？", "page": 14, "y": 1321, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 560, "speaker": "刘光第", "text": "李大人，日渐腿软。你就说吧。", "page": 14, "y": 1373, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 561, "speaker": "舞台提示", "text": "[袁世凯，走到下场口话筒前。", "page": 14, "y": 1424, "col": 1, "kind": "stage", "chapter": 4}, {"id": 562, "speaker": "袁世凯", "text": "谢大人！您那“求富”为先的理论里曾经提到过军事，但是70年代以后，您就是“求富”在前，军事在后了。现在，我必须在皇上搞变法的章程里，提出，或恳请提出军事的重要性，建设现代化军队，选拔新型军事人才。我，军人袁世凯，要给大清出救国良方，要从我军人的脸上，看到大清的未来！我目前，从天津小站进京，居住法华寺，等待皇上召见，为大清谏言献策、肝脑涂地！", "page": 14, "y": 1475, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 563, "speaker": "舞台提示", "text": "[袁世凯，给光绪磕头。", "page": 14, "y": 1988, "col": 1, "kind": "stage", "chapter": 4}, {"id": 564, "speaker": "光绪", "text": "关键就是，我不想做亡国之君。如何铺展这一幅狼籍的中国版图？大清目前列强环视，民怨积重。甲午战败，戊戌年德国占了胶州湾，俄国占了旅顺港，英国占据威海卫和香港。中国大部分沿海岛屿和城市被西方强国瓜分了。身居偌大的中国版图之上，我怕有一天不能轻而易举地站在“黄河”边上，聆听见壶口澎湃的水声。", "page": 14, "y": 2040, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 565, "speaker": "舞台提示", "text": "[幕外：水浪声此起彼伏。", "page": 15, "y": 546, "col": 0, "kind": "stage", "chapter": 4}, {"id": 566, "speaker": "光绪", "text": "我怕我不能踏云逐月，领略长江蜿蜒的柔情！纵观中国历史，不管朝代多么的兴旺发达，都逃不过300年左右而亡这个劫数，就被起义夺权。", "page": 15, "y": 599, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 567, "speaker": "舞台提示", "text": "[多媒体：水浪平复，依旧“大清版图”", "page": 15, "y": 805, "col": 0, "kind": "stage", "chapter": 4}, {"id": 568, "speaker": "光绪", "text": "大清到我这辈皇帝已经十一代，262年，衰世之征已现。我经常疑虑我为什么诞生在这样一个时间段里，面对百姓，无法救助！面对强国，无法抬头做人！我经常怀疑自己，我不似祖先康熙皇帝开疆扩土，万民拥戴。我不似老祖雍正皇帝大权独揽，朝纲独断。我食不甘味，心急如焚，我夜里做梦都能惊醒！每天凌晨上朝，面对陈腐的三拜九叩，面对所有新策都要呈交慈览，面对我下达的所有指令，都会拖沓延误，都会严重走样，朕只能事必躬亲，亲力亲为！我有些元阳上亢，虚火上升。我要改良政体，寻找希望，挽救国家！我要效法日本，日本已经成功！", "page": 15, "y": 857, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 569, "speaker": "光绪", "text": "引进欧美技术，进行工业化浪潮", "page": 15, "y": 1580, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 570, "speaker": "康有为", "text": "提倡文明开化。", "page": 15, "y": 1631, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 571, "speaker": "林旭", "text": "鼓励生活欧洲化", "page": 15, "y": 1683, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 572, "speaker": "谭嗣同", "text": "发展军队现代化。支持民生民主化，发展文教自由化等。", "page": 15, "y": 1734, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 573, "speaker": "舞台提示", "text": "[慈禧，走到上场口话筒前", "page": 15, "y": 1838, "col": 0, "kind": "stage", "chapter": 4}, {"id": 574, "speaker": "光绪", "text": "改革，使日本成为亚洲第一个走上工业化道路的国家，跻身于世界强国之列。", "page": 15, "y": 1889, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 575, "speaker": "康有为", "text": "亚洲近代化的开端，不是我天朝发起的！", "page": 15, "y": 1993, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 576, "speaker": "光绪", "text": "大清，颜面何在？关键是，改良政体", "page": 15, "y": 2045, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 577, "speaker": "慈禧", "text": "皇帝，质言之，以何等手段推行政体改革？", "page": 15, "y": 2096, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 578, "speaker": "光绪", "text": "维新！", "page": 15, "y": 238, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 579, "speaker": "慈禧", "text": "维新，不是革新", "page": 15, "y": 289, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 580, "speaker": "光绪", "text": "变法！", "page": 15, "y": 341, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 581, "speaker": "慈禧", "text": "变法，不是翻脸。", "page": 15, "y": 392, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 582, "speaker": "光绪", "text": "改革", "page": 15, "y": 444, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 583, "speaker": "慈禧", "text": "改革，不是革命。欲把千年帝制和清朝皇权的改良任务在三年之内便大功告捷？", "page": 15, "y": 495, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 584, "speaker": "舞台提示", "text": "[康有为，走到舞台中央话筒前", "page": 15, "y": 599, "col": 1, "kind": "stage", "chapter": 4}, {"id": 585, "speaker": "康有为", "text": "欧洲变法三百年而治，日本“维新”三十年而强。先开制度局……", "page": 15, "y": 651, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 586, "speaker": "光绪", "text": "我说的，先开制度局！", "page": 15, "y": 753, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 587, "speaker": "康有为", "text": "我说，皇上圣明绝伦！", "page": 15, "y": 805, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 588, "speaker": "光绪", "text": "我说，我大清国土之大，人民之众……", "page": 15, "y": 857, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 589, "speaker": "康有为", "text": "我说，变法三年，可以自立！此后，当蒸蒸日上！皇上说“", "page": 15, "y": 909, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 590, "speaker": "光绪", "text": "富国强民，为万国之首！", "page": 15, "y": 1012, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 591, "speaker": "慈禧", "text": "维新派全变、大变的急进变革主张，造成整个朝野内部结构与清朝社会结构的强烈震荡！使与现存社会有利害关系的社会集团和政治势力，受到前所未有的威胁。百日维新期间，上谕达一百八十四件之多，几乎一天一个新策，全国百姓目不暇接。一天之内，罢黜六个礼部官员。", "page": 15, "y": 1064, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 592, "speaker": "异禀", "text": "师父，礼部是什么官员？官儿很大吗？就是咱们民国的宣传部、教育部、文化部、外交部。", "page": 15, "y": 1426, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 593, "speaker": "慈禧", "text": "皇帝严惩阻挠变法的朝廷官员，操之过急，树敌深重。废除八股，改革科举制度，起小儿学的考试题换了，怎么考还不知道。让吃糠咽菜供孩子读书的全国家庭震荡，令庞大的士人群体引起普遍恐慌。", "page": 15, "y": 1581, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 594, "speaker": "康有为", "text": "现在想起来，似有些疯狂。", "page": 15, "y": 1838, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 595, "speaker": "光绪", "text": "康有为，你站哪家儿说话呢！", "page": 15, "y": 1890, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 596, "speaker": "康有为", "text": "风烛残年，我对这个世界己无顾忌，先帝！", "page": 15, "y": 1942, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 597, "speaker": "舞台提示", "text": "[幕外：大提琴音乐响起。", "page": 15, "y": 1994, "col": 1, "kind": "stage", "chapter": 4}, {"id": 598, "speaker": "舞台提示", "text": "[光绪，落寞地转身，坐到维新派一边。", "page": 15, "y": 2046, "col": 1, "kind": "stage", "chapter": 4}, {"id": 599, "speaker": "舞台提示", "text": "[灯光：变化。", "page": 15, "y": 2097, "col": 1, "kind": "stage", "chapter": 4}, {"id": 600, "speaker": "慈禧", "text": "国家有难，罪在朕躬！千年帝制之祖训，出了事情，赖不得其他，作为一国之君，稳定政局，安抚民情，才是皇帝的断然措施。康有为！", "page": 16, "y": 246, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 601, "speaker": "康有为", "text": "到我了。", "page": 16, "y": 452, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 602, "speaker": "慈禧", "text": "我们不是没有见过面吗？出去！", "page": 16, "y": 503, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 603, "speaker": "舞台提示", "text": "[康有为落寞地走到台侧座位坐下，慈禧走到舞台中间话筒。", "page": 16, "y": 554, "col": 0, "kind": "stage", "chapter": 4}, {"id": 604, "speaker": "慈禧", "text": "君主立宪制，开议会，剪辫子，易装，迁都上海，我没有怪罪他，他妄言“借才”，聘请退休的日本首相伊藤博文，做大清朝廷的顾问，才是核心症结。他提出“和邦”英国、日本、中国、美国，四国参议，建言大清。我断定他，居心叵测，忤逆妄为，祸乱朝政！大清，从先祖打下江山，马踏而得，上百年基业，自当沦为列强之傀儡定他妖言惑众之罪，是轻的。", "page": 16, "y": 656, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 605, "speaker": "光绪", "text": "建立君主立宪制的资本主义社会，是康有为给大清开的一剂救命良方！", "page": 16, "y": 1118, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 606, "speaker": "康有为", "text": "这是日本的一个重要历史阶段。他们拿着天朝的银子扬长而去了！", "page": 16, "y": 1220, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 607, "speaker": "袁世凯", "text": "扬长而去的不只是日本人。还有他们，他们走得太快了，也不等等我。永远忘记一个戊戌变法的重要历史人物，我，袁世凯。康先生您说得对，取鉴日本明治维新之思想", "page": 16, "y": 1323, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 608, "speaker": "舞台提示", "text": "[袁世凯，拿椅子坐到维新派一边", "page": 16, "y": 1579, "col": 0, "kind": "stage", "chapter": 4}, {"id": 609, "speaker": "众人", "text": "（合）改良求变，改良图新，改良维新，维新变法！", "page": 16, "y": 1631, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 610, "speaker": "康有为", "text": "中国的机会，中国难得的机会。皇上，您抓紧！", "page": 16, "y": 1733, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 611, "speaker": "舞台提示", "text": "[舞台两侧两方势力位置对换", "page": 16, "y": 1835, "col": 0, "kind": "stage", "chapter": 4}, {"id": 612, "speaker": "光绪", "text": "学习明治维新，摆脱强国欺压，还我帝国颜面。", "page": 16, "y": 1887, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 613, "speaker": "众人", "text": "（合）皇上“快点”！", "page": 16, "y": 1989, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 614, "speaker": "舞台提示", "text": "[光绪，跑向维新人群", "page": 16, "y": 2040, "col": 0, "kind": "stage", "chapter": 4}, {"id": 615, "speaker": "袁世凯", "text": "他们走得太快了，都跑上了，我就不追了，还是我的兵好。口号！晚清晚清，晚清完胜！", "page": 16, "y": 2091, "col": 0, "kind": "dialogue", "chapter": 4}, {"id": 616, "speaker": "袁世凯", "text": "国家还是人民的国家，以后就叫它民国吧。", "page": 16, "y": 350, "col": 1, "kind": "dialogue", "chapter": 4}, {"id": 617, "speaker": "舞台提示", "text": "[多媒体：慢慢变化为寺庙院墙", "page": 16, "y": 402, "col": 1, "kind": "stage", "chapter": 4}, {"id": 618, "speaker": "舞台提示", "text": "[灯光：照亮新老两方阵营。", "page": 16, "y": 453, "col": 1, "kind": "stage", "chapter": 4}, {"id": 619, "speaker": "舞台提示", "text": "[多媒体：字幕“第五章节各执一词新老有异”", "page": 16, "y": 504, "col": 1, "kind": "stage", "chapter": 5}, {"id": 620, "speaker": "舞台提示", "text": "[慈禧，有些郁闷，看着这两个人，平息了", "page": 16, "y": 607, "col": 1, "kind": "stage", "chapter": 5}, {"id": 621, "speaker": "慈禧", "text": "皇帝，扶桑从东到西，要走多少日子？大清从东到西要走多少日子？扶桑人口多少？大清人口多少？扶桑有多少道、府、县、镇？大清有多少省份、区府、县镇？天皇政府设立多少行政机构？大清朝廷设立多少行政机构？多少部，多少院，多少司，多少处？扶桑有多少官员？大清是多少官员？明治维新，是哪年光景？幕府年。", "page": 16, "y": 709, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 622, "speaker": "慈禧", "text": "强国还在自由资本竞争时期。戊戌变法是如今几何？清光绪二十四年，年代末。", "page": 16, "y": 1170, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 623, "speaker": "慈禧", "text": "强国殖民已经瓜分汹涌。有关国计民生，亦是无论新旧，皇帝都不得，因噎废食。只除旧迎新，造成大清官员恐慌掣肘；只谈守旧，大清又无力变法；皇帝需谨慎处之，平衡发展。变法，岂可几日而得，需皇帝拼尽余生，忍耐智取。而宵小之徒，窃变法之说煽乱之谋，我必不饶之。康有为“．", "page": 16, "y": 1324, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 624, "speaker": "康有为", "text": "康有为，是爱国的！", "page": 16, "y": 1682, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 625, "speaker": "荣禄", "text": "禀报，康有为说，“杀几个二品大员，法亦变也”", "page": 16, "y": 1734, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 626, "speaker": "光绪", "text": "光绪，是爱天下的！", "page": 16, "y": 1836, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 627, "speaker": "李莲英", "text": "皇上9月4日下令将怀塔布等阻挠变法的礼部六堂官全部罢免", "page": 16, "y": 1887, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 628, "speaker": "刘光第", "text": "腐朽不除，海内惊惶！俄国人已经铁路铺开，占据奉天。", "page": 16, "y": 1990, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 629, "speaker": "李鸿章", "text": "9月5日，皇上即任命四位年轻官员为军机章京上行走。", "page": 16, "y": 2092, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 630, "speaker": "谭嗣同", "text": "乱民蠢动，列强侵扰，你们难道视而不见吗！", "page": 17, "y": 292, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 631, "speaker": "恭亲王", "text": "维新冲动，恣意妄为，如此以往，我大清前途未卜", "page": 17, "y": 344, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 632, "speaker": "林旭", "text": "李鸿章，1898年3月27日，你签字把旅顺租借给俄国25年。", "page": 17, "y": 447, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 633, "speaker": "杨锐", "text": "还受贿50万两银子表示满意？！", "page": 17, "y": 550, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 634, "speaker": "李鸿章", "text": "收不收贿，都是一样", "page": 17, "y": 601, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 635, "speaker": "刘光第", "text": "怎么能一样，你怎么谈的？！", "page": 17, "y": 653, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 636, "speaker": "李鸿章", "text": "光绪帝要的是，不惜一切代价“不战”！", "page": 17, "y": 704, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 637, "speaker": "谭嗣同", "text": "那不是皇上的本意。", "page": 17, "y": 756, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 638, "speaker": "李鸿章", "text": "太后，臣有本奏，北京的外交通道需要保护。", "page": 17, "y": 807, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 639, "speaker": "林旭", "text": "英国人正在重划边界，岌岌可危西藏！你还在说北京外交？美、德、英、法等早已建立起资本主义制度的国家位居世界前列，他们的外交你应该学学。而不只是外交，北京外交。还有相对落后的俄国、日本，在发展了资本主义之后，也迅速强大起来。在这种局势下，变革旧的制度和旧的生产力是对的，你那个外交通道要修理！不要再错误下去，学习学习，你知道吗？根源，找根源！", "page": 17, "y": 859, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 640, "speaker": "荣禄", "text": "根源在于，大清是一个朝代概念，帝国是一个文化概念，政权是一个政治概念。国家外交，必须站在自己文化的立场上对外交流疏通，急不得，也要允许有失败，学习西方，是为知己知彼，而不为其他！你们把不同的概念混淆一烩，对旧制度的否定，就是对帝国概念不负历史责任的破坏，举动轻浮急躁，对大清形象已经构成了威胁。若不是存有推翻之心，就是有意而为之！臣有本奏，大清与外辱之冤情需要申诉", "page": 17, "y": 1375, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 641, "speaker": "梁启超", "text": "德国人已经占据了胶州湾。申诉也应该找到根源。英、美等国实现了文官制度改革，整顿了吏治，提高了行政管理效率，我们清廷就应该提高我们的管理效率，才能知道怎样去申诉冤情。资本主义政治制度现在已经日趋完善。这些国家已经提供了示范。明摆着的道理，你们为什么不学习？腐朽！", "page": 17, "y": 1941, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 642, "speaker": "恭亲王", "text": "提高政府管理效力的第一根源，即是要了解自己！地理即是民族概念，朝代即是大清概念，大清即是祖国！大清律法即是祖制！我们始终矢志不渝地学习先进，无论欧洲还是美洲，更有亚洲，和我们自己的传统！我们不选择放弃，我们的坚持，才是大清的生存之路", "page": 17, "y": 448, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 643, "speaker": "舞台提示", "text": "[恭亲王，走到下场口话筒前。", "page": 17, "y": 809, "col": 1, "kind": "stage", "chapter": 5}, {"id": 644, "speaker": "恭亲王", "text": "在我主持朝政的那些年，在太后的支持下，修补内部政治秩序，调整对外战略方针，基本放弃沿袭已久的宗藩朝贡体制，向西方学习，走上霸道政治的道路，以屈辱的姿态韬光养晦，接受条约体制，致力于和平外交，为大清的恢复与发展赢得了一个难得的外部环境", "page": 17, "y": 860, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 645, "speaker": "舞台提示", "text": "[李鸿章，走到舞台中间话筒前", "page": 17, "y": 1221, "col": 1, "kind": "stage", "chapter": 5}, {"id": 646, "speaker": "舞台提示", "text": "[荣禄，走到上场口话筒前", "page": 17, "y": 1273, "col": 1, "kind": "stage", "chapter": 5}, {"id": 647, "speaker": "李鸿章", "text": "和平的外部环境、稳定的国内秩序、相对开放的对外政策，有助于大清的发展", "page": 17, "y": 1324, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 648, "speaker": "荣禄", "text": "经过大约三十年的努力，中国在经济上，修复了因两次鸦片战争和太平天国长毛逆贼所造成的破坏，综合国力与军事力量虽不能与老牌资本主义强国相比，但在亚洲的中心地位与大国气势毕竟得到了相当程度的恢复。即便不是世界上最强大的国家，至少在亚洲尚无其它国家可以取代大清的地位。（合）大清艰难地迈出步人“近代”的脚步。", "page": 17, "y": 1427, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 649, "speaker": "恭亲王", "text": "在大清走向近代的征途中，我起到了一些作用，然而我在提倡大清向西方学习的同时，始终不认为大清在整体上落后于西方，始终相信我们自古相传的政治体制在经过两千年的不断更新后，大有“历史终结”的意味。在我的政治理念中，大清不如西方只是暂时的和局部的，旦我们学习、掌握了西方近代科学技术，大清必将重新崛起，依然是世界政治格局中的重要一局。", "page": 17, "y": 1943, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 650, "speaker": "普净", "text": "1898年5月29日，清光绪二十四年四月初十，夜幕降临时分，位于北京内城什刹海西南角的恭王府内哭声一片。", "page": 18, "y": 551, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 651, "speaker": "舞台提示", "text": "[多媒体：恭王府内景“同德延鳌”额。", "page": 18, "y": 705, "col": 0, "kind": "stage", "chapter": 5}, {"id": 652, "speaker": "袁世凯", "text": "恭王府的主人，大清王朝首席军机兼总理衙门领班大臣恭亲王奕訢，久病不治，撒手人寰，享年六十六岁。", "page": 18, "y": 756, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 653, "speaker": "舞台提示", "text": "[幕外：一记锣鼓", "page": 18, "y": 910, "col": 0, "kind": "stage", "chapter": 5}, {"id": 654, "speaker": "舞台提示", "text": "[光绪、慈禧，起身", "page": 18, "y": 961, "col": 0, "kind": "stage", "chapter": 5}, {"id": 655, "speaker": "舞台提示", "text": "[众臣，下跪；普净，合十。", "page": 18, "y": 1013, "col": 0, "kind": "stage", "chapter": 5}, {"id": 656, "speaker": "恭亲王", "text": "太后，我始终在，大清在，我亦在！我的遗嘱，留意康有为。", "page": 18, "y": 1064, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 657, "speaker": "普净", "text": "6月11日，恭亲王尸骨未寒，光绪帝颁布《明定国是诏》，人们普遍相信，中国政治必将发生某些变化", "page": 18, "y": 1166, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 658, "speaker": "舞台提示", "text": "[多媒体：恢复寺庙院墙", "page": 18, "y": 1320, "col": 0, "kind": "stage", "chapter": 5}, {"id": 659, "speaker": "杨锐", "text": "日本人正在占据朝鲜，窥伺在侧的辽东。将西方资本主义政治学说与中国传统的儒家思想结合起来，成为我们的思想。康先生的思想在你们看来是激进的，但在我们看来还是不够有震撼力，他依然有封建思想残余。我们是不会妥协的。", "page": 18, "y": 1372, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 660, "speaker": "李鸿章", "text": "意识形态属于上层建筑，知识结构即是系统道论儒学体系经历朝历代修缮整理，删繁就简，大而一统！从来是“中和之美”任何关乎民族命运的决定，都是综合指数，紧密操纵。国情下达，不是权利偏好与争夺标准，是超越伦常俗理的极高境界！", "page": 18, "y": 1679, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 661, "speaker": "李鸿章", "text": "臣有本奏，全国饥民流弊，怨声载道，亟须安抚民生。", "page": 18, "y": 2089, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 662, "speaker": "刘光第", "text": "法国人煽动民乱，开始侵袭广西。要不要实行维新变法，要不要改封建君主专制制度为君主立宪制度，要不要改革封建的教育制度。这是一个值得思考的问题一种新思想的产生，应该被客观地看待皇上圣明！皇上圣明！", "page": 18, "y": 294, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 663, "speaker": "刘光第", "text": "你们一味守旧、反对变法，显然是嫉妒！你们要开阔眼界，解放你们的思想，你们再不解放思想，就可以退休了！退休！", "page": 18, "y": 654, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 664, "speaker": "李莲英", "text": "说退休的这一套说法，是关于权力的说法。权力关乎于决定，关乎于权力决定的最高标准，太后是不会让这些老臣们退休的，就是退休了，也罢着不让你们这些没有行政经验的人掌权胡来！太后，请您考虑“、", "page": 18, "y": 859, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 665, "speaker": "李鸿章", "text": "教育经费。", "page": 18, "y": 1167, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 666, "speaker": "荣禄", "text": "军备经费。外交经费如何掂配！时局维艰，举目望之，爱国．“", "page": 18, "y": 1218, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 667, "speaker": "舞台提示", "text": "[幕外：主题变奏音乐起爱国一（合）爱国，皆是困难。", "page": 18, "y": 1371, "col": 1, "kind": "stage", "chapter": 5}, {"id": 668, "speaker": "李莲英", "text": "老佛爷！我们的爱国，是爱大清！他们的爱国，，是爱中华！", "page": 18, "y": 1577, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 669, "speaker": "舞台提示", "text": "[慈禧，起身走到话筒前。", "page": 18, "y": 1730, "col": 1, "kind": "stage", "chapter": 5}, {"id": 670, "speaker": "慈禧", "text": "“惟以一人治天下，岂为天下奉一人。”这是雍正皇帝给我们留下来的祖训。举望世界君主立宪制国家，皇权都属文化形象或国家代言，并无实权。大清上百年而治，列祖列宗勤勉学习汉文化，谨慎处理汉族民心！兢兢业业，从无倦怠。皇上，你爱国，没有实权，还怎么爱国？！你这个聪明孩子，却没有考虑到这核心的危险？！君主立宪，是要交出皇权，和平演变。皇帝，你会成为大清最愚蠢的叛徒！作为清朝第十一代皇帝，去给列祖列宗跪下", "page": 18, "y": 1782, "col": 1, "kind": "dialogue", "chapter": 5}, {"id": 671, "speaker": "光绪", "text": "太后……你干政！", "page": 19, "y": 445, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 672, "speaker": "舞台提示", "text": "[幕外：一记耳光声。", "page": 19, "y": 497, "col": 0, "kind": "stage", "chapter": 5}, {"id": 673, "speaker": "舞台提示", "text": "[灯光：集中到慈禧、光绪处。", "page": 19, "y": 549, "col": 0, "kind": "stage", "chapter": 5}, {"id": 674, "speaker": "李莲英", "text": "这叫，自己亡国", "page": 19, "y": 601, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 675, "speaker": "众大臣", "text": "（合）请太后训政！", "page": 19, "y": 653, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 676, "speaker": "舞台提示", "text": "[幕外：一记锣鼓。", "page": 19, "y": 704, "col": 0, "kind": "stage", "chapter": 5}, {"id": 677, "speaker": "舞台提示", "text": "[守旧派，下跪", "page": 19, "y": 756, "col": 0, "kind": "stage", "chapter": 5}, {"id": 678, "speaker": "异禀", "text": "奶奶，您打了皇上一个大嘴巴吗？", "page": 19, "y": 809, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 679, "speaker": "普净", "text": "野史。1898年9月19日，慈禧太后从颐和园返回西苑，瀛台问罪光绪皇帝。真正的政治核心是慈禧太后。", "page": 19, "y": 860, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 680, "speaker": "舞台提示", "text": "[幕外：京剧锣鼓，、0", "page": 19, "y": 1015, "col": 0, "kind": "stage", "chapter": 5}, {"id": 681, "speaker": "舞台提示", "text": "[光绪，下跪。", "page": 19, "y": 1067, "col": 0, "kind": "stage", "chapter": 5}, {"id": 682, "speaker": "舞台提示", "text": "[灯光，慢慢收掉慈禧光区。", "page": 19, "y": 1119, "col": 0, "kind": "stage", "chapter": 5}, {"id": 683, "speaker": "舞台提示", "text": "[众臣鞠躬，随即下场", "page": 19, "y": 1171, "col": 0, "kind": "stage", "chapter": 5}, {"id": 684, "speaker": "舞台提示", "text": "[灯光：照见谭嗣同和袁世凯。", "page": 19, "y": 1223, "col": 0, "kind": "stage", "chapter": 5}, {"id": 685, "speaker": "舞台提示", "text": "[多媒体：恢复寺庙院墙", "page": 19, "y": 1274, "col": 0, "kind": "stage", "chapter": 5}, {"id": 686, "speaker": "谭嗣同", "text": "迂腐！", "page": 19, "y": 1327, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 687, "speaker": "袁世凯", "text": "可怕！", "page": 19, "y": 1379, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 688, "speaker": "舞台提示", "text": "[光绪，起身走到舞台后区。", "page": 19, "y": 1430, "col": 0, "kind": "stage", "chapter": 5}, {"id": 689, "speaker": "谭嗣同", "text": "这帮老朽，我都懒得搭理你们。两千年来，无非上面是强盗，下面是奴才；上面是霸道，下面是苟且；上面是披着儒家外衣的狼，下面是披着儒家外衣的犬；上面指鹿为马，下面难得糊涂；上面黑，下面厚，主子使唤奴才，奴才献媚主子。“生民之初，本无所谓君臣，则皆民也”，“废君统，倡民主，变不平等为平等”，这就是我们维新的目的。", "page": 19, "y": 1482, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 690, "speaker": "袁世凯", "text": "新、旧？！我看倒是像一帮狂徒和一群老朽；变，得变，不光是变法，还得变大清！", "page": 19, "y": 1949, "col": 0, "kind": "dialogue", "chapter": 5}, {"id": 691, "speaker": "舞台提示", "text": "[灯光：渐渐收去。", "page": 19, "y": 2053, "col": 0, "kind": "stage", "chapter": 5}, {"id": 692, "speaker": "舞台提示", "text": "[多媒体：字幕“第六章节休怀绝念心急难挡”", "page": 19, "y": 2104, "col": 0, "kind": "stage", "chapter": 6}, {"id": 693, "speaker": "舞台提示", "text": "[幕外：电闪雷鸣、雨声。", "page": 19, "y": 289, "col": 1, "kind": "stage", "chapter": 6}, {"id": 694, "speaker": "舞台提示", "text": "[灯光：瞬起，照亮舞台中区一条道路", "page": 19, "y": 340, "col": 1, "kind": "stage", "chapter": 6}, {"id": 695, "speaker": "舞台提示", "text": "[光绪，急跑，梁启超、康有为，随皇帝奔跑外：急促电报机的声音，此起彼伏地响起。", "page": 19, "y": 392, "col": 1, "kind": "stage", "chapter": 6}, {"id": 696, "speaker": "舞台提示", "text": "[灯光：四章京，各自急切地站在自己的光区里", "page": 19, "y": 496, "col": 1, "kind": "stage", "chapter": 6}, {"id": 697, "speaker": "杨锐", "text": "急电！", "page": 19, "y": 601, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 698, "speaker": "林旭", "text": "急电！", "page": 19, "y": 653, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 699, "speaker": "刘光第", "text": "急电！", "page": 19, "y": 704, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 700, "speaker": "谭嗣同", "text": "急电！", "page": 19, "y": 756, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 701, "speaker": "杨锐", "text": "急电两江两广总督张之洞大人！", "page": 19, "y": 808, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 702, "speaker": "林旭", "text": "急电翰林学士王锡藩！", "page": 19, "y": 861, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 703, "speaker": "刘光第", "text": "急电湖南巡抚陈宝箴大人！", "page": 19, "y": 912, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 704, "speaker": "谭嗣同", "text": "急电礼部尚书李端棻大人！", "page": 19, "y": 964, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 705, "speaker": "杨锐", "text": "大人如见：重大事件，我即将被捕，罪名深重。", "page": 19, "y": 1015, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 706, "speaker": "林旭", "text": "大人如见：本人与维新派一并构罪！触及林旭性命！", "page": 19, "y": 1119, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 707, "speaker": "刘光第", "text": "大人如见：维新重创，即将累及光第本人", "page": 19, "y": 1222, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 708, "speaker": "谭嗣同", "text": "大人如见：旧势力反扑，我命在旦夕。", "page": 19, "y": 1274, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 709, "speaker": "杨锐", "text": "恳请大人速想良策，拯救学生杨锐。", "page": 19, "y": 1326, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 710, "speaker": "林旭", "text": "望大人速想良策", "page": 19, "y": 1379, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 711, "speaker": "刘光第", "text": "光第罪名不定，或可重判。", "page": 19, "y": 1430, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 712, "speaker": "谭嗣同", "text": "谭嗣同不求营救。特此禀告大人。", "page": 19, "y": 1481, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 713, "speaker": "杨锐", "text": "求救！", "page": 19, "y": 1534, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 714, "speaker": "林旭", "text": "救命！", "page": 19, "y": 1586, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 715, "speaker": "刘光第", "text": "求救！", "page": 19, "y": 1638, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 716, "speaker": "谭嗣同", "text": "丢人现眼。", "page": 19, "y": 1690, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 717, "speaker": "舞台提示", "text": "[三章京，下场；谭嗣同留在舞台上。", "page": 19, "y": 1740, "col": 1, "kind": "stage", "chapter": 6}, {"id": 718, "speaker": "舞台提示", "text": "[幕外：雷声。", "page": 19, "y": 1792, "col": 1, "kind": "stage", "chapter": 6}, {"id": 719, "speaker": "舞台提示", "text": "[光绪、梁启超、康有为跑向舞台前区。", "page": 19, "y": 1844, "col": 1, "kind": "stage", "chapter": 6}, {"id": 720, "speaker": "舞台提示", "text": "[梁启超、康有为摔倒。", "page": 19, "y": 1896, "col": 1, "kind": "stage", "chapter": 6}, {"id": 721, "speaker": "光绪", "text": "黑暗的，注定失败的一条道路！", "page": 19, "y": 1949, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 722, "speaker": "康有为", "text": "黑暗，让你变得更强，或是粉碎你的希望", "page": 19, "y": 2001, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 723, "speaker": "梁启超", "text": "黑暗的，没有失败的一个方向！", "page": 19, "y": 2053, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 724, "speaker": "光绪", "text": "看得出来，你要逃离这场劫难？！", "page": 19, "y": 2105, "col": 1, "kind": "dialogue", "chapter": 6}, {"id": 725, "speaker": "康有为", "text": "黑暗的出路，是不想破灭的拯救！", "page": 20, "y": 243, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 726, "speaker": "光绪", "text": "逃离！", "page": 20, "y": 295, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 727, "speaker": "康有为", "text": "拯救！", "page": 20, "y": 346, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 728, "speaker": "梁启超", "text": "求生！", "page": 20, "y": 398, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 729, "speaker": "谭嗣同", "text": "殉难！", "page": 20, "y": 449, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 730, "speaker": "舞台提示", "text": "[梁启超，回去抱住谭嗣同。", "page": 20, "y": 501, "col": 0, "kind": "stage", "chapter": 6}, {"id": 731, "speaker": "舞台提示", "text": "[康有为，抱住走出的光绪皇帝外：“清平调”音乐响起，夹杂一声汽笛声。", "page": 20, "y": 552, "col": 0, "kind": "stage", "chapter": 6}, {"id": 732, "speaker": "谭嗣同", "text": "去躲过这场劫难", "page": 20, "y": 655, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 733, "speaker": "梁启超", "text": "我不知道是我的幸运还是不幸！", "page": 20, "y": 706, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 734, "speaker": "光绪", "text": "去，快去逃亡！", "page": 20, "y": 758, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 735, "speaker": "康有为", "text": "我人生最恨的就是临阵脱逃！", "page": 20, "y": 809, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 736, "speaker": "光绪", "text": "我所有的努力。", "page": 20, "y": 861, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 737, "speaker": "谭嗣同", "text": "我所有的人格", "page": 20, "y": 911, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 738, "speaker": "康有为", "text": "我所有的荣誉。", "page": 20, "y": 963, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 739, "speaker": "梁启超", "text": "我所有的理想（合）皆因为一场逃亡和失败。", "page": 20, "y": 1015, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 740, "speaker": "康有为", "text": "噩梦般的逃离。", "page": 20, "y": 1118, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 741, "speaker": "梁启超", "text": "创世的梦想", "page": 20, "y": 1169, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 742, "speaker": "光绪", "text": "我的主张！", "page": 20, "y": 1221, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 743, "speaker": "谭嗣同", "text": "我的人群！", "page": 20, "y": 1272, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 744, "speaker": "舞台提示", "text": "[谭嗣同，走到舞台中央", "page": 20, "y": 1324, "col": 0, "kind": "stage", "chapter": 6}, {"id": 745, "speaker": "谭嗣同", "text": "救驾！", "page": 20, "y": 1375, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 746, "speaker": "舞台提示", "text": "[幕外：汽笛声。", "page": 20, "y": 1427, "col": 0, "kind": "stage", "chapter": 6}, {"id": 747, "speaker": "康有为", "text": "我没有办法传递我们拯救您的过程", "page": 20, "y": 1478, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 748, "speaker": "光绪", "text": "朕没有办法告诉你朕被罢黜的心情。", "page": 20, "y": 1529, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 749, "speaker": "康有为", "text": "救驾！", "page": 20, "y": 1581, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 750, "speaker": "舞台提示", "text": "[幕外：汽笛声。", "page": 20, "y": 1633, "col": 0, "kind": "stage", "chapter": 6}, {"id": 751, "speaker": "舞台提示", "text": "[康有为，掩面而泣。", "page": 20, "y": 1684, "col": 0, "kind": "stage", "chapter": 6}, {"id": 752, "speaker": "康有为", "text": "我即将告别我的民族，告别我的江山，告别我自己。别了，我的江山！我的民族（对光绪下跪）皇上，请让我为您办完最后一件事，再去逃亡！", "page": 20, "y": 1735, "col": 0, "kind": "dialogue", "chapter": 6}, {"id": 753, "speaker": "舞台提示", "text": "[康有为，深深鞠躬。", "page": 20, "y": 1941, "col": 0, "kind": "stage", "chapter": 6}, {"id": 754, "speaker": "舞台提示", "text": "[灯光：收去光绪、康有为。", "page": 20, "y": 1993, "col": 0, "kind": "stage", "chapter": 6}, {"id": 755, "speaker": "舞台提示", "text": "[康有为、光绪，下场", "page": 20, "y": 2044, "col": 0, "kind": "stage", "chapter": 6}, {"id": 756, "speaker": "舞台提示", "text": "[多媒体：字幕“第七章节法源寺内曾经结拜”", "page": 20, "y": 2095, "col": 0, "kind": "stage", "chapter": 7}, {"id": 757, "speaker": "舞台提示", "text": "[谭嗣同、梁启超站在舞台中区，干净、落寞。", "page": 20, "y": 296, "col": 1, "kind": "stage", "chapter": 7}, {"id": 758, "speaker": "舞台提示", "text": "[多媒体：墙体后，显出寺庙大殿。", "page": 20, "y": 348, "col": 1, "kind": "stage", "chapter": 7}, {"id": 759, "speaker": "梁启超", "text": "（哭着问谭嗣同）是法源寺的名字好，还是悯忠寺的名字好？", "page": 20, "y": 399, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 760, "speaker": "谭嗣同", "text": "袁崇焕袁大督师，当年就停灵悯忠寺。法源寺对生者行道，悯忠寺，对死者有情。", "page": 20, "y": 502, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 761, "speaker": "梁启超", "text": "袁督师一代名将凌迟处死，悯忠、悯忠，悯出大恩情！", "page": 20, "y": 605, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 762, "speaker": "谭嗣同", "text": "我说的情，不是世俗伦常之情，而是大慈悲。", "page": 20, "y": 708, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 763, "speaker": "梁启超", "text": "请用佛理给我解释你说的大慈悲？！", "page": 20, "y": 759, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 764, "speaker": "谭嗣同", "text": "古今志士仁人，出世以后，无不现身五浊恶世，正是佛所渭乘本愿而出。而仁人志士之舍身，正是佛所说的，以无我相，去救众生而引刀一快！", "page": 20, "y": 810, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 765, "speaker": "舞台提示", "text": "[幕外：音乐收，下雨声。", "page": 20, "y": 1016, "col": 1, "kind": "stage", "chapter": 7}, {"id": 766, "speaker": "梁启超", "text": "袁督师被利刀碎肉，深受奇冤，如何引刀", "page": 20, "y": 1068, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 767, "speaker": "谭嗣同", "text": "袁都师既然料到会身遭此难，就只能挺胸受刃，尽忠大明！这就是大慈悲！", "page": 20, "y": 1170, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 768, "speaker": "梁启超", "text": "原来慈悲是这么彻底、极致，对自己这么残酷，我还以为慈悲就是善良", "page": 20, "y": 1274, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 769, "speaker": "谭嗣同", "text": "慈悲，勇猛多了！", "page": 20, "y": 1377, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 770, "speaker": "舞台提示", "text": "[幕外：一声磬响。", "page": 20, "y": 1428, "col": 1, "kind": "stage", "chapter": 7}, {"id": 771, "speaker": "梁启超", "text": "若他日推行变法，大难临头！我自认慈悲不了，我怕死。你呢？！", "page": 20, "y": 1480, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 772, "speaker": "谭嗣同", "text": "我也怕！但是，是我的肉身怕，我的肉身，并非真正的我。所谓，目中有身，心中无身，把自己变成虚妄，肉身亦成虚妄！虚妄过后，一无所恋，一无所惜。灵魂驻世，把妄成真，这才是佛教正解！", "page": 20, "y": 1582, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 773, "speaker": "梁启超", "text": "仁兄，是真正的佛菩萨！我在为宵小的生死而苦恼，仁兄却把自己看成了无，进退疾徐，从容无量，菩萨境界！小弟，求以大哥结拜！", "page": 20, "y": 1839, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 774, "speaker": "谭嗣同", "text": "（看了梁启超一会儿）好！", "page": 20, "y": 2045, "col": 1, "kind": "dialogue", "chapter": 7}, {"id": 775, "speaker": "舞台提示", "text": "[幕外：音乐响起“清平调”", "page": 20, "y": 2096, "col": 1, "kind": "stage", "chapter": 7}, {"id": 776, "speaker": "舞台提示", "text": "[谭嗣同，梁启超跪拜。", "page": 21, "y": 239, "col": 0, "kind": "stage", "chapter": 7}, {"id": 777, "speaker": "梁启超", "text": "你老兄和我萍水相逢！", "page": 21, "y": 291, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 778, "speaker": "谭嗣同", "text": "相逢于古庙，悯忠阁。", "page": 21, "y": 342, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 779, "speaker": "梁启超", "text": "相逢于法源寺，大雄宝殿", "page": 21, "y": 394, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 780, "speaker": "谭嗣同", "text": "诸佛菩萨面前。", "page": 21, "y": 445, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 781, "speaker": "梁启超", "text": "乃至十八罗汉为证。（合）两人缘定三生，积健为雄，共参华严，一真法界。", "page": 21, "y": 497, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 782, "speaker": "梁启超", "text": "投契如此“", "page": 21, "y": 701, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 783, "speaker": "谭嗣同", "text": "快慰平生。", "page": 21, "y": 753, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 784, "speaker": "梁启超", "text": "我小你九岁", "page": 21, "y": 804, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 785, "speaker": "谭嗣同", "text": "我即为兄长。", "page": 21, "y": 855, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 786, "speaker": "谭嗣同", "text": "（对梁启超）只怕，我不要辜负你", "page": 21, "y": 907, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 787, "speaker": "梁启超", "text": "（对谭嗣同）你这种人，一生都不会辜负人，我灵着呢，只有小弟的便宜可占。大哥！", "page": 21, "y": 959, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 788, "speaker": "谭嗣同", "text": "庙里结拜，当叫师兄。", "page": 21, "y": 1062, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 789, "speaker": "梁启超", "text": "师兄！咱师父是谁？", "page": 21, "y": 1113, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 790, "speaker": "谭嗣同", "text": "释迦牟尼。", "page": 21, "y": 1165, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 791, "speaker": "舞台提示", "text": "[幕外：一声磬响。", "page": 21, "y": 1216, "col": 0, "kind": "stage", "chapter": 7}, {"id": 792, "speaker": "舞台提示", "text": "[谭嗣同，站起身。", "page": 21, "y": 1267, "col": 0, "kind": "stage", "chapter": 7}, {"id": 793, "speaker": "舞台提示", "text": "[梁启超，磕头，随即站起身。", "page": 21, "y": 1319, "col": 0, "kind": "stage", "chapter": 7}, {"id": 794, "speaker": "谭嗣同", "text": "想起他，就是他年轻时的样子，他是位王子，俗名“乔达摩．悉达多”，他不是泥胎的塑像，是了悟宇宙真理和真相的觉者，革命者，思想家，是在印度等级森严的时期，提出众生平等的佛", "page": 21, "y": 1370, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 795, "speaker": "舞台提示", "text": "[谭嗣同，下场", "page": 21, "y": 1627, "col": 0, "kind": "stage", "chapter": 7}, {"id": 796, "speaker": "梁启超", "text": "想起他，就是他年轻时的样子。我知道了悉达多，结识了复生兄，跟随康先生。我参加了戊戌变法，成为了我想成为的后世传颂的中国思想改良者。我没有做先驱，没有因为哪一场改革丧命。我是幸运又不幸的人。幸运的是，结拜了佛门师兄谭嗣同，和三个为变法而死的军机章京。", "page": 21, "y": 1679, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 797, "speaker": "舞台提示", "text": "[三章京，上场。", "page": 21, "y": 2038, "col": 0, "kind": "stage", "chapter": 7}, {"id": 798, "speaker": "梁启超", "text": "我也经过了灾难最深、最重的国运，一个幸存者，这个国家我必须去救。不幸的是，我失败了！虽然我屡战，还是屡败。我想师兄，谭嗣同。", "page": 21, "y": 2090, "col": 0, "kind": "dialogue", "chapter": 7}, {"id": 799, "speaker": "舞台提示", "text": "[多媒体：字幕“第八章节救驾保命两者兼得”", "page": 21, "y": 391, "col": 1, "kind": "stage", "chapter": 8}, {"id": 800, "speaker": "舞台提示", "text": "[幕外：音乐收，远处狗叫声。", "page": 21, "y": 495, "col": 1, "kind": "stage", "chapter": 8}, {"id": 801, "speaker": "舞台提示", "text": "[众和尚，搬椅子给四章京，四章京落座。", "page": 21, "y": 546, "col": 1, "kind": "stage", "chapter": 8}, {"id": 802, "speaker": "舞台提示", "text": "[灯光：瞬起", "page": 21, "y": 599, "col": 1, "kind": "stage", "chapter": 8}, {"id": 803, "speaker": "舞台提示", "text": "[多媒体：“南海会馆”石匾", "page": 21, "y": 649, "col": 1, "kind": "stage", "chapter": 8}, {"id": 804, "speaker": "舞台提示", "text": "[杨锐、林旭、刘光第，紧张地哆嗦着，牙齿颤动", "page": 21, "y": 701, "col": 1, "kind": "stage", "chapter": 8}, {"id": 805, "speaker": "舞台提示", "text": "[刘光第，陡然站起。", "page": 21, "y": 803, "col": 1, "kind": "stage", "chapter": 8}, {"id": 806, "speaker": "刘光第", "text": "莫慌！", "page": 21, "y": 855, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 807, "speaker": "舞台提示", "text": "〔林旭，陡然站起。", "page": 21, "y": 907, "col": 1, "kind": "stage", "chapter": 8}, {"id": 808, "speaker": "林旭", "text": "莫慌！", "page": 21, "y": 959, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 809, "speaker": "舞台提示", "text": "[杨锐，陡然站起", "page": 21, "y": 1009, "col": 1, "kind": "stage", "chapter": 8}, {"id": 810, "speaker": "杨锐", "text": "莫慌！", "page": 21, "y": 1062, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 811, "speaker": "舞台提示", "text": "[谭嗣同，陡然站起", "page": 21, "y": 1113, "col": 1, "kind": "stage", "chapter": 8}, {"id": 812, "speaker": "异禀", "text": "你是英雄，你不能站起来", "page": 21, "y": 1165, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 813, "speaker": "谭嗣同", "text": "莫慌！", "page": 21, "y": 1216, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 814, "speaker": "舞台提示", "text": "[谭嗣同，落座。", "page": 21, "y": 1267, "col": 1, "kind": "stage", "chapter": 8}, {"id": 815, "speaker": "杨锐", "text": "我致电张之洞大人，没有详表，只求拯救。", "page": 21, "y": 1318, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 816, "speaker": "刘光第", "text": "我急电了湖南巡抚陈宝箴大人，不想求救，还是求救！", "page": 21, "y": 1370, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 817, "speaker": "林旭", "text": "致电我的推荐人王锡藩大人，很简单，救命！", "page": 21, "y": 1474, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 818, "speaker": "谭嗣同", "text": "我致电礼部尚书李端大人，谭嗣同不求营救，准备殉啡！", "page": 21, "y": 1525, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 819, "speaker": "舞台提示", "text": "[三章京，被谭嗣同的话，惊吓起身，与谭嗣同拉开距离", "page": 21, "y": 1626, "col": 1, "kind": "stage", "chapter": 8}, {"id": 820, "speaker": "谭嗣同", "text": "（对异禀）可以吧", "page": 21, "y": 1730, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 821, "speaker": "异禀", "text": "好极了。", "page": 21, "y": 1782, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 822, "speaker": "谭嗣同", "text": "（问梁启超）卓如，你呢？", "page": 21, "y": 1833, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 823, "speaker": "梁启超", "text": "我没有判断，我可生，也可以死。哥……", "page": 21, "y": 1884, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 824, "speaker": "异禀", "text": "〈对梁启超）我俩太像了，你就是我。", "page": 21, "y": 1936, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 825, "speaker": "舞台提示", "text": "[刘光第，回到座位。", "page": 21, "y": 1987, "col": 1, "kind": "stage", "chapter": 8}, {"id": 826, "speaker": "刘光第", "text": "事情还没有到不可收拾的地步。", "page": 21, "y": 2039, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 827, "speaker": "林旭", "text": "（依然紧张着）我们目前，还没出事！", "page": 21, "y": 2090, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 828, "speaker": "谭嗣同", "text": "看看你们这副贪生怕死的样子，如果让皇上知道了，他该做何感想", "page": 22, "y": 247, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 829, "speaker": "舞台提示", "text": "[四章京、梁启超回头看向后区光绪，然后集体再看向杨锐。", "page": 22, "y": 350, "col": 0, "kind": "stage", "chapter": 8}, {"id": 830, "speaker": "谭嗣同", "text": "皇上的密诏，你再念念。", "page": 22, "y": 453, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 831, "speaker": "舞台提示", "text": "[杨锐，打开“密诏”念着诏书。", "page": 22, "y": 504, "col": 0, "kind": "stage", "chapter": 8}, {"id": 832, "speaker": "舞台提示", "text": "[光绪帝，从黑暗中走出，念着自己的诏书。", "page": 22, "y": 556, "col": 0, "kind": "stage", "chapter": 8}, {"id": 833, "speaker": "舞台提示", "text": "[二人，几乎同时念着“密诏”", "page": 22, "y": 608, "col": 0, "kind": "stage", "chapter": 8}, {"id": 834, "speaker": "光杨合", "text": "但必欲朕一早痛切降旨，将旧法尽变而尽黜此辈昏庸之人，则朕之权力，实有未足。果始如此，则朕位不能保，何况其他？", "page": 22, "y": 660, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 835, "speaker": "杨锐", "text": "（不信）朕位不能保，何况其他……", "page": 22, "y": 814, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 836, "speaker": "刘光第", "text": "千真万确！", "page": 22, "y": 866, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 837, "speaker": "林旭", "text": "皇上的位子不保了！", "page": 22, "y": 917, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 838, "speaker": "刘光第", "text": "我一直不信，皇上没实权。", "page": 22, "y": 968, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 839, "speaker": "谭嗣同", "text": "还有一个人列席旁听。", "page": 22, "y": 1020, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 840, "speaker": "舞台提示", "text": "[袁世凯，打开写有“徐世昌”的扇子，走过四章京", "page": 22, "y": 1071, "col": 0, "kind": "stage", "chapter": 8}, {"id": 841, "speaker": "袁世凯", "text": "袁世凯的心腹，徐世昌列会", "page": 22, "y": 1175, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 842, "speaker": "林旭", "text": "徐世昌，号菊人", "page": 22, "y": 1227, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 843, "speaker": "梁启超", "text": "噢，葉花的菊", "page": 22, "y": 1278, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 844, "speaker": "林旭", "text": "菊人，河南人。袁世凯的心腹谋士，一文一武，可谓一生盟友，互为同道。谁叫他来的？", "page": 22, "y": 1330, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 845, "speaker": "舞台提示", "text": "[灯光：照亮拿着“徐世昌”扇子的袁世凯", "page": 22, "y": 1483, "col": 0, "kind": "stage", "chapter": 8}, {"id": 846, "speaker": "袁世凯", "text": "后世没有记载", "page": 22, "y": 1535, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 847, "speaker": "杨锐", "text": "天大的机密，皇上“密诏”这么机密的事，（向康有为）您叫他来的？", "page": 22, "y": 1587, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 848, "speaker": "康有为", "text": "变法之初我们很好，他称呼我大哥，我信任过这个“鳖孙”。（向袁世凯）目前您不在场，请回避。", "page": 22, "y": 1690, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 849, "speaker": "袁世凯", "text": "袁世凯心腹徐世昌，依然列会！", "page": 22, "y": 1844, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 850, "speaker": "舞台提示", "text": "[袁世凯，把扇子给杨锐，下场。", "page": 22, "y": 1895, "col": 0, "kind": "stage", "chapter": 8}, {"id": 851, "speaker": "舞台提示", "text": "[梁启超，问康有为。", "page": 22, "y": 1947, "col": 0, "kind": "stage", "chapter": 8}, {"id": 852, "speaker": "舞台提示", "text": "[康有为，走出。", "page": 22, "y": 1999, "col": 0, "kind": "stage", "chapter": 8}, {"id": 853, "speaker": "梁启超", "text": "您叫他来的？", "page": 22, "y": 2051, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 854, "speaker": "康有为", "text": "后世很少提起，我觉得耻辱问谭嗣同", "page": 22, "y": 2102, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 855, "speaker": "舞台提示", "text": "[幕外：一记锣鼓", "page": 22, "y": 246, "col": 1, "kind": "stage", "chapter": 8}, {"id": 856, "speaker": "谭嗣同", "text": "我没有能力留下这场密谋的文字记载", "page": 22, "y": 298, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 857, "speaker": "普净", "text": "皇上，把密诏交由杨锐带出宫，到变法失败，整整13天……", "page": 22, "y": 350, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 858, "speaker": "康有为", "text": "此人到底是谁请的？", "page": 22, "y": 453, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 859, "speaker": "梁启超", "text": "他不是您请的吗？您分明写道：召卓如来，经画救上之策。袁幕府徐菊人亦来，吾乃相与痛哭以感动之。徐菊人亦哭，于是大众痛哭不成声。是《康南海自编年谱（外二种）》，中华书局出版的。", "page": 22, "y": 504, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 860, "speaker": "康有为", "text": "那是我写的，但也不是我写的。书里面怎么会有真实的历史呢？历史都是迷障丛生，乱云飞渡，但我仍从容", "page": 22, "y": 761, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 861, "speaker": "谭嗣同", "text": "杨锐，你为什么没有把皇上的亲笔密诏拿出来？", "page": 22, "y": 917, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 862, "speaker": "刘光第", "text": "皇上是七月三十把密诏交给你，为什么迟两天才给我们看。", "page": 22, "y": 1019, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 863, "speaker": "杨锐", "text": "我一直在帮皇上出主意！", "page": 22, "y": 1122, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 864, "speaker": "谭嗣同", "text": "那主意呢？", "page": 22, "y": 1174, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 865, "speaker": "杨锐", "text": "没有啊。所以才拿出来，让大家一起想办法！", "page": 22, "y": 1225, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 866, "speaker": "刘光第", "text": "正本呢？", "page": 22, "y": 1277, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 867, "speaker": "杨锐", "text": "在我家。", "page": 22, "y": 1329, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 868, "speaker": "刘光第", "text": "回家取", "page": 22, "y": 1380, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 869, "speaker": "杨锐", "text": "它不能示人", "page": 22, "y": 1431, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 870, "speaker": "林旭", "text": "是吗？可是这么重要的东西你拿个副本给我们，谁知道是真的还是假的？再念一遍！", "page": 22, "y": 1483, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 871, "speaker": "刘光第", "text": "再念一遍作甚？", "page": 22, "y": 1586, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 872, "speaker": "林旭", "text": "说不定是你念错了，或是我们听错了？", "page": 22, "y": 1638, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 873, "speaker": "舞台提示", "text": "[刘光第，瞪了林旭一眼", "page": 22, "y": 1689, "col": 1, "kind": "stage", "chapter": 8}, {"id": 874, "speaker": "刘光第", "text": "（向梁启超）你念！", "page": 22, "y": 1740, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 875, "speaker": "舞台提示", "text": "[梁启超，用广东话念“密诏”", "page": 22, "y": 1792, "col": 1, "kind": "stage", "chapter": 8}, {"id": 876, "speaker": "梁启超", "text": "但必欲朕，一早痛切降旨，将旧法尽变而尽黜此辈昏庸之人，则朕之权力，实有未足。果始如此，则朕位不能保，何况其他？", "page": 22, "y": 1843, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 877, "speaker": "林旭", "text": "那天卓如要不是因为官话讲得不好，皇上就不会给他那么小的官", "page": 22, "y": 1998, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 878, "speaker": "梁启超", "text": "（向林旭）我怎么讲得不好了？是皇上他没有听懂嘛！", "page": 22, "y": 2101, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 879, "speaker": "刘光第", "text": "你都和皇上说什么来着？", "page": 23, "y": 290, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 880, "speaker": "梁启超", "text": "（广东话）一曰理想，二曰热诚，三曰胆气。卓如寄托皇上，胸襟壮阔，挫败旧臣，戊戌维新，二十世纪新中国史开宗明义第一章也！", "page": 23, "y": 341, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 881, "speaker": "杨锐", "text": "卓如啊，不说官话怎么行啊！", "page": 23, "y": 548, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 882, "speaker": "舞台提示", "text": "[梁启超，跪向光绪", "page": 23, "y": 599, "col": 0, "kind": "stage", "chapter": 8}, {"id": 883, "speaker": "光绪", "text": "说得真好，朕一句没听懂。鉴于你的口才有碍，学识尚好，朕赏你六品衔，负责办理京师大学堂译书局事物。", "page": 23, "y": 651, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 884, "speaker": "梁启超", "text": "谢皇上！", "page": 23, "y": 806, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 885, "speaker": "杨锐", "text": "卓如，不学官话，怎么行。", "page": 23, "y": 857, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 886, "speaker": "林旭", "text": "（对梁启超）我比你强。", "page": 23, "y": 909, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 887, "speaker": "舞台提示", "text": "[幕外：锣鼓一响", "page": 23, "y": 960, "col": 0, "kind": "stage", "chapter": 8}, {"id": 888, "speaker": "舞台提示", "text": "[林旭，跪向光绪", "page": 23, "y": 1012, "col": 0, "kind": "stage", "chapter": 8}, {"id": 889, "speaker": "林旭", "text": "（福建话）皇上！我是福建人，皇上听不听得懂我的福建话啊？", "page": 23, "y": 1063, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 890, "speaker": "光绪", "text": "我当然听不懂！", "page": 23, "y": 1167, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 891, "speaker": "林旭", "text": "我文字好写你看！", "page": 23, "y": 1218, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 892, "speaker": "舞台提示", "text": "[多媒体：字幕“拥护皇上颁布的．明定国是'诏书，发起在京的福建维新人士，成立闽学会，与广东、四川、浙江、陕西等学会，互通信息。旧法不改，不足以兴中华，您叫干啥就干啥！救亡图存，振兴中华！”", "page": 23, "y": 1270, "col": 0, "kind": "stage", "chapter": 8}, {"id": 893, "speaker": "异禀", "text": "拥护皇上颁布的“明定国是”诏书！发起在京的福建维新人士，成立闽学会，与广东、四川、浙江、陕西等学会，互通信息旧法不改，不足以兴中华，您叫干啥就干啥！救亡图存，振兴中华！", "page": 23, "y": 1528, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 894, "speaker": "光绪", "text": "林旭，诗文俱佳，堪称当代李贺！几句话，简历、决心、才华，都给朕看清楚了，朕心大悦。", "page": 23, "y": 1786, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 895, "speaker": "林旭", "text": "谢皇上。", "page": 23, "y": 1941, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 896, "speaker": "舞台提示", "text": "[林旭，回到椅子坐下。", "page": 23, "y": 1992, "col": 0, "kind": "stage", "chapter": 8}, {"id": 897, "speaker": "舞台提示", "text": "[梁启超，失落着。", "page": 23, "y": 2043, "col": 0, "kind": "stage", "chapter": 8}, {"id": 898, "speaker": "梁启超", "text": "我以后还是多写字好了。", "page": 23, "y": 2095, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 899, "speaker": "谭嗣同", "text": "卓如，你一天三千字，有吧？", "page": 23, "y": 237, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 900, "speaker": "梁启超", "text": "有", "page": 23, "y": 289, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 901, "speaker": "谭嗣同", "text": "给我倒杯水。", "page": 23, "y": 340, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 902, "speaker": "梁启超", "text": "好。", "page": 23, "y": 392, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 903, "speaker": "谭嗣同", "text": "我来念。", "page": 23, "y": 444, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 904, "speaker": "舞台提示", "text": "[梁启超，去倒水。", "page": 23, "y": 496, "col": 1, "kind": "stage", "chapter": 8}, {"id": 905, "speaker": "舞台提示", "text": "[谭嗣同，走向光绪", "page": 23, "y": 547, "col": 1, "kind": "stage", "chapter": 8}, {"id": 906, "speaker": "舞台提示", "text": "[灯光变化，集中在两人身上。", "page": 23, "y": 598, "col": 1, "kind": "stage", "chapter": 8}, {"id": 907, "speaker": "谭嗣同", "text": "今朕问汝，可有何良策？", "page": 23, "y": 650, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 908, "speaker": "光绪", "text": "你们商议一下，看有什么好主意？", "page": 23, "y": 702, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 909, "speaker": "谭嗣同", "text": "俾旧法可以全变．“", "page": 23, "y": 754, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 910, "speaker": "光绪", "text": "旧法要慢慢变法，不可操之过急。", "page": 23, "y": 805, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 911, "speaker": "谭嗣同", "text": "将老谬昏庸之大臣尽行罢黜", "page": 23, "y": 857, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 912, "speaker": "光绪", "text": "把那些守旧的老人家，逐个辞退！", "page": 23, "y": 909, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 913, "speaker": "谭嗣同", "text": "而登进英勇通达之人，令其议政", "page": 23, "y": 960, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 914, "speaker": "光绪", "text": "录用胆识英敏，思路通达之人，参与国事议政", "page": 23, "y": 1012, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 915, "speaker": "谭嗣同", "text": "使大清转危为安、化弱为强，而又不致有拂圣意。", "page": 23, "y": 1115, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 916, "speaker": "光绪", "text": "使我大清转危为安，化弱为强，又不违背太后的懿旨", "page": 23, "y": 1217, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 917, "speaker": "杨锐", "text": "没听错吗？", "page": 23, "y": 1322, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 918, "speaker": "舞台提示", "text": "[光绪，走过舞台", "page": 23, "y": 1372, "col": 1, "kind": "stage", "chapter": 8}, {"id": 919, "speaker": "谭嗣同", "text": "接着往下念。", "page": 23, "y": 1424, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 920, "speaker": "光绪", "text": "但必欲朕一早痛切降旨！", "page": 23, "y": 1476, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 921, "speaker": "谭嗣同", "text": "今天一早，非常想痛苦地下一道指令！", "page": 23, "y": 1528, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 922, "speaker": "光绪", "text": "将旧法尽变而尽黜此辈昏庸之人。", "page": 23, "y": 1579, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 923, "speaker": "谭嗣同", "text": "将旧法尽变，昏庸尽除！则朕之权力，实有未足。则朕之权力，实有未足", "page": 23, "y": 1631, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 924, "speaker": "刘光第", "text": "皇上没实权！", "page": 23, "y": 1785, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 925, "speaker": "光绪", "text": "果始如此，则朕位不能保。", "page": 23, "y": 1837, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 926, "speaker": "舞台提示", "text": "[三章京，惊坐。", "page": 23, "y": 1888, "col": 1, "kind": "stage", "chapter": 8}, {"id": 927, "speaker": "光绪", "text": "何况其他？", "page": 23, "y": 1941, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 928, "speaker": "谭嗣同", "text": "果始如此，则朕位不能保，何况其他？", "page": 23, "y": 1992, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 929, "speaker": "林旭", "text": "皇上的位置不保了！", "page": 23, "y": 2044, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 930, "speaker": "舞台提示", "text": "[幕外：一记锣鼓", "page": 23, "y": 2095, "col": 1, "kind": "stage", "chapter": 8}, {"id": 931, "speaker": "光绪", "text": "今朕问汝，可有何良策？", "page": 24, "y": 245, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 932, "speaker": "谭嗣同", "text": "不能念了！皇上的意思是……", "page": 24, "y": 296, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 933, "speaker": "三章京", "text": "救驾！", "page": 24, "y": 348, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 934, "speaker": "舞台提示", "text": "[幕外：一阵急切的锣鼓点响起", "page": 24, "y": 398, "col": 0, "kind": "stage", "chapter": 8}, {"id": 935, "speaker": "舞台提示", "text": "[光绪，随锣鼓点行走，三章京跟随。", "page": 24, "y": 449, "col": 0, "kind": "stage", "chapter": 8}, {"id": 936, "speaker": "康有为", "text": "徐世昌说“是救驾还是自保？！”救驾的后果，你们想清楚了吗？", "page": 24, "y": 502, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 937, "speaker": "林旭", "text": "既能救驾，又能自保（合）彼此，一样。", "page": 24, "y": 605, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 938, "speaker": "舞台提示", "text": "[康有为，举起徐世昌的扇子，走过舞台。", "page": 24, "y": 757, "col": 0, "kind": "stage", "chapter": 8}, {"id": 939, "speaker": "康有为", "text": "徐世昌，你们不要忽略徐世昌的提问！", "page": 24, "y": 809, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 940, "speaker": "舞台提示", "text": "[灯光：渐渐隐去光绪，照亮谭嗣同", "page": 24, "y": 860, "col": 0, "kind": "stage", "chapter": 8}, {"id": 941, "speaker": "谭嗣同", "text": "我以我．血荐轩辕", "page": 24, "y": 912, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 942, "speaker": "康有为", "text": "徐世昌你这说的都是什么？", "page": 24, "y": 963, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 943, "speaker": "谭嗣同", "text": "谭嗣同支持皇帝矢志变法，绝无动摇！山河破碎，不有死者，无以酬圣主，不有行者，无以图将来，救亡图存。", "page": 24, "y": 1014, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 944, "speaker": "舞台提示", "text": "[灯光恢复。", "page": 24, "y": 1169, "col": 0, "kind": "stage", "chapter": 8}, {"id": 945, "speaker": "舞台提示", "text": "[四章京，坐回原座位", "page": 24, "y": 1220, "col": 0, "kind": "stage", "chapter": 8}, {"id": 946, "speaker": "舞台提示", "text": "[光绪，回到后区座位。", "page": 24, "y": 1272, "col": 0, "kind": "stage", "chapter": 8}, {"id": 947, "speaker": "舞台提示", "text": "[康有为，放下扇子。", "page": 24, "y": 1322, "col": 0, "kind": "stage", "chapter": 8}, {"id": 948, "speaker": "林旭", "text": "徐世昌？哎？徐世昌人呢？", "page": 24, "y": 1374, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 949, "speaker": "异禀", "text": "徐世昌他跑了。", "page": 24, "y": 1426, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 950, "speaker": "康有为", "text": "我说徐世昌并不在场", "page": 24, "y": 1477, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 951, "speaker": "刘光第", "text": "徐世昌跑了，跑前他说什么来着？", "page": 24, "y": 1529, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 952, "speaker": "杨锐", "text": "他怎么说的？", "page": 24, "y": 1580, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 953, "speaker": "康有为", "text": "他说“是救驾还是自保”？！救驾的后果，你们想清楚了吗？", "page": 24, "y": 1631, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 954, "speaker": "刘光第", "text": "政变。", "page": 24, "y": 1734, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 955, "speaker": "杨锐", "text": "政变。", "page": 24, "y": 1785, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 956, "speaker": "林旭", "text": "政变是什么意思啊？（合）那就是救驾啊！", "page": 24, "y": 1837, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 957, "speaker": "林旭", "text": "那不政变呢？", "page": 24, "y": 1990, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 958, "speaker": "舞台提示", "text": "[刘光第，向袁世凯问。", "page": 24, "y": 2041, "col": 0, "kind": "stage", "chapter": 8}, {"id": 959, "speaker": "刘光第", "text": "河南话怎么说？袁世凯。", "page": 24, "y": 2093, "col": 0, "kind": "dialogue", "chapter": 8}, {"id": 960, "speaker": "袁世凯", "text": "“去球噠”！", "page": 24, "y": 244, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 961, "speaker": "康有为", "text": "你这个“鳖孙”．", "page": 24, "y": 295, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 962, "speaker": "舞台提示", "text": "[袁世凯，下场", "page": 24, "y": 347, "col": 1, "kind": "stage", "chapter": 8}, {"id": 963, "speaker": "康有为", "text": "人民“鳖孙”", "page": 24, "y": 398, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 964, "speaker": "刘光第", "text": "完美", "page": 24, "y": 449, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 965, "speaker": "舞台提示", "text": "[幕外：电报声，此起彼伏。", "page": 24, "y": 500, "col": 1, "kind": "stage", "chapter": 8}, {"id": 966, "speaker": "舞台提示", "text": "[三章京，冲到台前", "page": 24, "y": 551, "col": 1, "kind": "stage", "chapter": 8}, {"id": 967, "speaker": "杨锐", "text": "所以，我急电两江两广总督张之洞大人！", "page": 24, "y": 604, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 968, "speaker": "林旭", "text": "所以，我急电翰林学士王锡藩大人！", "page": 24, "y": 654, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 969, "speaker": "刘光第", "text": "所以，我急电湖南巡抚陈宝箴大人！", "page": 24, "y": 706, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 970, "speaker": "杨锐", "text": "求救！", "page": 24, "y": 757, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 971, "speaker": "林旭", "text": "救命！", "page": 24, "y": 808, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 972, "speaker": "刘光第", "text": "求救！", "page": 24, "y": 860, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 973, "speaker": "谭嗣同", "text": "8月21日，皇上召见我四人，授予四品卿衔军机章京上行走，参议新政，官职面前，无人拒绝", "page": 24, "y": 911, "col": 1, "kind": "dialogue", "chapter": 8}, {"id": 974, "speaker": "舞台提示", "text": "[幕外：一声锣响。", "page": 24, "y": 1065, "col": 1, "kind": "stage", "chapter": 8}, {"id": 975, "speaker": "舞台提示", "text": "[多媒体：字幕“第九章节维新章京辅佐皇帝”", "page": 24, "y": 1116, "col": 1, "kind": "stage", "chapter": 9}, {"id": 976, "speaker": "舞台提示", "text": "[众人、异禀，把椅子分为两边。", "page": 24, "y": 1219, "col": 1, "kind": "stage", "chapter": 9}, {"id": 977, "speaker": "舞台提示", "text": "[多媒体：紫禁城“养心殿”内。", "page": 24, "y": 1271, "col": 1, "kind": "stage", "chapter": 9}, {"id": 978, "speaker": "舞台提示", "text": "[光绪，走到四章京面前，站定。", "page": 24, "y": 1322, "col": 1, "kind": "stage", "chapter": 9}, {"id": 979, "speaker": "舞台提示", "text": "[灯光：起光。", "page": 24, "y": 1374, "col": 1, "kind": "stage", "chapter": 9}, {"id": 980, "speaker": "光绪", "text": "朕，接受康有为建议，筹备秘书班子。全国推荐人数，千余人，朕选拔了七个月，面见了一百余位候选，你们四个，符合朕意。", "page": 24, "y": 1425, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 981, "speaker": "舞台提示", "text": "[四章京，下跪", "page": 24, "y": 1578, "col": 1, "kind": "stage", "chapter": 9}, {"id": 982, "speaker": "舞台提示", "text": "[光绪，示意让四章京起身。", "page": 24, "y": 1629, "col": 1, "kind": "stage", "chapter": 9}, {"id": 983, "speaker": "光绪", "text": "起来吧", "page": 24, "y": 1682, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 984, "speaker": "四章京", "text": "谢皇上。", "page": 24, "y": 1733, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 985, "speaker": "舞台提示", "text": "[四章京站起。", "page": 24, "y": 1784, "col": 1, "kind": "stage", "chapter": 9}, {"id": 986, "speaker": "光绪", "text": "新任军机处章京上行走。林旭，回话！", "page": 24, "y": 1836, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 987, "speaker": "林旭", "text": "清流喜泣君恩补，慷慨君歌千里言！林旭，肝脑涂地！", "page": 24, "y": 1887, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 988, "speaker": "光绪", "text": "林旭年纪？", "page": 24, "y": 1990, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 989, "speaker": "林旭", "text": "皇上，我没听清楚。", "page": 24, "y": 2041, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 990, "speaker": "光绪", "text": "你多大？", "page": 24, "y": 2092, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 991, "speaker": "林旭", "text": "24岁。", "page": 25, "y": 241, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 992, "speaker": "光绪", "text": "精灵圆熟，聪颖机智，当为大清效力！", "page": 25, "y": 294, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 993, "speaker": "林旭", "text": "（激动）谢皇上！", "page": 25, "y": 345, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 994, "speaker": "光绪", "text": "杨锐！", "page": 25, "y": 396, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 995, "speaker": "杨锐", "text": "臣在。", "page": 25, "y": 448, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 996, "speaker": "光绪", "text": "你做张之洞大人幕府秘书15年之久，经验可嘉。你说！", "page": 25, "y": 499, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 997, "speaker": "杨锐", "text": "皇上，兴学、练兵、救亡、用人，是臣辅佐皇上效力之策！臣，力学越王勾践，二十年卧薪尝胆……", "page": 25, "y": 602, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 998, "speaker": "光绪", "text": "二十年？慢了，大清三年变法当以自立，要快！", "page": 25, "y": 757, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 999, "speaker": "杨锐", "text": "三年？是康先生的建议，臣虽不敢苟同，但臣是秘书出身，都听领导的！快！", "page": 25, "y": 860, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1000, "speaker": "光绪", "text": "刘光第！", "page": 25, "y": 963, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1001, "speaker": "刘光第", "text": "皇上，变法三年当以自立！看似是个急活。光第，当不负昼夜，自请免去节假日，倾付身心为大清效命两年，然后回家教书。请免光第半年薪水。恳请皇上答允。", "page": 25, "y": 1015, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1002, "speaker": "光绪", "text": "刘光第闻名朝野的清官，没有靠山背景，不营私结党，免你半年俸禄，给朝野树个榜样，至于两年请辞，朕再考虑。", "page": 25, "y": 1222, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1003, "speaker": "刘光第", "text": "谢皇上！", "page": 25, "y": 1377, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1004, "speaker": "光绪", "text": "谭嗣同。", "page": 25, "y": 1429, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1005, "speaker": "谭嗣同", "text": "皇上，大清祸在朝廷重臣，借纲常礼义为幌，行独夫民贼勾当。谭嗣同不做为官之想，只为变法而来。不有行者，无以图将来；不有死者，无以召后起。嗣同为皇上效力，更为中华复兴而尽心！", "page": 25, "y": 1480, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1006, "speaker": "光绪", "text": "二品大员谭继洵大人的公子，朕送你两字：桀骜。", "page": 25, "y": 1738, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1007, "speaker": "舞台提示", "text": "[谭嗣同，下跪。", "page": 25, "y": 1841, "col": 0, "kind": "stage", "chapter": 9}, {"id": 1008, "speaker": "谭嗣同", "text": "皇上，光第家小，由我浏阳会馆支付。（合）一起分摊吧。", "page": 25, "y": 1892, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1009, "speaker": "刘光第", "text": "（下跪）皇上。", "page": 25, "y": 2047, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1010, "speaker": "光绪", "text": "再送你二字：担当。", "page": 25, "y": 2099, "col": 0, "kind": "dialogue", "chapter": 9}, {"id": 1011, "speaker": "谭嗣同", "text": "谢皇上！", "page": 25, "y": 243, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 1012, "speaker": "舞台提示", "text": "[光绪，扶谭嗣同起身。", "page": 25, "y": 295, "col": 1, "kind": "stage", "chapter": 9}, {"id": 1013, "speaker": "光绪", "text": "望你为大清变法，竭力担当。你们跪安吧", "page": 25, "y": 347, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 1014, "speaker": "舞台提示", "text": "[四章京，即将要跪。", "page": 25, "y": 398, "col": 1, "kind": "stage", "chapter": 9}, {"id": 1015, "speaker": "光绪", "text": "慢", "page": 25, "y": 450, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 1016, "speaker": "舞台提示", "text": "[光绪，伸手向四章京，行握手礼。", "page": 25, "y": 502, "col": 1, "kind": "stage", "chapter": 9}, {"id": 1017, "speaker": "舞台提示", "text": "[幕外：音乐“清平调”", "page": 25, "y": 553, "col": 1, "kind": "stage", "chapter": 9}, {"id": 1018, "speaker": "舞台提示", "text": "[四章京，与光绪握手。", "page": 25, "y": 605, "col": 1, "kind": "stage", "chapter": 9}, {"id": 1019, "speaker": "普净", "text": "蒙受君恩，殿前效力。还需要一点好修行，不然会喜不自禁", "page": 25, "y": 656, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 1020, "speaker": "梁启超", "text": "这里面只有谭嗣同例外，在面见皇帝之初，给远在家乡的妻子李闰写过一封家书。", "page": 25, "y": 759, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 1021, "speaker": "舞台提示", "text": "[多媒体：恢复寺庙院墙。", "page": 25, "y": 862, "col": 1, "kind": "stage", "chapter": 9}, {"id": 1022, "speaker": "谭嗣同", "text": "夫人如见：朝廷毅然变法，国事大有可为。我因此益加奋勉，不欲自暇自逸。平日再忙亦会尽虔修之力，得我佛慈悲也。我此行若出人意外……", "page": 25, "y": 913, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 1023, "speaker": "异禀", "text": "师父，谭嗣同好直觉，他预知了后面的下场", "page": 25, "y": 1120, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 1024, "speaker": "普净", "text": "这种近欢愉而不惊的定力，是个好修行人。", "page": 25, "y": 1172, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 1025, "speaker": "异禀", "text": "您重复一下上句。", "page": 25, "y": 1224, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 1026, "speaker": "谭嗣同", "text": "我此行，若出人意外，夫人益当自勉，视荣华如梦幻，视死辱为常情，勿喜勿悲，听命天然。惟必须节俭，免得人说闲话，至要至要。我十七、八号可被引见。此上，即颂坤安！", "page": 25, "y": 1275, "col": 1, "kind": "dialogue", "chapter": 9}, {"id": 1027, "speaker": "舞台提示", "text": "[谭嗣同，合信，走下", "page": 25, "y": 1533, "col": 1, "kind": "stage", "chapter": 9}, {"id": 1028, "speaker": "舞台提示", "text": "[多媒体：字幕“坤安”坤安，写给女人的词，这种文明已经丢失很久了。", "page": 25, "y": 1585, "col": 1, "kind": "stage", "chapter": 9}, {"id": 1029, "speaker": "舞台提示", "text": "[灯光：恢复四章京所在的座位前。", "page": 25, "y": 1740, "col": 1, "kind": "stage", "chapter": 9}, {"id": 1030, "speaker": "舞台提示", "text": "〔多媒体：字幕“第十章节密擅封奏谭章京行”", "page": 25, "y": 1791, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1031, "speaker": "舞台提示", "text": "[异禀，扶谭嗣同起身", "page": 25, "y": 1895, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1032, "speaker": "舞台提示", "text": "[四章京，回忆完上任之初的情景，回到现实。", "page": 25, "y": 1946, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1033, "speaker": "舞台提示", "text": "[多媒体：恢复“南海会馆”石。", "page": 25, "y": 1997, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1034, "speaker": "刘光第", "text": "救驾！", "page": 25, "y": 2049, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1035, "speaker": "林旭", "text": "救驾！救驾就是政变，是不是？", "page": 25, "y": 2101, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1036, "speaker": "杨锐", "text": "是政变！", "page": 26, "y": 235, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1037, "speaker": "刘光第", "text": "非得政变才能救驾吗？我就不愿意看到这样的事发生！", "page": 26, "y": 287, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1038, "speaker": "杨锐", "text": "没有人愿意看到，事情到这么不可收拾的地步！", "page": 26, "y": 389, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1039, "speaker": "林旭", "text": "如果政变失败，我们的政治前途会一黑到底。", "page": 26, "y": 493, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1040, "speaker": "梁启超", "text": "那我们就不救皇上了？！（合）救啊！", "page": 26, "y": 595, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1041, "speaker": "杨锐", "text": "我没有从密诏上看出皇上已经完全被废的迹象，皇上只是让我们想办法！", "page": 26, "y": 749, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1042, "speaker": "刘光第", "text": "办法呢？！", "page": 26, "y": 852, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1043, "speaker": "杨锐", "text": "没有。", "page": 26, "y": 903, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1044, "speaker": "刘光第", "text": "没有，老哥你说什么呢？", "page": 26, "y": 955, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1045, "speaker": "康有为", "text": "办法，只有一个，政变！异禀，我们参与一下。", "page": 26, "y": 1006, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1046, "speaker": "舞台提示", "text": "[普净，带异禀进人四章京的空间", "page": 26, "y": 1108, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1047, "speaker": "普净", "text": "后世对此次密谋，众说纷纭。有人说……", "page": 26, "y": 1160, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1048, "speaker": "林旭", "text": "我们不政变，怎么救驾？！", "page": 26, "y": 1212, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1049, "speaker": "杨锐", "text": "带出皇上密诏，命我等火速筹商密擅封奏！皇上是在暗示我们大难临头赶紧快走！", "page": 26, "y": 1263, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1050, "speaker": "舞台提示", "text": "[众人，站立。", "page": 26, "y": 1365, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1051, "speaker": "谭嗣同", "text": "不、不，皇上是在向我们求救！我们该当想出良策，既不伤害皇上和太后的和气，又能想出帮助皇上的办法。", "page": 26, "y": 1417, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1052, "speaker": "康有为", "text": "来不及了！宫中出了肃杀之气，", "page": 26, "y": 1571, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1053, "speaker": "舞台提示", "text": "[幕外：咚咚，鼓敲两声。", "page": 26, "y": 1622, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1054, "speaker": "康有为", "text": "慈禧肯定是要动手了，欲把维新派连根拔起。", "page": 26, "y": 1673, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1055, "speaker": "林旭", "text": "您是说慈禧不仅要把我们一网打尽，还要对皇上不利", "page": 26, "y": 1777, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1056, "speaker": "梁启超", "text": "康先生，事已至此，我们该做何打算？", "page": 26, "y": 1878, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1057, "speaker": "康有为", "text": "唯有行张柬之之志！", "page": 26, "y": 1930, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1058, "speaker": "舞台提示", "text": "[幕外：咚咚，鼓敲两声。", "page": 26, "y": 1981, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1059, "speaker": "舞台提示", "text": "[众人，坐下。", "page": 26, "y": 2033, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1060, "speaker": "刘光第", "text": "张柬之，是什么情况？", "page": 26, "y": 2085, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1061, "speaker": "康有为", "text": "当年武则天年老病衰之时，张柬之发动兵变，联合李多祚迫使武则天让位中宗李显，才让唐朝重新归正李姓。", "page": 26, "y": 234, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1062, "speaker": "林旭", "text": "康先生的意思是？！", "page": 26, "y": 389, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1063, "speaker": "康有为", "text": "当断不断，反受其累！", "page": 26, "y": 440, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1064, "speaker": "杨锐", "text": "这是千真万确的谋反！", "page": 26, "y": 492, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1065, "speaker": "舞台提示", "text": "[幕外：鼓敲两声。", "page": 26, "y": 543, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1066, "speaker": "康有为", "text": "政变是救驾，不是谋反，保皇救驾，围园劫后！", "page": 26, "y": 594, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1067, "speaker": "舞台提示", "text": "[六人，目光如炬，眼对中间", "page": 26, "y": 697, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1068, "speaker": "舞台提示", "text": "[灯光：集中在四章京、康有为、梁启超身上。", "page": 26, "y": 748, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1069, "speaker": "普净", "text": "这就叫急红眼！", "page": 26, "y": 800, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1070, "speaker": "异禀", "text": "不，师父这叫戏！", "page": 26, "y": 852, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1071, "speaker": "舞台提示", "text": "[幕外：鼓敲密集", "page": 26, "y": 903, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1072, "speaker": "舞台提示", "text": "[师兄弟，摆排装扮之物", "page": 26, "y": 954, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1073, "speaker": "舞台提示", "text": "[众人，开始装扮。", "page": 26, "y": 1005, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1074, "speaker": "普净", "text": "那就再激烈一点儿！来个大反转！", "page": 26, "y": 1057, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1075, "speaker": "舞台提示", "text": "[众人翻转椅子。", "page": 26, "y": 1108, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1076, "speaker": "康有为", "text": "不、不，法国大革命导致法国上下血流成河，革命最后取得成功，灾难却在法国延绵了80年，代价惨痛。为师主张变法，革命非我所愿。", "page": 26, "y": 1158, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1077, "speaker": "谭嗣同", "text": "慈禧让皇帝做傀儡掩人耳目，现在连这个傀儡都不想要，皇上恐怕连性命都不得其保。", "page": 26, "y": 1365, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1078, "speaker": "梁启超", "text": "皇上冒生命危险向我们通风报信，我们不能见死不救", "page": 26, "y": 1518, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1079, "speaker": "谭嗣同", "text": "必须把事情推到极端上去，不成功，便成仁，就是不能视而不见！必须政变！", "page": 26, "y": 1621, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1080, "speaker": "康有为", "text": "政变不是谋反，如果谋反，为师之前走的改良之路岂不滑稽可笑。", "page": 26, "y": 1724, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1081, "speaker": "异禀", "text": "康先生，刚才还主张张柬之政变，现在怎么又变了呢？！", "page": 26, "y": 1827, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1082, "speaker": "普净", "text": "历史，总是迷瘴丛生！这是关于谭嗣同的一个极端版本。", "page": 26, "y": 1930, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1083, "speaker": "谭嗣同", "text": "我们只有一个目的。将政权交予皇上。皇上有了实权，再行变法之路，事半功倍曲线变法，不算政变。围园劫后！", "page": 26, "y": 2032, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1084, "speaker": "众人", "text": "（合）围园劫后！", "page": 27, "y": 292, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1085, "speaker": "异禀", "text": "围园劫后，到底是谭大哥提的，还是康老师说的？！", "page": 27, "y": 344, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1086, "speaker": "普净", "text": "历史，总是迷瘴丛生！后世有人说，，", "page": 27, "y": 447, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1087, "speaker": "康有为", "text": "行张柬之之变，围园劫后！", "page": 27, "y": 498, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1088, "speaker": "异禀", "text": "是康老师说的？！", "page": 27, "y": 550, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1089, "speaker": "普净", "text": "后世还有人说。", "page": 27, "y": 601, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1090, "speaker": "谭嗣同", "text": "围园劫后！", "page": 27, "y": 653, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1091, "speaker": "异禀", "text": "哦，谭大哥说的。", "page": 27, "y": 705, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1092, "speaker": "普净", "text": "你说什么？", "page": 27, "y": 756, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1093, "speaker": "异禀", "text": "师父，我太混乱了。", "page": 27, "y": 808, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1094, "speaker": "普净", "text": "后世又有人记载！", "page": 27, "y": 859, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1095, "speaker": "三章京", "text": "另外三个章京，并不在场", "page": 27, "y": 911, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1096, "speaker": "杨锐", "text": "太极端了！", "page": 27, "y": 962, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1097, "speaker": "林旭", "text": "太极端了！", "page": 27, "y": 1014, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1098, "speaker": "刘光第", "text": "太极端了！", "page": 27, "y": 1065, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1099, "speaker": "康有为", "text": "不愿意干的，滚！", "page": 27, "y": 1116, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1100, "speaker": "舞台提示", "text": "[刘光第、杨锐、林旭，似走", "page": 27, "y": 1168, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1101, "speaker": "异禀", "text": "等等！你们不要想一走了之，回来", "page": 27, "y": 1220, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1102, "speaker": "舞台提示", "text": "[刘光第、杨锐、林旭，留下", "page": 27, "y": 1271, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1103, "speaker": "舞台提示", "text": "[众人，翻椅子。", "page": 27, "y": 1322, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1104, "speaker": "谭嗣同", "text": "不、不，康先生，我并不主张“围园劫后”，维新派长期以来并无谋反之心", "page": 27, "y": 1374, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1105, "speaker": "康有为", "text": "变法触及保守势力，慈禧早就想除掉我们，既然决一死战，不如先下手为强。", "page": 27, "y": 1477, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1106, "speaker": "谭嗣同", "text": "慈禧只是想让你一人出局。皇上明诏，着康有为速速离开京城，上海办报馆，这是皇上救康先生的万全之策。", "page": 27, "y": 1580, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1107, "speaker": "梁启超", "text": "如果皇上因由我们遭到杀身之祸，恐怕不是康先生的意愿。", "page": 27, "y": 1734, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1108, "speaker": "康有为", "text": "唯有置之死地而后生。为师走后，你们一定要投石击破水中天。", "page": 27, "y": 1837, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1109, "speaker": "舞台提示", "text": "[幕外：水声声效。", "page": 27, "y": 1940, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1110, "speaker": "梁启超", "text": "即使我们是张柬之，谁又是御林大将军李多祚？我们既无兵权又无势力，如何尝试？", "page": 27, "y": 1993, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1111, "speaker": "康有为", "text": "借兵。抢到慈禧前面，只有袁世凯能担此大任。", "page": 27, "y": 2095, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1112, "speaker": "梁启超", "text": "他一面支持变法，一面又深得荣禄器重", "page": 27, "y": 293, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1113, "speaker": "康有为", "text": "袁．世凯的新军是现今战斗力最强的一个军队", "page": 27, "y": 345, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1114, "speaker": "舞台提示", "text": "[梁启超，起身", "page": 27, "y": 447, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1115, "speaker": "谭嗣同", "text": "康先生说得对。只有袁世凯能担此大任。", "page": 27, "y": 499, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1116, "speaker": "舞台提示", "text": "[袁世凯，出现", "page": 27, "y": 551, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1117, "speaker": "谭嗣同", "text": "我去找袁世凯，是奸雄，是英雄，就在他的一念之中。", "page": 27, "y": 602, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1118, "speaker": "三章京", "text": "他要是出卖我们呢！", "page": 27, "y": 705, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1119, "speaker": "舞台提示", "text": "[袁世凯，随即再下场。", "page": 27, "y": 757, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1120, "speaker": "谭嗣同", "text": "那就让我当这个千古罪人吧。康先生，卓如，你们走！", "page": 27, "y": 808, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1121, "speaker": "舞台提示", "text": "[幕外：鼓敲两声。", "page": 27, "y": 911, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1122, "speaker": "梁启超", "text": "师兄，那肯定不行！", "page": 27, "y": 963, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1123, "speaker": "谭嗣同", "text": "皇上让康先生走，是惜才，康先生的学问可以帮助后世。你走，是你必须的选择你的未来是怎么说的？", "page": 27, "y": 1014, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1124, "speaker": "梁启超", "text": "推动中国现代社会发展的开山巨匠。你更是。", "page": 27, "y": 1169, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1125, "speaker": "谭嗣同", "text": "我不是。如果维新变法，我们都走了，那变法就是一场笑话。这局棋里，有一步死棋，就是我", "page": 27, "y": 1272, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1126, "speaker": "舞台提示", "text": "[幕外：一声磬响。", "page": 27, "y": 1426, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1127, "speaker": "舞台提示", "text": "[幕外：《心曲》响起", "page": 27, "y": 1478, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1128, "speaker": "舞台提示", "text": "[多媒体：法源寺“大雄宝殿”内", "page": 27, "y": 1530, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1129, "speaker": "舞台提示", "text": "[三章京、普净，下场", "page": 27, "y": 1581, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1130, "speaker": "舞台提示", "text": "[梁启超，大哭", "page": 27, "y": 1633, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1131, "speaker": "梁启超", "text": "我不愿意别人看见我的脆弱。", "page": 27, "y": 1684, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1132, "speaker": "康有为", "text": "这个师父知道。", "page": 27, "y": 1736, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1133, "speaker": "梁启超", "text": "我崇拜您，", "page": 27, "y": 1787, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1134, "speaker": "康有为", "text": "这个师父也知道，在我心里，你一直是初相识朝气蓬勃的你", "page": 27, "y": 1838, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1135, "speaker": "梁启超", "text": "我是幸运的人。", "page": 27, "y": 1941, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1136, "speaker": "康有为", "text": "知道“", "page": 27, "y": 1993, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1137, "speaker": "梁启超", "text": "17岁，在万木草堂得见您的才学，犹如大海潮音，狮子吼般地摧毁了我的意识，我没有经过思考便即刻拜您为师从此卓如一生学问之得力，皆在此年。", "page": 27, "y": 2044, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1138, "speaker": "舞台提示", "text": "[幕外：再一声磬响", "page": 28, "y": 341, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1139, "speaker": "梁启超", "text": "变法即将失败之前，千钧一发之际，老师你为何同意逃跑？！为什么让谭嗣同干那么危险的事", "page": 28, "y": 393, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1140, "speaker": "谭嗣同", "text": "卓如，是我自己想去做的", "page": 28, "y": 548, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1141, "speaker": "康有为", "text": "这就是变法的代价，逃生或去赴死。你别哭哭啼啼的，失败与否尚无定论", "page": 28, "y": 600, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1142, "speaker": "梁启超", "text": "先行逃生，就是懦夫！老师，我很失望，因为逃生就是逃跑！", "page": 28, "y": 703, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1143, "speaker": "康有为", "text": "逃跑，是对不利自己环境的逃离", "page": 28, "y": 807, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1144, "speaker": "谭嗣同", "text": "是事务性逃离", "page": 28, "y": 859, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1145, "speaker": "梁启超", "text": "逃生，是生存以求！", "page": 28, "y": 910, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1146, "speaker": "舞台提示", "text": "[梁启超，向后区走。", "page": 28, "y": 961, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1147, "speaker": "康有为", "text": "既然预知险境，为什么不去逃离？！", "page": 28, "y": 1014, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1148, "speaker": "舞台提示", "text": "[康有为，向后区走。", "page": 28, "y": 1065, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1149, "speaker": "梁启超", "text": "逃离就是怕死！老师，我本来是崇拜你的，可你在关键时刻的逃离，境界一点儿都不高！", "page": 28, "y": 1118, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1150, "speaker": "康有为", "text": "你是想看着老师死吗？！", "page": 28, "y": 1272, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1151, "speaker": "舞台提示", "text": "[梁启超，下跪", "page": 28, "y": 1324, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1152, "speaker": "梁启超", "text": "不是！", "page": 28, "y": 1376, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1153, "speaker": "康有为", "text": "那是什么？", "page": 28, "y": 1428, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1154, "speaker": "梁启超", "text": "变法的时候我24岁，我没有更高的智慧，我想不通，我很痛苦，也很纠结！有的死，是名节上的生！有的生，是名节上的死", "page": 28, "y": 1480, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1155, "speaker": "康有为", "text": "我们今天讨论的是，生！", "page": 28, "y": 1635, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1156, "speaker": "舞台提示", "text": "[多媒体：恢复法源寺院墙", "page": 28, "y": 1686, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1157, "speaker": "舞台提示", "text": "[幕外：一声磬响，《春歌》音乐起", "page": 28, "y": 1738, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1158, "speaker": "舞台提示", "text": "[三人形成阵势，慢走。", "page": 28, "y": 1790, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1159, "speaker": "舞台提示", "text": "[多媒体：字幕“生”", "page": 28, "y": 1841, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1160, "speaker": "舞台提示", "text": "[众僧做法事", "page": 28, "y": 1893, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1161, "speaker": "康有为", "text": "逃生是遇到危险时人类采取的措施及保全。保全是核心要义！保全自己，去弘扬思想是知识分子、是大知识分子的生存意义！", "page": 28, "y": 1945, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1162, "speaker": "梁启超", "text": "那您怎么解释佛教所讲“为救助众生而引刀一快”？复生，师兄！", "page": 28, "y": 237, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1163, "speaker": "谭嗣同", "text": "那是该当引刀，必须去死！情境、情节、救助，缺一不可！", "page": 28, "y": 340, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1164, "speaker": "康有为", "text": "三者缺一时，不该求死才是你的逻辑！作为一个天才，世界上可能仅存的“最后一个无所不知的人”！", "page": 28, "y": 443, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1165, "speaker": "梁启超", "text": "老师，您在说您自己！", "page": 28, "y": 599, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1166, "speaker": "康有为", "text": "当然是你、我这样为中国人群之进化，思想言论之自由，而努力生存的人！", "page": 28, "y": 651, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1167, "speaker": "梁启超", "text": "可我本来怕死，我都无法说服我自己听信您的言论！年轻人就该不顾一切！我想突破我的私念！我就是想死！", "page": 28, "y": 754, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1168, "speaker": "康有为", "text": "你不能愚昧地死去，我应该智慧地逃生！这就是老师与你的差距！", "page": 28, "y": 910, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1169, "speaker": "梁启超", "text": "我和老师的差距就是我想选择死，我和我师兄的差距，就是他不怕死！失之毫厘，差之千寻！为什么不成全我！", "page": 28, "y": 1013, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1170, "speaker": "舞台提示", "text": "[三人，走到中区。", "page": 28, "y": 1169, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1171, "speaker": "康有为", "text": "中国若能采纳我们的思想，必将出现大同盛世。你为什么不成全你自己！成全你自己，也是成全大清。", "page": 28, "y": 1221, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1172, "speaker": "梁启超", "text": "老师，你为你的贪生怕死找到了所有的理由，我简直就要听信你了。复生兄！", "page": 28, "y": 1376, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1173, "speaker": "舞台提示", "text": "[普净，带走康有为。", "page": 28, "y": 1479, "col": 1, "kind": "stage", "chapter": 10}, {"id": 1174, "speaker": "谭嗣同", "text": "你怎么总是哭哭啼啼", "page": 28, "y": 1530, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1175, "speaker": "梁启超", "text": "观世音也哭。", "page": 28, "y": 1583, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1176, "speaker": "谭嗣同", "text": "观音那叫普洒甘露，你这叫自寻烦恼。生死皆不能放下，你这叫苦情。", "page": 28, "y": 1635, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1177, "speaker": "梁启超", "text": "苦情吗？", "page": 28, "y": 1738, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1178, "speaker": "谭嗣同", "text": "苦情！", "page": 28, "y": 1790, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1179, "speaker": "梁启超", "text": "那请给我解释，我为什么要生？", "page": 28, "y": 1842, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1180, "speaker": "谭嗣同", "text": "我们因父母爱的力量或父母的欲望，成了我们这副肉身。", "page": 28, "y": 1893, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1181, "speaker": "梁启超", "text": "对，这副肉身", "page": 28, "y": 1997, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1182, "speaker": "谭嗣同", "text": "我们是纵向出生的竖式分娩", "page": 28, "y": 2048, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1183, "speaker": "梁启超", "text": "区别于横向出生的动物", "page": 28, "y": 2100, "col": 1, "kind": "dialogue", "chapter": 10}, {"id": 1184, "speaker": "谭嗣同", "text": "我们为人得天地之心。", "page": 29, "y": 240, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1185, "speaker": "梁启超", "text": "故我们此生为极贵。", "page": 29, "y": 291, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1186, "speaker": "谭嗣同", "text": "就是我们与生俱来具备的灵性。你的灵性优于他人。", "page": 29, "y": 343, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1187, "speaker": "梁启超", "text": "所以，我要活着", "page": 29, "y": 446, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1188, "speaker": "谭嗣同", "text": "你24岁，还能活很长。", "page": 29, "y": 498, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1189, "speaker": "梁启超", "text": "你不是才33岁吗？", "page": 29, "y": 550, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1190, "speaker": "谭嗣同", "text": "《赵氏孤儿》里有个公孙杵臼，他简单地去死了，不承担活着的屈辱。", "page": 29, "y": 602, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1191, "speaker": "梁启超", "text": "你准备简单地去死。", "page": 29, "y": 704, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1192, "speaker": "谭嗣同", "text": "我的故事没有悬念，大家都知道", "page": 29, "y": 756, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1193, "speaker": "舞台提示", "text": "[两人，坐在椅子上。", "page": 29, "y": 808, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1194, "speaker": "梁启超", "text": "我准备复杂地求生。", "page": 29, "y": 860, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1195, "speaker": "谭嗣同", "text": "应该说是昂扬地活着！向着未来的生活，活着，是件难事，兄弟。", "page": 29, "y": 911, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1196, "speaker": "梁启超", "text": "死才是勇气！", "page": 29, "y": 1014, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1197, "speaker": "舞台提示", "text": "[幕外：京剧锣鼓", "page": 29, "y": 1066, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1198, "speaker": "谭嗣同", "text": "郑廷玉《楚昭公》第三折：慌速速的强逃生……", "page": 29, "y": 1118, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1199, "speaker": "梁启超", "text": "急煎煎的甘受苦。", "page": 29, "y": 1169, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1200, "speaker": "谭嗣同", "text": "董解元《西厢记诸宫调》卷二", "page": 29, "y": 1221, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1201, "speaker": "梁启超", "text": "欲待望本阵里逃生“", "page": 29, "y": 1272, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1202, "speaker": "谭嗣同", "text": "见一骑马悄如飞到！", "page": 29, "y": 1325, "col": 0, "kind": "dialogue", "chapter": 10}, {"id": 1203, "speaker": "舞台提示", "text": "[幕外：马的嘶吼，快跑的声响", "page": 29, "y": 1376, "col": 0, "kind": "stage", "chapter": 10}, {"id": 1204, "speaker": "舞台提示", "text": "[多媒体：字幕“第十一章节法华寺内夜访袁公”", "page": 29, "y": 1428, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1205, "speaker": "舞台提示", "text": "[众人，搬椅子，分坐两侧，瞧戏。", "page": 29, "y": 1531, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1206, "speaker": "舞台提示", "text": "[四位僧人，搬上一桌二椅。", "page": 29, "y": 1583, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1207, "speaker": "舞台提示", "text": "[一束光起，谭嗣同站定。待一切安静，谭嗣同开始说话", "page": 29, "y": 1635, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1208, "speaker": "舞台提示", "text": "[多媒体：夜晚行云、飞鸟。", "page": 29, "y": 1737, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1209, "speaker": "谭嗣同", "text": "天干物燥，小心火烛。清明朗月，飞沙走石却迷了眼睛。破军！贪狼星出北方。乌云中，瞭牙乍现。半空中，怪鸟长鸣。", "page": 29, "y": 1789, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1210, "speaker": "舞台提示", "text": "[幕外：鸟声。", "page": 29, "y": 1944, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1211, "speaker": "谭嗣同", "text": "我径自出宣武门向南行，过珠市口。今日繁华市集，昔年宰杀活猪之地。", "page": 29, "y": 1996, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1212, "speaker": "舞台提示", "text": "[袁世凯，走出。", "page": 29, "y": 2099, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1213, "speaker": "袁世凯", "text": "一到夜里，人烟散去，百年前开膛破肚的腥臭气还是扑鼻而来。白天，人浮于事；夜晚，鬼也拜佛", "page": 29, "y": 240, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1214, "speaker": "谭嗣同", "text": "西厅胡同，葱店四巷驹章胡同报房胡同，山门三大间豁然眼前，黑暗中看不真切。", "page": 29, "y": 395, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1215, "speaker": "舞台提示", "text": "[幕外：一声梆子响。", "page": 29, "y": 498, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1216, "speaker": "舞台提示", "text": "[灯光：乍变。", "page": 29, "y": 550, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1217, "speaker": "谭嗣同", "text": "我到了。", "page": 29, "y": 602, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1218, "speaker": "舞台提示", "text": "[幕外：一声磬响。", "page": 29, "y": 653, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1219, "speaker": "舞台提示", "text": "[多媒体：匾额“法华寺”。", "page": 29, "y": 704, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1220, "speaker": "众人", "text": "（合）法华寺。", "page": 29, "y": 757, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1221, "speaker": "谭嗣同", "text": "有时候，是得先成夜叉，再成菩萨。", "page": 29, "y": 808, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1222, "speaker": "袁世凯", "text": "久了，觉得自己也成了一只鬼", "page": 29, "y": 860, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1223, "speaker": "普净", "text": "谭嗣同，不等人传请，就直接进了厅堂。", "page": 29, "y": 911, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1224, "speaker": "舞台提示", "text": "[多媒体：法华寺内堂。", "page": 29, "y": 963, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1225, "speaker": "舞台提示", "text": "[谭嗣同，深呼吸，整整衣衫，拱手为礼。", "page": 29, "y": 1014, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1226, "speaker": "谭嗣同", "text": "袁勤王！", "page": 29, "y": 1067, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1227, "speaker": "舞台提示", "text": "[幕外：一声剑气。", "page": 29, "y": 1118, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1228, "speaker": "舞台提示", "text": "[袁世凯，看见谭嗣同。", "page": 29, "y": 1170, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1229, "speaker": "异禀", "text": "厅堂内，一股肃杀之气。二人四目交投！", "page": 29, "y": 1221, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1230, "speaker": "谭嗣同", "text": "袁勤王这面相，正可谓豹头虎眼的大将格局，只可惜，面皮太白了。", "page": 29, "y": 1273, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1231, "speaker": "袁世凯", "text": "谭大人！（对观众）我看他，双目炯炯有神，似两团冥火在跳荡，却是个不祥之人。", "page": 29, "y": 1377, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1232, "speaker": "刘光第", "text": "奸贼看义士，都是不祥之人。", "page": 29, "y": 1480, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1233, "speaker": "袁世凯", "text": "谭大人，深夜造访，可有要事？请坐。", "page": 29, "y": 1532, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1234, "speaker": "谭嗣同", "text": "袁勤王，身居法华寺，可是信佛？", "page": 29, "y": 1584, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1235, "speaker": "袁世凯", "text": "身居此寺，是离恩师李鸿章大人居住的贤良寺近，故好走动请教。况且法华寺一带是驻扎八旗军队的地方，顺治十八年改设正蓝旗教场。作为军人，我住着舒坦而己。", "page": 29, "y": 1635, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1236, "speaker": "谭嗣同", "text": "身带杀伐之气，敢住寺庙，你也有这个胆子！", "page": 29, "y": 1893, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1237, "speaker": "袁世凯", "text": "佛门有句话：放下屠刀，立地成佛", "page": 29, "y": 1945, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1238, "speaker": "舞台提示", "text": "[幕外：一声磬响（合）不必寒暄……", "page": 29, "y": 1997, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1239, "speaker": "袁世凯", "text": "谭大人，何事请讲！", "page": 30, "y": 234, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1240, "speaker": "谭嗣同", "text": "君子直言坦荡，皇帝有难，袁勤王肯出手相救？！", "page": 30, "y": 286, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1241, "speaker": "袁世凯", "text": "一您再说一遍？！", "page": 30, "y": 390, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1242, "speaker": "谭嗣同", "text": "我想你是听清楚了，不然我就骂你！（合）好话不说二遍“", "page": 30, "y": 442, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1243, "speaker": "袁世凯", "text": "您是说，光绪皇帝有难？！", "page": 30, "y": 598, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1244, "speaker": "谭嗣同", "text": "空负大将格局，却不敢担当国事！", "page": 30, "y": 649, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1245, "speaker": "袁世凯", "text": "骂得好！您是说，再说一遍，皇帝有难？！", "page": 30, "y": 701, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1246, "speaker": "谭嗣同", "text": "对！再说一遍，袁勤王，肯出手相救吗？！", "page": 30, "y": 753, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1247, "speaker": "袁世凯", "text": "请谭大人赐教！", "page": 30, "y": 805, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1248, "speaker": "谭嗣同", "text": "你怎么看待，光绪皇帝！", "page": 30, "y": 856, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1249, "speaker": "袁世凯", "text": "旷代之圣主！", "page": 30, "y": 908, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1250, "speaker": "谭嗣同", "text": "光绪帝，待你袁世凯如何？", "page": 30, "y": 959, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1251, "speaker": "袁世凯", "text": "两天前，袁某第一次被皇帝召见，即被加官两级。", "page": 30, "y": 1012, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1252, "speaker": "普净", "text": "这个官级相当于民国的国防部副部长。", "page": 30, "y": 1115, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1253, "speaker": "袁世凯", "text": "袁某必肝脑涂地，图报皇恩，不知我主，难在何处？", "page": 30, "y": 1167, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1254, "speaker": "异禀", "text": "谭大哥，拿密诏！", "page": 30, "y": 1271, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1255, "speaker": "林旭", "text": "密诏能给他看吗？", "page": 30, "y": 1322, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1256, "speaker": "异禀", "text": "当然能！你闭嘴！", "page": 30, "y": 1374, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1257, "speaker": "林旭", "text": "你厉害！", "page": 30, "y": 1426, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1258, "speaker": "舞台提示", "text": "[谭嗣同，取出密诏。", "page": 30, "y": 1478, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1259, "speaker": "谭嗣同", "text": "皇帝，密诏在此，袁世凯接诏！", "page": 30, "y": 1529, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1260, "speaker": "舞台提示", "text": "[袁也凯跪地磕头。接过密诏念出声来。", "page": 30, "y": 1582, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1261, "speaker": "舞台提示", "text": "[幕外：京戏单皮鼓声。", "page": 30, "y": 1633, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1262, "speaker": "袁世凯", "text": "今朕位几不保，汝康有为、杨锐、林旭、谭嗣同、刘光第等，可，“", "page": 30, "y": 1685, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1263, "speaker": "三章京", "text": "（大声）妥速密筹，设法相救，朕十分焦灼，不胜企望之至。", "page": 30, "y": 1788, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1264, "speaker": "谭嗣同", "text": "特，谕。", "page": 30, "y": 1892, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1265, "speaker": "袁世凯", "text": "这字迹……", "page": 30, "y": 1944, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1266, "speaker": "谭嗣同", "text": "字迹如何？", "page": 30, "y": 1996, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1267, "speaker": "袁世凯", "text": "我说的是颜色！", "page": 30, "y": 2047, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1268, "speaker": "谭嗣同", "text": "墨色", "page": 30, "y": 2099, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1269, "speaker": "袁世凯", "text": "假的。", "page": 30, "y": 235, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1270, "speaker": "舞台提示", "text": "[袁世凯，扔诏", "page": 30, "y": 287, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1271, "speaker": "谭嗣同", "text": "密诏，本就是绝密，为皇上安全计！这是抄本。", "page": 30, "y": 339, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1272, "speaker": "袁世凯", "text": "你给我个抄本，我怎么相信你，我要皇上的真诏。", "page": 30, "y": 442, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1273, "speaker": "谭嗣同", "text": "杨锐！你不给我真密诏，我怎么说服袁世凯。", "page": 30, "y": 546, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1274, "speaker": "舞台提示", "text": "[异禀，跑过来，向杨锐", "page": 30, "y": 598, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1275, "speaker": "异禀", "text": "你不给谭大哥真密诏，杨大哥，你怎么想的？！", "page": 30, "y": 650, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1276, "speaker": "杨锐", "text": "密诏本就是绝密，本不该示人，若有任何闪失，都会牵连皇上。", "page": 30, "y": 753, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1277, "speaker": "谭嗣同", "text": "你坏了我大事！", "page": 30, "y": 856, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1278, "speaker": "杨锐", "text": "为不牵连皇上，我必须是一个忠诚的秘书！", "page": 30, "y": 909, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1279, "speaker": "异禀", "text": "如果袁世凯看到真的密诏呢？", "page": 30, "y": 961, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1280, "speaker": "袁世凯", "text": "历史，将可能重新改写。", "page": 30, "y": 1013, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1281, "speaker": "普净", "text": "做为官升两级的袁世凯，必会酬谢皇恩！", "page": 30, "y": 1064, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1282, "speaker": "袁世凯", "text": "不，做为大清官员，遵奉圣旨，是天职", "page": 30, "y": 1115, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1283, "speaker": "三章京", "text": "否则，违令者，斩！", "page": 30, "y": 1168, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1284, "speaker": "谭嗣同", "text": "一个秘书的决定，有时会影响领导一生！", "page": 30, "y": 1219, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1285, "speaker": "舞台提示", "text": "[谭嗣同，拍案而起。", "page": 30, "y": 1271, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1286, "speaker": "袁世凯", "text": "疼吗？", "page": 30, "y": 1323, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1287, "speaker": "谭嗣同", "text": "有点。", "page": 30, "y": 1374, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1288, "speaker": "舞台提示", "text": "[袁世凯，拍案而起。", "page": 30, "y": 1426, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1289, "speaker": "袁世凯", "text": "他腰间衣襟高起，似有硬物！", "page": 30, "y": 1479, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1290, "speaker": "谭嗣同", "text": "疼吗？", "page": 30, "y": 1530, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1291, "speaker": "袁世凯", "text": "不疼。请坐。", "page": 30, "y": 1582, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1292, "speaker": "异禀", "text": "谭大哥，你带凶器了？", "page": 30, "y": 1634, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1293, "speaker": "谭嗣同", "text": "带了！", "page": 30, "y": 1686, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1294, "speaker": "舞台提示", "text": "[谭嗣同，打开一把折扇。", "page": 30, "y": 1737, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1295, "speaker": "谭嗣同", "text": "一把折扇。", "page": 30, "y": 1788, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1296, "speaker": "异禀", "text": "他要是不答应呢？", "page": 30, "y": 1841, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1297, "speaker": "袁世凯", "text": "（河南话）他会用硬物弄死俺！", "page": 30, "y": 1893, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1298, "speaker": "三章京", "text": "（河南话）袁世凯很聪明。", "page": 30, "y": 1944, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1299, "speaker": "舞台提示", "text": "[袁世凯，起身站立；随即谭嗣同站立。", "page": 30, "y": 1995, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1300, "speaker": "舞台提示", "text": "[两人，围桌子踱步。", "page": 30, "y": 2048, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1301, "speaker": "刘光第", "text": "我们维新派在密谋的时候，分析过袁世凯。", "page": 30, "y": 2099, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1302, "speaker": "杨锐", "text": "他可以翻手为云。", "page": 31, "y": 244, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1303, "speaker": "刘光第", "text": "也可以覆手为雨。", "page": 31, "y": 295, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1304, "speaker": "林旭", "text": "有野心！有野心，便有利用价值", "page": 31, "y": 347, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1305, "speaker": "普净", "text": "戊戌年八月初一，他第一次面见光绪皇帝，就认为自己可能陷人了某个政治漩涡。", "page": 31, "y": 399, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1306, "speaker": "谭嗣同", "text": "袁勤王，要不要成就一番事业，或想做一代枭雄，要不要办一件惊世骇俗之事，都不重要，重要的是，皇帝有难，满朝文武，只有一个人可以担当拯救，非你莫属！", "page": 31, "y": 502, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1307, "speaker": "袁世凯", "text": "我不信你！", "page": 31, "y": 709, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1308, "speaker": "谭嗣同", "text": "那我就效仿战国将领樊於期，自割头颅。", "page": 31, "y": 760, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1309, "speaker": "舞台提示", "text": "[谭嗣同，拿出匕首。", "page": 31, "y": 812, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1310, "speaker": "异禀", "text": "大哥，你带凶器了！", "page": 31, "y": 864, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1311, "speaker": "袁世凯", "text": "等等！此事是真？！", "page": 31, "y": 915, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1312, "speaker": "谭嗣同", "text": "你必须答应救驾", "page": 31, "y": 967, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1313, "speaker": "袁世凯", "text": "哎……哎……", "page": 31, "y": 1018, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1314, "speaker": "舞台提示", "text": "[二人，打一照面", "page": 31, "y": 1070, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1315, "speaker": "谭嗣同", "text": "我再死不迟！", "page": 31, "y": 1121, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1316, "speaker": "舞台提示", "text": "[二人，重新坐回。", "page": 31, "y": 1174, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1317, "speaker": "谭嗣同", "text": "你知道小站练兵的目的吗？", "page": 31, "y": 1225, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1318, "speaker": "袁世凯", "text": "小站练兵，是要练成一支能打胜仗的大清军队。", "page": 31, "y": 1277, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1319, "speaker": "谭嗣同", "text": "操练部队干什么用？", "page": 31, "y": 1379, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1320, "speaker": "袁世凯", "text": "为皇帝所用", "page": 31, "y": 1431, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1321, "speaker": "谭嗣同", "text": "现在荣禄是总兵，直隶总督！你在他手下听命。荣禄用你的新兵，废除皇上，你想到没有？", "page": 31, "y": 1483, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1322, "speaker": "袁世凯", "text": "我初到北京，就嗅到不同寻常的味道，北京城谣言四起，慈禧太后和荣禄大人要在天津发动政变，以及康有为领导的维新派各种异动谣传。还有关于帝党、后党之说，充斥京城。皇上给我提升官职，就像打开了一道凶险的闸门。但是，我想观望不动，或说顺水推舟。", "page": 31, "y": 1637, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1323, "speaker": "舞台提示", "text": "[谭嗣同，拔出匕首，横在脖颈。", "page": 31, "y": 1999, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1324, "speaker": "谭嗣同", "text": "现在，皇帝有难，即将被废，你不酬谢皇恩，你天诛地灭！", "page": 31, "y": 2051, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1325, "speaker": "袁世凯", "text": "多么可怕的一个造型！你说过，庙里不能有杀伐之气！", "page": 31, "y": 244, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1326, "speaker": "谭嗣同", "text": "我是佛门弟子，死在庙里，快哉快哉！", "page": 31, "y": 347, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1327, "speaker": "袁世凯", "text": "一个亡命之人。面对这样一个狂徒，我的智商！", "page": 31, "y": 398, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1328, "speaker": "舞台提示", "text": "[幕外：磬声一响", "page": 31, "y": 502, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1329, "speaker": "袁世凯", "text": "谭大人说得有道理，我该怎么办？！", "page": 31, "y": 554, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1330, "speaker": "舞台提示", "text": "[两人，即坐。", "page": 31, "y": 606, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1331, "speaker": "谭嗣同", "text": "坐！石破天惊，一个计划！", "page": 31, "y": 657, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1332, "speaker": "袁世凯", "text": "等等，我不想听！你死吧。", "page": 31, "y": 709, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1333, "speaker": "舞台提示", "text": "[谭嗣同，激动地上桌子。", "page": 31, "y": 760, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1334, "speaker": "谭嗣同", "text": "我死也要拉上你！坏了皇上的大事，我在阴间做鬼也不会放过你！", "page": 31, "y": 811, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1335, "speaker": "袁世凯", "text": "（动着心思）我刚才说过，我想静候观望来着，你别强迫我，你把刀先放下。", "page": 31, "y": 915, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1336, "speaker": "舞台提示", "text": "[谭嗣同，不放刀。", "page": 31, "y": 1018, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1337, "speaker": "谭嗣同", "text": "变法是文戏，为了变法顺利，必须唱武戏。", "page": 31, "y": 1070, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1338, "speaker": "袁世凯", "text": "什么文戏武戏的，你先说事！我听听是不是有道理！", "page": 31, "y": 1121, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1339, "speaker": "舞台提示", "text": "[谭嗣同，用刀指向袁世凯", "page": 31, "y": 1225, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1340, "speaker": "谭嗣同", "text": "用新军包围颐和园，囚禁慈禧。此举叫，四个字……", "page": 31, "y": 1276, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1341, "speaker": "袁世凯", "text": "一个字我也不想听。", "page": 31, "y": 1379, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1342, "speaker": "谭嗣同", "text": "“围园劫后”！", "page": 31, "y": 1431, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1343, "speaker": "舞台提示", "text": "[袁世凯，堵住耳朵，蹲在地上。", "page": 31, "y": 1483, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1344, "speaker": "异禀", "text": "大哥，你是要杀奶奶吗？", "page": 31, "y": 1534, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1345, "speaker": "谭嗣同", "text": "不是！先把奶奶保护起来！", "page": 31, "y": 1586, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1346, "speaker": "袁世凯", "text": "（河南话）我带兵多年，杀人不眨眼，泰山崩于前而色不变，可是现在，我的裤子好像湿了。", "page": 31, "y": 1638, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1347, "speaker": "舞台提示", "text": "[袁世凯，走向前。", "page": 31, "y": 1792, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1348, "speaker": "袁世凯", "text": "一（河南话）俺的枪呢？！没做准备，来人！", "page": 31, "y": 1844, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1349, "speaker": "舞台提示", "text": "[谭嗣同，起身跳下，匕首对着袁世凯。", "page": 31, "y": 1896, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1350, "speaker": "谭嗣同", "text": "不许声张！", "page": 31, "y": 1948, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1351, "speaker": "异禀", "text": "袁大头，不许声张！", "page": 31, "y": 1999, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1352, "speaker": "三章京", "text": "不许声张！", "page": 31, "y": 2050, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1353, "speaker": "谭嗣同", "text": "看得出来，你对皇上不忠！", "page": 31, "y": 2102, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1354, "speaker": "袁世凯", "text": "苍天在上，皇恩深重！袁某对皇上可以鞠躬尽瘁！我只是不信你的假密诏！", "page": 32, "y": 244, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1355, "speaker": "舞台提示", "text": "[两人，回座。", "page": 32, "y": 347, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1356, "speaker": "谭嗣同", "text": "我不能死，你也不能死。救驾！待我们成功！", "page": 32, "y": 399, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1357, "speaker": "袁世凯", "text": "要是失败呢？！", "page": 32, "y": 450, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1358, "speaker": "谭嗣同", "text": "你我一块儿去死！你若有告密之想，今天就是你的死期！", "page": 32, "y": 502, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1359, "speaker": "舞台提示", "text": "[谭嗣同，刀横手上一划，将血抹在袁世凯脸上。", "page": 32, "y": 605, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1360, "speaker": "袁世凯", "text": "（河南话）这都是误会，我们坐下谈话", "page": 32, "y": 708, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1361, "speaker": "舞台提示", "text": "[谭嗣同，坐上桌子。", "page": 32, "y": 759, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1362, "speaker": "谭嗣同", "text": "讲！", "page": 32, "y": 811, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1363, "speaker": "袁世凯", "text": "我当然明白你的用心，容我考虑", "page": 32, "y": 863, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1364, "speaker": "谭嗣同", "text": "你必须答应。", "page": 32, "y": 915, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1365, "speaker": "舞台提示", "text": "[袁世凯，坐上桌子。", "page": 32, "y": 966, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1366, "speaker": "谭嗣同", "text": "这是关乎国家昌盛与否的重大决定。你不要让我为难", "page": 32, "y": 1017, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1367, "speaker": "袁世凯", "text": "你在为难我。", "page": 32, "y": 1120, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1368, "speaker": "谭嗣同", "text": "袁大人可以报君恩，救君难，立奇功大业，一举而定天下局势；也可以径自去颐和园告发，害及皇上，功名富贵，唾手可得。路要怎么走，就看袁大人怎么选了。", "page": 32, "y": 1172, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1369, "speaker": "林旭", "text": "推论袁世凯，要不要冒险！", "page": 32, "y": 1379, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1370, "speaker": "刘光第", "text": "权利到底在谁那儿？", "page": 32, "y": 1430, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1371, "speaker": "袁世凯", "text": "很简单，不用想，在太后那儿！", "page": 32, "y": 1481, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1372, "speaker": "杨锐", "text": "较量中，是傍胳膊？还是大腿？", "page": 32, "y": 1533, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1373, "speaker": "袁世凯", "text": "不用想，傍大腿", "page": 32, "y": 1585, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1374, "speaker": "谭嗣同", "text": "是马上告发？还是静观其动？", "page": 32, "y": 1636, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1375, "speaker": "袁世凯", "text": "不用说，静观其动！", "page": 32, "y": 1687, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1376, "speaker": "林旭", "text": "是歇两天？还是马上行动？", "page": 32, "y": 1739, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1377, "speaker": "袁世凯", "text": "不用说，歇两天看风声。", "page": 32, "y": 1791, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1378, "speaker": "刘光第", "text": "两天之内，慈禧人宫，变法可能流产，袁世凯在想对策。", "page": 32, "y": 1841, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1379, "speaker": "袁世凯", "text": "说的明白，当然！", "page": 32, "y": 1945, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1380, "speaker": "杨锐", "text": "东窗事发，经过拷问，惊天大密惊现，就是袁世凯政变。", "page": 32, "y": 1997, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1381, "speaker": "袁世凯", "text": "必然！", "page": 32, "y": 2100, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1382, "speaker": "林旭", "text": "要杀头，值不值得？", "page": 32, "y": 245, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1383, "speaker": "袁世凯", "text": "不值！", "page": 32, "y": 296, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1384, "speaker": "刘光第", "text": "袁世凯，先下手为强！", "page": 32, "y": 347, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1385, "speaker": "袁世凯", "text": "这叫表明心迹！", "page": 32, "y": 399, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1386, "speaker": "三章京", "text": "袁世凯如何定夺？谭嗣同，都看你的了！", "page": 32, "y": 450, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1387, "speaker": "谭嗣同", "text": "袁世凯，都看你的了！", "page": 32, "y": 502, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1388, "speaker": "舞台提示", "text": "[袁世凯，跳下桌子，向前走。", "page": 32, "y": 553, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1389, "speaker": "袁世凯", "text": "谭大人，皇上是你的皇上，也是我的皇上。你救得，我当然也救得。（低声）你我萍水相逢，你深夜造访，我的随从必生疑心，要是泄密于外人，你我计划必定败露。因为你是近臣，我有兵权，最易招疑。围园劫后！从今天起，我将闭门称病，你不可人内，也不可再来", "page": 32, "y": 605, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1390, "speaker": "谭嗣同", "text": "皇上之安危，维新之气运，中国之未来，尽在袁公之手。我怎么信你？！", "page": 32, "y": 965, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1391, "speaker": "袁世凯", "text": "（哭）我受国恩深重，断不至丧心病狂，贻误大局。但能有益于皇上，必当死生以之！", "page": 32, "y": 1069, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1392, "speaker": "舞台提示", "text": "[袁世凯，抓住谭嗣同带匕首的手，在手上划了一刀。抹在谭嗣同脸上。", "page": 32, "y": 1171, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1393, "speaker": "谭嗣同", "text": "大人所言甚是，告辞。（抱拳，转身就走）", "page": 32, "y": 1275, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1394, "speaker": "舞台提示", "text": "[多媒体：瞬变，夜晚行云。", "page": 32, "y": 1326, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1395, "speaker": "袁世凯", "text": "他面色不改，转身走进黑夜里。", "page": 32, "y": 1378, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1396, "speaker": "谭嗣同", "text": "我面色不改，转身走进黑夜里。", "page": 32, "y": 1429, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1397, "speaker": "普净", "text": "看着谭嗣同离去，想起古人语。血勇之人……", "page": 32, "y": 1481, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1398, "speaker": "异禀", "text": "怒而面赤。", "page": 32, "y": 1533, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1399, "speaker": "普净", "text": "脉勇之人“", "page": 32, "y": 1584, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1400, "speaker": "异禀", "text": "怒而面青。", "page": 32, "y": 1636, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1401, "speaker": "普净", "text": "骨勇之人，，", "page": 32, "y": 1687, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1402, "speaker": "异禀", "text": "怒而面白。", "page": 32, "y": 1739, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1403, "speaker": "谭嗣同", "text": "神勇之人，怒而色不改。", "page": 32, "y": 1790, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1404, "speaker": "袁世凯", "text": "真狂徒也！", "page": 32, "y": 1841, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1405, "speaker": "三章京", "text": "真义士也", "page": 32, "y": 1893, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1406, "speaker": "舞台提示", "text": "[异禀，起立鼓掌。", "page": 32, "y": 1944, "col": 1, "kind": "stage", "chapter": 11}, {"id": 1407, "speaker": "异禀", "text": "大哥，英雄！", "page": 32, "y": 1997, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1408, "speaker": "袁世凯", "text": "我感到一阵彻骨的恐怖。", "page": 32, "y": 2047, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1409, "speaker": "谭嗣同", "text": "我忽然感到一阵莫名的悲伤", "page": 32, "y": 2099, "col": 1, "kind": "dialogue", "chapter": 11}, {"id": 1410, "speaker": "袁世凯", "text": "一定是冥冥中某个神明和我开了这个似梦般的恶毒玩笑。", "page": 33, "y": 239, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1411, "speaker": "谭嗣同", "text": "一定是我违背了佛祖之意，在庙里说了绮语、异语的业障伤情！", "page": 33, "y": 342, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1412, "speaker": "袁世凯", "text": "是不是，他就这么幽灵般的来了一趟。", "page": 33, "y": 445, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1413, "speaker": "谭嗣同", "text": "是不是，我就这么来了一趟。为了救驾，渺茫之希望，最后之一搏！我的死期就快近了。", "page": 33, "y": 497, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1414, "speaker": "袁世凯", "text": "作为军人，我第一次想对佛祖说，救我！", "page": 33, "y": 651, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1415, "speaker": "谭嗣同", "text": "我想在这暗夜里，把我的身体做柴，燃起大清不灭的熊熊烈火，救驾！", "page": 33, "y": 702, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1416, "speaker": "袁世凯", "text": "救……", "page": 33, "y": 805, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1417, "speaker": "舞台提示", "text": "[幕外：大提琴音乐", "page": 33, "y": 857, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1418, "speaker": "舞台提示", "text": "[谭嗣同，哭泣。", "page": 33, "y": 909, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1419, "speaker": "谭嗣同", "text": "我像一个女人一样深深地爱着大清！", "page": 33, "y": 960, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1420, "speaker": "袁世凯", "text": "我似一个女人一样深深地爱着大清！", "page": 33, "y": 1012, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1421, "speaker": "谭嗣同", "text": "一枝红艳", "page": 33, "y": 1063, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1422, "speaker": "袁世凯", "text": "露凝香。", "page": 33, "y": 1114, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1423, "speaker": "谭嗣同", "text": "云雨巫山", "page": 33, "y": 1166, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1424, "speaker": "袁世凯", "text": "枉断肠", "page": 33, "y": 1218, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1425, "speaker": "谭嗣同", "text": "借问汉宫谁得似。", "page": 33, "y": 1269, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1426, "speaker": "袁世凯", "text": "可怜飞燕。", "page": 33, "y": 1321, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1426001, "speaker": "袁世凯、谭嗣同", "text": "（合）倚新装。", "page": 33, "y": 1321, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1427, "speaker": "袁世凯", "text": "他的……", "page": 33, "y": 1424, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1428, "speaker": "谭嗣同", "text": "我的……", "page": 33, "y": 1475, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1428001, "speaker": "袁世凯、谭嗣同", "text": "（合）命运，就这么被决定了。", "page": 33, "y": 1475, "col": 0, "kind": "dialogue", "chapter": 11}, {"id": 1429, "speaker": "舞台提示", "text": "[多媒体：恢复法源寺院墙。", "page": 33, "y": 1578, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1430, "speaker": "舞台提示", "text": "[幕外：火车鸣笛声音", "page": 33, "y": 1630, "col": 0, "kind": "stage", "chapter": 11}, {"id": 1431, "speaker": "舞台提示", "text": "[多媒体：字幕“第十二章节进退维谷心忧如焚”", "page": 33, "y": 1681, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1432, "speaker": "舞台提示", "text": "[多媒体：呼啸着开动的火车。", "page": 33, "y": 1784, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1433, "speaker": "舞台提示", "text": "[康有为，走上", "page": 33, "y": 1836, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1434, "speaker": "舞台提示", "text": "[袁世凯与康有为，分坐舞台两侧。", "page": 33, "y": 1887, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1435, "speaker": "袁世凯", "text": "（哭）北京，桂花飘香的时节……", "page": 33, "y": 1939, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1436, "speaker": "康有为", "text": "（哭）北京，落叶飘零，菊花盛开的时侯……", "page": 33, "y": 1990, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1437, "speaker": "舞台提示", "text": "[幕外：刹车声。", "page": 33, "y": 2042, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1438, "speaker": "袁世凯", "text": "一个想静观其变，稳而不慌的，傻子！", "page": 33, "y": 2093, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1439, "speaker": "舞台提示", "text": "[光绪帝，走出。", "page": 33, "y": 239, "col": 1, "kind": "stage", "chapter": 12}, {"id": 1440, "speaker": "袁世凯", "text": "被荒谬的命运大神，摔上了一辆呼啸着、疯狂冲向黑暗的列车！初五面见皇上。我怕隔墙有耳，不敢告诉您谭嗣同夜会我的情景，我只能说，年轻官员，阁历太浅，做事不能慎密，倘有疏忽，累及皇上，关系极重，望皇上十分留意，才是天下之兴。臣，不敢不冒死直陈！", "page": 33, "y": 290, "col": 1, "kind": "dialogue", "chapter": 12}, {"id": 1441, "speaker": "康有为", "text": "臣多想带皇上一起逃亡，去等待机会c皇上，您在紫禁城还好么？", "page": 33, "y": 651, "col": 1, "kind": "dialogue", "chapter": 12}, {"id": 1442, "speaker": "袁世凯", "text": "皇上，您在紫禁城还好么？", "page": 33, "y": 754, "col": 1, "kind": "dialogue", "chapter": 12}, {"id": 1443, "speaker": "梁启超", "text": "皇上，您在紫禁城还好么？", "page": 33, "y": 805, "col": 1, "kind": "dialogue", "chapter": 12}, {"id": 1444, "speaker": "舞台提示", "text": "[光绪，摇摇头。", "page": 33, "y": 857, "col": 1, "kind": "stage", "chapter": 12}, {"id": 1445, "speaker": "袁世凯", "text": "（合）肯定不好。", "page": 33, "y": 960, "col": 1, "kind": "dialogue", "chapter": 12}, {"id": 1446, "speaker": "舞台提示", "text": "[多媒体：大雪纷飞。", "page": 33, "y": 1062, "col": 1, "kind": "stage", "chapter": 12}, {"id": 1447, "speaker": "康有为", "text": "皇上，臣逃亡前为您做的最后一件事，即是在八月初四，冲进日本公使馆，面向伊藤博文陈述中国变法之困境，请伊藤博文在面见太后时，提出变法的重要性，做大清变法的顾问，支持皇上。", "page": 33, "y": 1114, "col": 1, "kind": "dialogue", "chapter": 12}, {"id": 1448, "speaker": "梁启超", "text": "皇上！我将乘日本横滨丸邮船，离沪南下，做一名活着的懦夫！我写了一首《去国行》——“君恩友仇两未报，死于贼手毋乃非英雄。割慈忍泪出国门，掉头不顾吾其东。", "page": 33, "y": 1373, "col": 1, "kind": "dialogue", "chapter": 12}, {"id": 1449, "speaker": "舞台提示", "text": "[幕外：火车声隐去。", "page": 33, "y": 1629, "col": 1, "kind": "stage", "chapter": 12}, {"id": 1450, "speaker": "舞台提示", "text": "[灯光：照亮光绪，隐去火车。", "page": 33, "y": 1681, "col": 1, "kind": "stage", "chapter": 12}, {"id": 1451, "speaker": "光绪", "text": "八月初五，伊藤博文觐见，我没有提出重用他做大清变法顾问的言辞。因为八月初四，太后从颐和园驾临紫禁城。我对变法第一次口是心非。", "page": 33, "y": 1734, "col": 1, "kind": "dialogue", "chapter": 12}, {"id": 1452, "speaker": "舞台提示", "text": "[幕外：火车声即响起（合）情，我若有情！我便要信守承诺，忠于皇上！", "page": 33, "y": 1939, "col": 1, "kind": "stage", "chapter": 12}, {"id": 1453, "speaker": "舞台提示", "text": "[康有为、袁世凯，站起。（合）围园劫后！", "page": 33, "y": 2093, "col": 1, "kind": "stage", "chapter": 12}, {"id": 1454, "speaker": "舞台提示", "text": "[异禀，递上报纸。", "page": 34, "y": 342, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1455, "speaker": "康有为", "text": "我在逃亡中的英国轮船上，看到了一张Newspaper。八月初六，皇上降旨捉拿康有为。", "page": 34, "y": 395, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1456, "speaker": "舞台提示", "text": "[幕外：火车声隐去。", "page": 34, "y": 498, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1457, "speaker": "舞台提示", "text": "[灯光：隐去火车。", "page": 34, "y": 550, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1458, "speaker": "光绪", "text": "面对已经写好的圣旨，我只能点头。", "page": 34, "y": 602, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1459, "speaker": "舞台提示", "text": "[幕外：火车声即起。", "page": 34, "y": 654, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1460, "speaker": "袁世凯", "text": "因为八月初六，太后宣布训政！", "page": 34, "y": 706, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1461, "speaker": "康有为", "text": "袁世凯，我与你不共戴天，你个人民鳖孙！", "page": 34, "y": 758, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1462, "speaker": "舞台提示", "text": "[康有为向袁也凯挥动拳头。", "page": 34, "y": 809, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1463, "speaker": "舞台提示", "text": "[幕外：火车声收。", "page": 34, "y": 861, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1464, "speaker": "异禀", "text": "康老师，知识分子不许打人！", "page": 34, "y": 913, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1465, "speaker": "康有为", "text": "知识分子不打好人", "page": 34, "y": 966, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1466, "speaker": "舞台提示", "text": "[被打倒在地的袁世凯，愤懑着。", "page": 34, "y": 1017, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1467, "speaker": "袁世凯", "text": "我的好名声，死在了戊戌年9月28日。谭嗣同！你就是我的克星，你知道吗！", "page": 34, "y": 1069, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1468, "speaker": "康有为", "text": "袁世凯，你站起来！你要承担历史的罪责。", "page": 34, "y": 1173, "col": 0, "kind": "dialogue", "chapter": 12}, {"id": 1469, "speaker": "舞台提示", "text": "[幕外：辉煌的宫廷音乐响起。", "page": 34, "y": 1224, "col": 0, "kind": "stage", "chapter": 12}, {"id": 1470, "speaker": "舞台提示", "text": "[多媒体：字幕“第十三章节粉身殒命太后训政”", "page": 34, "y": 1275, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1471, "speaker": "舞台提示", "text": "[慈禧，光绪、李莲英、荣禄、恭亲王、李鸿章，大臣们出现", "page": 34, "y": 1379, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1472, "speaker": "舞台提示", "text": "[袁世凯，跪地", "page": 34, "y": 1483, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1473, "speaker": "袁世凯", "text": "围园劫后，杀荣禄，夺兵权，都是谭嗣同的主意。", "page": 34, "y": 1536, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1474, "speaker": "舞台提示", "text": "[袁世凯，爬走。", "page": 34, "y": 1639, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1475, "speaker": "慈禧", "text": "康有为叛逆，图谋于我！你知道还是不知道？或者你也是同谋？！", "page": 34, "y": 1692, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1476, "speaker": "光绪", "text": "（停顿）……知道！", "page": 34, "y": 1795, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1477, "speaker": "慈禧", "text": "既知道，还不将康有为正法，反要放走？！", "page": 34, "y": 1847, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1478, "speaker": "荣禄", "text": "臣派人查到记载，此人年轻时，因为没考上乡试，心情沮丧，习禅打坐，竟闹到哭笑无常的程度。据医师讲，此类病人，若正常求医，则其疾不至深人也，若病人以此“佯狂”而自傲，就可能变成疯子。做疯子当个学者，也就罢了，但不能参政。", "page": 34, "y": 1899, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1479, "speaker": "慈禧", "text": "我养育你二十余年，你听信狂浪小人，图谋劫持我？！", "page": 34, "y": 290, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1480, "speaker": "光绪", "text": "我，绝没有这个意思。", "page": 34, "y": 395, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1481, "speaker": "慈禧", "text": "你为了不做亡国之君，自己亡国。没有我，还能有你吗？！我这么做是为了大清！围园劫后，我不能原谅你！合邦，放洋人进来，侵占大清！还有扶桑倭寇伊藤博文，骑到我大清脖子上做政治顾问？！大清转瞬就是日本人的！你对大清犯下的这两宗重罪，无法饶恕！拟旨，宣布戊戌变法为“戊戌政变”！", "page": 34, "y": 446, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1482, "speaker": "舞台提示", "text": "[幕外：一声锣响", "page": 34, "y": 861, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1483, "speaker": "众大臣", "text": "（合）太后圣明", "page": 34, "y": 913, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1484, "speaker": "慈禧", "text": "下令京师戒严，火车停驶，缉捕新党，新政尽废，恢复旧法。我宣布训政！", "page": 34, "y": 965, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1485, "speaker": "舞台提示", "text": "[四位老臣，下跪太后。", "page": 34, "y": 1069, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1486, "speaker": "慈禧", "text": "你总说大清颜面何在，现在，我就还以大清颜面。", "page": 34, "y": 1172, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1487, "speaker": "荣禄", "text": "圣旨下！", "page": 34, "y": 1276, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1488, "speaker": "舞台提示", "text": "[幕外：“希望”音乐响起", "page": 34, "y": 1328, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1489, "speaker": "李莲英", "text": "重用小臣，一个不饶谭嗣同。刘光第林旭杨锐。", "page": 34, "y": 1379, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1490, "speaker": "舞台提示", "text": "[谭嗣同及妻子、刘光第及妻子、杨锐及妻子、林旭及妻子，走出。", "page": 34, "y": 1639, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1491, "speaker": "荣禄", "text": "不要再念了，这些名字脏了我的耳朵。", "page": 34, "y": 1742, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1492, "speaker": "舞台提示", "text": "[李鸿章，向前走到下场口侧座；恭亲王，退后移步到后区座位。", "page": 34, "y": 1794, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1493, "speaker": "李鸿章", "text": "我本来是支持维新的，现在想来可笑之极", "page": 34, "y": 1898, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1494, "speaker": "李莲英", "text": "命都没了，还怎么笑啊。", "page": 34, "y": 1949, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1495, "speaker": "舞台提示", "text": "[四章京，与妻子携手而立。]", "page": 34, "y": 2002, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1495001, "speaker": "谭妻", "text": "轮台东门送君去！", "page": 34, "y": 2002, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1495002, "speaker": "刘妻", "text": "去时雪满路天山。", "page": 34, "y": 2002, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1495003, "speaker": "杨妻", "text": "峰回路转君不见！", "page": 35, "y": 2002, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1495004, "speaker": "林妻", "text": "千山暮雪何处归。", "page": 35, "y": 2002, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1496, "speaker": "杨锐", "text": "相逢难信掬土黄！", "page": 35, "y": 345, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1497, "speaker": "林旭", "text": "留待狂歌天妒贤", "page": 35, "y": 396, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1498, "speaker": "刘光第", "text": "千秋别过愁万古！", "page": 35, "y": 448, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1499, "speaker": "谭嗣同", "text": "再盼魂归聚欢颜。", "page": 35, "y": 499, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1500, "speaker": "众人", "text": "（合）我们即将告别生活", "page": 35, "y": 551, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1501, "speaker": "谭嗣同", "text": "我想天上一切的杰作，都是星辰流转，过去了，就要无所顾惜", "page": 35, "y": 603, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1501001, "speaker": "谭妻", "text": "我祈求佛祖给我们一次束缚，因为会琴瑟和鸣，因为会心心相印", "page": 35, "y": 603, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1502, "speaker": "谭嗣同", "text": "博览地下，万事万物自是缘起缘灭，都是此消彼长。离开了就别牵挂。", "page": 35, "y": 809, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1502001, "speaker": "谭妻", "text": "仰望上苍，我只见彩云逐月，我只看星月相依。", "page": 35, "y": 809, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1503, "speaker": "谭嗣同", "text": "我想面对面地大声对你说，我毁灭自己的身体，是拿去投掷腐朽！是拿去投掷腐败！是拿去投掷不堪的大清！", "page": 35, "y": 1016, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1503001, "speaker": "谭妻", "text": "如有厄运，妾身情愿身代！", "page": 35, "y": 1016, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1504, "speaker": "林旭", "text": "我的新婚爱妻，我苦思容颜！", "page": 35, "y": 1222, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1504001, "speaker": "林妻", "text": "佳人思君，不见君！", "page": 35, "y": 1222, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1505, "speaker": "林旭", "text": "征鸿飞尽", "page": 35, "y": 1326, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1505001, "speaker": "林妻", "text": "无雁传情……", "page": 35, "y": 1326, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1506, "speaker": "林旭", "text": "没想，一死绝情！", "page": 35, "y": 1429, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1506001, "speaker": "林妻", "text": "妾想随君行！（哭）", "page": 35, "y": 1429, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1507, "speaker": "刘光第", "text": "好古忽今……", "page": 35, "y": 1532, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1507001, "speaker": "刘妻", "text": "苒苒无音信……", "page": 35, "y": 1532, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1508, "speaker": "刘光第", "text": "怨恨无意。", "page": 35, "y": 1635, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1508001, "speaker": "刘妻", "text": "风打泪莹然。", "page": 35, "y": 1635, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1509, "speaker": "刘光第", "text": "我死。", "page": 35, "y": 1738, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1509001, "speaker": "刘妻", "text": "不能。", "page": 35, "y": 1738, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1510, "speaker": "刘光第", "text": "就是这个民族的退化！", "page": 35, "y": 1841, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1511, "speaker": "杨锐", "text": "愚昧横亘了己被摧毁的大清，这是我的选择吗？满目疮痍、瓦砾，蔽日阴云滚滚", "page": 35, "y": 1893, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1511001, "speaker": "杨妻", "text": "离别乍苦，肝肠痛断！", "page": 35, "y": 1893, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1512, "speaker": "林旭", "text": "你们破坏我的婚姻，破坏我的家庭！你们破坏我聪明、贤惠、才女妻子的无辜！", "page": 35, "y": 2048, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1513, "speaker": "舞台提示", "text": "[刚毅，上前", "page": 35, "y": 243, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1514, "speaker": "刚毅", "text": "你算什么无辜，煽乱谋反，破坏大清子民的幸福，你当死上千遍！", "page": 35, "y": 295, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1515, "speaker": "谭嗣同", "text": "当我必须面对死时，我必须要给自己一个必须去死的理由！作为变法人士我必死！在我即死之际，我想向国家呐喊！不变法不图强，就是灭亡吗？不变法不图强，必然灭亡！变法之中肯定有问题，那都不是事！只能走这条路！因为不图强，就消亡！", "page": 35, "y": 398, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1516, "speaker": "三章京", "text": "不变化，不生长，不自强，就消亡！您对国家，重爱难抵！情，我又怎能深情地活着！", "page": 35, "y": 708, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1517, "speaker": "刘光第", "text": "这就是我支持皇上变法的事业（合）绝望的人不是我，绝望的是大清！", "page": 35, "y": 914, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1518, "speaker": "刘光第", "text": "我本来是怕死的（合）可现在，这都不是事！", "page": 35, "y": 1069, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1519, "speaker": "舞台提示", "text": "[李莲英，上前", "page": 35, "y": 1224, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1520, "speaker": "李莲英", "text": "闭嘴，不要说了！", "page": 35, "y": 1275, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1521, "speaker": "刚毅", "text": "闭嘴，不要说了！", "page": 35, "y": 1327, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1522, "speaker": "刘光第", "text": "我不闭嘴，我要控告大清刑部，你们不符合大清律法，没有审讯就杀人！我不服！", "page": 35, "y": 1379, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1523, "speaker": "林旭", "text": "我死到临头必须得说！我是忠于皇上的！皇上是要改革而不是其他！", "page": 35, "y": 1482, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1524, "speaker": "舞台提示", "text": "[慈僖，座榻慢慢向前推进", "page": 35, "y": 1586, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1525, "speaker": "杨锐", "text": "现在事情搞得这么极端，是我没有料到的！", "page": 35, "y": 1637, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1526, "speaker": "三章京", "text": "但是，我告诉你们，我没有必死的责任！", "page": 35, "y": 1688, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1527, "speaker": "舞台提示", "text": "[慈禧，座榻靠近刘光第、林旭，两人倒地", "page": 35, "y": 1740, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1528, "speaker": "刘光第", "text": "我是支持皇上的维新派。", "page": 35, "y": 1792, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1529, "speaker": "杨锐", "text": "不是以康有为“康党”为首的维新派！", "page": 35, "y": 1843, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1530, "speaker": "林旭", "text": "我上班13天，我还什么都没干呢！", "page": 35, "y": 1895, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1531, "speaker": "刚毅", "text": "暴虎冯河，死而无悔者，愚忠！", "page": 35, "y": 1947, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1532, "speaker": "杨锐", "text": "我在学说上不认同康有为，这个皇上是知道的。康先生远不如我的恩师张之洞大人。皇上变法并不是听康有为一人之说，皇上变法早有此意！", "page": 35, "y": 1998, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1533, "speaker": "刘光第", "text": "凡属重大改革，都要于法有据！法者，天下之准绳！如果你们按大清律法审讯我，我会明确告诉你们，我不是你们说的“康有为为首的维新乱党”。你们混淆逻辑，我不服！", "page": 36, "y": 294, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1534, "speaker": "杨锐", "text": "我们是张之洞大人的学生。我们本来想让张之洞大人主持变法。", "page": 36, "y": 500, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1535, "speaker": "林旭", "text": "中国从来都是一个人情社会，都是于情于理，而不是于理于情。", "page": 36, "y": 605, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1536, "speaker": "杨锐", "text": "我想死得明白！你们如此混淆一烩，你们这不扯淡吗！异禀，你想得这么激烈吗？", "page": 36, "y": 708, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1537, "speaker": "异禀", "text": "师父，是您想得太激烈。他们死前都没有申诉，你们说（合）我们没话了，说完了。", "page": 36, "y": 863, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1538, "speaker": "恭亲王", "text": "我来说说。我己经离去，你们也即将离开。那我们就说句话。", "page": 36, "y": 1070, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1539, "speaker": "舞台提示", "text": "[刚毅，拿话筒。恭亲王，示意不用", "page": 36, "y": 1173, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1540, "speaker": "恭亲王", "text": "变法没有错，错在你们操之过急！商鞅变法，自公元前356年变起，至公元前221年，始皇帝搞出“秦政法”约130余年，继续向前“转进”，又实验了100余年，至汉武帝加强中央集权，文官制和重农轻商的帝国雏形才“定型”下来。转型期延绵300年之久。面对这个古老大国，疆域之阔，民众之多，转型必然艰难。变法大清，就该当做铺路石，前赴后继！在历史的长河中，个人是渺小的，然桑田岁岁枯荣，大江旦夕东去。该当建设的就建设，该当牺牲的就牺牲！就像庙里的五百罗汉一样，个人有个人的位置。太后，您说是吧？", "page": 36, "y": 1225, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1541, "speaker": "慈禧", "text": "同意！但不能同意更多。变法，要变。无有死者，不以召后起。嗯，你们死的理由找到了。", "page": 36, "y": 1898, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1542, "speaker": "恭亲王", "text": "太后圣明。", "page": 36, "y": 2001, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1543, "speaker": "慈禧", "text": "我怎么会跟你对话？难道我也要“", "page": 36, "y": 2053, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1544, "speaker": "舞台提示", "text": "[幕外：大提琴音乐", "page": 36, "y": 2104, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1545, "speaker": "慈禧", "text": "离去。", "page": 36, "y": 241, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1546, "speaker": "舞台提示", "text": "[光绪，站起走向前，四章京，跪在地上。", "page": 36, "y": 292, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1547, "speaker": "光绪", "text": "中国，是一个有着特殊历史文化的亚洲式社会，必须要西式和现代化起来！这是你起小就教给我的！我怎么会跟你对话……", "page": 36, "y": 345, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1548, "speaker": "舞台提示", "text": "[恭亲王，退去坐在后区。", "page": 36, "y": 500, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1549, "speaker": "光绪", "text": "难道我也将离去……", "page": 36, "y": 552, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1550, "speaker": "舞台提示", "text": "[幕外：磬声一响。", "page": 36, "y": 603, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1551, "speaker": "光绪", "text": "我若能早生2年，也不失为一代圣主明君！", "page": 36, "y": 655, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1552, "speaker": "慈禧", "text": "当明君、做贤相，自有其固定的规律可循你们说说我们古国文明里的道德标准。", "page": 36, "y": 758, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1553, "speaker": "众人", "text": "（合）孔孟之道、四维八德、纲维律法、固体之本。这规律，是数千年，数亿万劳碌子民，和数不清的明君贤相的智慧与经验，慢慢积累而得。", "page": 36, "y": 862, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1554, "speaker": "光绪", "text": "朕的爱卿们，你把张文襄公的“五知”讲给他们听！", "page": 36, "y": 1070, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1555, "speaker": "杨锐", "text": "、知耻！", "page": 36, "y": 1173, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1556, "speaker": "四章京", "text": "耻不如日本", "page": 36, "y": 1225, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1557, "speaker": "刘光第", "text": "、知惧！", "page": 36, "y": 1277, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1558, "speaker": "四章京", "text": "惧为印度，惧为越南", "page": 36, "y": 1328, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1559, "speaker": "林旭", "text": "、知变！", "page": 36, "y": 1380, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1560, "speaker": "四章京", "text": "不变其习，不能变法。", "page": 36, "y": 1431, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1561, "speaker": "谭嗣同", "text": "四、知要！", "page": 36, "y": 1483, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1562, "speaker": "四章京", "text": "西艺非要，西政为要。", "page": 36, "y": 1535, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1563, "speaker": "光绪", "text": "五、知本！", "page": 36, "y": 1587, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1564, "speaker": "四章京", "text": "海外不忘国、异俗不忘亲、智巧不忘圣", "page": 36, "y": 1638, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1565, "speaker": "舞台提示", "text": "[四章京，对光绪磕头。", "page": 36, "y": 1690, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1566, "speaker": "光绪", "text": "亲爸爸，我是爱您的！我永远不会站在你的对立面。如果你对我失望，我是最难过的，我想尽力配合，我想变法顺利，我怕你对我不满意。可在中国的历史上我是一个儿皇帝，我尽力了，我不想让您丢脸，也不想让大清亡国。可是面对如此国运，我无能为力！", "page": 36, "y": 1742, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1567, "speaker": "舞台提示", "text": "[光绪，给慈禧下跪", "page": 36, "y": 2104, "col": 1, "kind": "stage", "chapter": 13}, {"id": 1568, "speaker": "慈禧", "text": "如果我是一个卓越的政治家，皇帝依然在紫禁城主政，六君子也不会人头落地，变法依旧进行。可我没有坐正大清朝皇太后的位置，刹那间我是一个伤心已极的母亲。我没有更高超的智慧，我对不起列祖列宗！但是，镇压维新派是对的，不镇压就亡国了！打小我就把你接进宫，哄你睡觉，陪你读书，教你写字，教你画画。你伤透了我的心。我起小儿进宫，我的住处的头顶上方悬挂着乾隆爷的亲笔匾额“敬修内则”，告诫后宫嫔妃，严格遵守祖宗家法行事，谨慎规范自己的一切言行。这就是我一生的戒律。作为大清朝的媳妇，我不能称帝。但是，我不能看着这些人祸害社稷！我是三度垂帘听政，两次决定皇位继承人。我不坐这儿，难不成你们来！这大清王朝到底往哪儿走？不是我说了就算的，不管你心里有多火急火燎，也不能急手忙脚。大清朝的脚步，得走得稳稳当当，得有个悠闲自在的大国气象。说我亡了大清朝，那他们也太高看了我，如果说我昏庸无能，却统治了大清朝47年，那你们也太小瞧了你们自己。", "page": 37, "y": 234, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1569, "speaker": "舞台提示", "text": "[四章京，起身，面向慈禧。", "page": 37, "y": 1425, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1570, "speaker": "恭亲王", "text": "江山面前，都是匆匆过客，千秋万载，留下的是王朝的背影。", "page": 37, "y": 1477, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1571, "speaker": "舞台提示", "text": "[恭亲王，下场", "page": 37, "y": 1581, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1572, "speaker": "慈禧", "text": "乱党羽翼，即行正法！", "page": 37, "y": 1633, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1573, "speaker": "舞台提示", "text": "[幕外：京剧锣鼓点，“南无阿弥陀佛”响起", "page": 37, "y": 1685, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1574, "speaker": "舞台提示", "text": "[光绪、慈禧，老臣退去。", "page": 37, "y": 1736, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1575, "speaker": "光绪", "text": "光绪，是爱天下的！", "page": 37, "y": 1788, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1576, "speaker": "四章京", "text": "皇上圣明！我们死了，死在1898年清新的空气里，死在了北京秋高气爽的时节！", "page": 37, "y": 1839, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1577, "speaker": "舞台提示", "text": "[多媒体：恢复法源寺院墙。", "page": 37, "y": 1943, "col": 0, "kind": "stage", "chapter": 13}, {"id": 1578, "speaker": "异禀", "text": "虽然佛教说生是偶然，死是必然，对生死要抱有平淡的态度，但是我不想叫她奶奶了，因为她杀生了。", "page": 37, "y": 1995, "col": 0, "kind": "dialogue", "chapter": 13}, {"id": 1579, "speaker": "普净", "text": "她那叫杀人，“千古艰难小生死，万代权衡大是非。", "page": 37, "y": 236, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1580, "speaker": "四章京", "text": "谢谢师父", "page": 37, "y": 339, "col": 1, "kind": "dialogue", "chapter": 13}, {"id": 1581, "speaker": "舞台提示", "text": "[多媒体：字幕“第十四章千古艰难万代权衡”", "page": 37, "y": 391, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1582, "speaker": "刘光第", "text": "我叫刘光第，戊戌变法重要代表人物之我的墓地，在四川省自贡赵化镇我的老家，罗汉寺内。1984年，自贡人民政府决定把我迁葬到五府山革命烈士陵园，原中国佛教协会会长赵朴初先生为我题写了墓碑。后世记载，赵朴初陪日本人游历峨眉山清音阁，介绍说他素为敬重刘光第的道德才华。我的道德才华是受我母亲的启蒙。父亲去世早，母亲卖掉房子供我私塾读书，要求我做人第一巛，必须干净，从容、大方、温良诚恳、仪表堂堂。我个头有一米八，是维新派中公认的帅哥。光绪九年，光第二十四岁，赴京会试，中二甲进士，职分刑部候补主事，就是司法部有处级职称的一个干部名额，工资很低。光第性格内向、孤介。光第给自己的座右铭是：勤勉，廉正，谨慎，公心。", "page": 37, "y": 495, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1583, "speaker": "舞台提示", "text": "[多媒体：字幕“公”", "page": 37, "y": 1375, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1584, "speaker": "刘光第", "text": "上班不搓麻将，下班不谈女人，不瞧戏，不斗酒。家离单位很远，买不起马车，也租不起人力车，每日来去步行，风雨无阻按时到衙门上班，十年之久。苦于无钱，常有罢去返乡教书的打算，就在我已心有决定，等待家乡寄来的款项一到，就即刻挂职返乡的当口，湖南巡抚陈宝箴举荐我，我见到了皇上！惟皇恩深重，急切不忍离去。我今年39岁，我的命运“", "page": 37, "y": 1427, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1585, "speaker": "舞台提示", "text": "[刘光第，回身看见走上场的林旭", "page": 37, "y": 1893, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1586, "speaker": "舞台提示", "text": "[刘光第，走到侧座。", "page": 37, "y": 1945, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1587, "speaker": "林旭", "text": "我叫林旭，戊戌变法六君子之一我死的时候，24岁。后世记载我死前仰天长啸：“君子死，正义尽！”然后大笑，声若洪钟后世又记载，我被砍成了两节，砍头，不是腰斩，瞎说！刽子手是门手艺，除非我乱跑，他们情急砍成两截，不合逻辑。我死了，生命永远定在郁郁葱葱的青春期，有着永远的一个“翠”。（笑得灿烂）", "page": 37, "y": 1996, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1588002, "speaker": "舞台提示", "text": "[多媒体：字幕“翠”。]", "page": 38, "y": 495, "col": 0, "kind": "stage", "chapter": 14}, {"id": 1588, "speaker": "林妻", "text": "“我已君休，万千悔恨更何尤？（与林旭合）拼得眼中无尽泪……”", "page": 38, "y": 495, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1589, "speaker": "林旭", "text": "我的妻，沈鹊应，是个才女，这是她写的诗文祭奠。生前我也写诗：“娇妻尚在江表，莫得一面，英烈之性，必从吾死……”死后她又写……", "page": 38, "y": 651, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1589001, "speaker": "林妻", "text": "“伊何人？我何人？生不见，死不见，但愿三生有幸，来世再结姻缘。”", "page": 38, "y": 651, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1590, "speaker": "林旭", "text": "才女的爱！她用各种方式在我死后不到半年，香消玉殒，24岁。夫妻二人安葬一处，墓联云……", "page": 38, "y": 960, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1590001, "speaker": "林旭、林妻", "text": "（合）千秋晚翠孤忠草，一卷崦楼绝命词。", "page": 38, "y": 960, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1591, "speaker": "林旭", "text": "哦，我是个官三代，我妻子……", "page": 38, "y": 1217, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1591001, "speaker": "林妻", "text": "是两江总督沈葆桢的孙女。", "page": 38, "y": 1217, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1592, "speaker": "林旭", "text": "我是沈大人的孙女婿", "page": 38, "y": 1320, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1593, "speaker": "舞台提示", "text": "[林旭，与妻子，转身走向后区。", "page": 38, "y": 1370, "col": 0, "kind": "stage", "chapter": 14}, {"id": 1594, "speaker": "舞台提示", "text": "[杨锐，上场。", "page": 38, "y": 1422, "col": 0, "kind": "stage", "chapter": 14}, {"id": 1595, "speaker": "杨锐", "text": "1898年9月23日，杨锐被捕，关进刑部大牢。两广两江及湖广总督张之洞闻讯，急电盛宣怀，请顺天府尹夔及户部尚书、协力大学士王文韶，设法营救。同时致电在北京的湖北按察使，提出杨锐是由湖南巡抚陈宝箴大人保荐，与康有为康党并无过密瓜葛电文恳请军机大臣兼礼部侍郎刚毅大人帮忙。但是，我得罪过刚毅大人，曾说过他刚愎无知，他岂肯帮我", "page": 38, "y": 1474, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1596, "speaker": "舞台提示", "text": "[多媒体：字幕“竹”", "page": 38, "y": 1937, "col": 0, "kind": "stage", "chapter": 14}, {"id": 1597, "speaker": "杨锐", "text": "杨锐，四川省绵竹县人，出身书香之家。年轻时参加院试，张之洞比我为蜀中当代的苏轼。任职期间，凡送呈朝廷的奏疏，大多出自杨锐之手。我一生最为得意的是光绪十五年，授内阁中书，修纂的《大清会典》。我，性喜寒，爱诗文，在我的精神世界里，总有那么一个人，负剑独行，登高临远。感谢家乡人民。以我的名字命名的“杨锐广场”位于四川省绵竹市人民公园内。", "page": 38, "y": 1989, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1598, "speaker": "舞台提示", "text": "[幕外：音乐停止磬声三响。", "page": 38, "y": 547, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1599, "speaker": "舞台提示", "text": "[谭嗣同，走上。", "page": 38, "y": 599, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1600, "speaker": "异禀", "text": "停！我特别不愿意再看下去了，哥，你坐下。", "page": 38, "y": 651, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1601, "speaker": "普净", "text": "你不是很崇拜他吗？", "page": 38, "y": 702, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1602, "speaker": "异禀", "text": "是的。", "page": 38, "y": 753, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1602001, "speaker": "普净", "text": "那为什么不听人家说说？", "page": 38, "y": 753, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1603, "speaker": "异禀", "text": "谭大哥是修行之人，为什么要遭此横祸呢？我们修行之人是为了要积福积德，大哥怎么会有这样的下场，我没有信心了。我就快消极了。", "page": 38, "y": 856, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1604, "speaker": "谭嗣同", "text": "你的恐惧是源自你的心魔", "page": 38, "y": 1062, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1605, "speaker": "异禀", "text": "那我就心魔吧，我克服不了。", "page": 38, "y": 1113, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1606, "speaker": "舞台提示", "text": "[李闰，抱着一个盆，走出。", "page": 38, "y": 1164, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1607, "speaker": "异禀", "text": "大哥，你说吧", "page": 38, "y": 1216, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1608, "speaker": "舞台提示", "text": "[幕外：《浏阳河》音乐起。", "page": 38, "y": 1267, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1609, "speaker": "谭嗣同", "text": "我看见我的妻子。", "page": 38, "y": 1319, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1610, "speaker": "舞台提示", "text": "[多媒体：谭嗣同老家，浏阳大夫第院内。", "page": 38, "y": 1370, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1611, "speaker": "谭嗣同", "text": "她抱着个木盆，这是要洗衣服，还是去做饭？李闰！", "page": 38, "y": 1422, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1612, "speaker": "异禀", "text": "大嫂", "page": 38, "y": 1526, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1613, "speaker": "谭嗣同", "text": "我们家在湖南浏阳，座北朝南，房屋有24间，两处天井，是江南庭院式的一座大夫第，是我祖父谭学琴置办下的，民居的建筑风格", "page": 38, "y": 1577, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1614, "speaker": "舞台提示", "text": "[谭妻李闰，下场拿东西。", "page": 38, "y": 1782, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1615, "speaker": "谭嗣同", "text": "前院是李闰的卧房和客厅，最深处是我和父亲的卧室、会客厅和书房。只要将门关上，闹市的嘈杂就挡在了门外，庭院幽静得听不到一点儿外面的喧闹", "page": 38, "y": 1834, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1616, "speaker": "舞台提示", "text": "[谭妻李闰，再次上场", "page": 38, "y": 2040, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1617, "speaker": "谭嗣同", "text": "依稀得见生活仍旧，只是不幸福了许多。", "page": 38, "y": 2091, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1617001, "speaker": "谭妻", "text": "我自杀了一回，没死成。我给你写了首诗。“前尘往事不可追，一成相思一层灰。来世化作采莲人，与君相逢横塘水。”", "page": 38, "y": 2091, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1618, "speaker": "谭嗣同", "text": "生死关头，年尽月尽，日时俱尽。", "page": 39, "y": 395, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1618001, "speaker": "谭妻", "text": "未免虚度此一生。如不于此时脚跟立定……", "page": 39, "y": 395, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1619, "speaker": "谭嗣同", "text": "做个顶天立地。", "page": 39, "y": 498, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1619001, "speaker": "谭妻", "text": "便百千年，亦只是虚度。", "page": 39, "y": 498, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1620, "speaker": "谭嗣同", "text": "只听楼上五更钟，大地冰清，凡圣路绝。", "page": 39, "y": 601, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1620001, "speaker": "谭妻", "text": "何处出身，何处落脚？", "page": 39, "y": 601, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1621, "speaker": "谭嗣同", "text": "我不可东去西去，只向万里，无寸草处去！", "page": 39, "y": 704, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1622, "speaker": "舞台提示", "text": "[谭妻李闰，下场。", "page": 39, "y": 755, "col": 0, "kind": "stage", "chapter": 14}, {"id": 1623, "speaker": "舞台提示", "text": "[幕外：人群嘈杂声，叫卖声。", "page": 39, "y": 807, "col": 0, "kind": "stage", "chapter": 14}, {"id": 1624, "speaker": "谭嗣同", "text": "我看见菜市口人声鼎沸，看砍头的人群摩肩接踵，叫卖声此起彼伏，豆汁、油条炸糕、焦圈、糖卷果……我死前大声疾呼，有心杀贼、无力回天、死得其所、快哉快哉！人群声浪很大，听见没听见的，那也就算了。", "page": 39, "y": 858, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1625, "speaker": "异禀", "text": "你们都听着点儿！", "page": 39, "y": 1166, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1626, "speaker": "谭嗣同", "text": "我在狱中曾写一（大声，合）望门投止思张俭，忍死须臾待杜根！", "page": 39, "y": 1218, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1627, "speaker": "谭嗣同", "text": "我自横刀向天笑，去留肝胆两昆仑！", "page": 39, "y": 1373, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1628, "speaker": "异禀", "text": "有人说，你这诗也有人改动！这不是你写的原话，没那么英勇！", "page": 39, "y": 1424, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1629, "speaker": "谭嗣同", "text": "我记不真切了，不过确实是我选择了死。", "page": 39, "y": 1527, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1630, "speaker": "异禀", "text": "我就认这四句，就这四句。大哥，我认了！", "page": 39, "y": 1578, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1631, "speaker": "谭嗣同", "text": "我听见了几声叫好声，是为我，还是为刽子手这位老兄的手艺！", "page": 39, "y": 1630, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1632, "speaker": "普净", "text": "听说砍了三刀，怎么可能是为手艺！", "page": 39, "y": 1733, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1633, "speaker": "异禀", "text": "大哥，这六君子里，就你觉得你死得不冤", "page": 39, "y": 1785, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1634, "speaker": "谭嗣同", "text": "国家空虚，社稷不保，我想革命，但没坚持，我支持了康有为。他有他的智慧，我有我的信仰，我在狱中抄了一遍地藏菩萨本愿经。", "page": 39, "y": 1836, "col": 0, "kind": "dialogue", "chapter": 14}, {"id": 1635, "speaker": "舞台提示", "text": "[谭嗣同、异禀，并排同行向前。（合）地藏菩萨发愿地狱不空，誓不成佛我想我今生顶天立地，来生必仗剑天涯，看明月天山外，苍茫云海间。风景不殊，山河尤是，人民小康", "page": 39, "y": 2042, "col": 0, "kind": "stage", "chapter": 14}, {"id": 1636, "speaker": "异禀", "text": "被捕前，你写了一堆你父亲骂你的信。", "page": 39, "y": 395, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1637, "speaker": "谭嗣同", "text": "我模仿他的笔迹，保全了家庭，我是个孝子。", "page": 39, "y": 446, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1638, "speaker": "异禀", "text": "大哥，你是个孝子。", "page": 39, "y": 497, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1639, "speaker": "谭嗣同", "text": "对，我是个孝子。", "page": 39, "y": 549, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1640, "speaker": "舞台提示", "text": "[幕外：《春歌》音乐响起。", "page": 39, "y": 600, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1641, "speaker": "舞台提示", "text": "[多媒体：法源寺院墙", "page": 39, "y": 651, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1642, "speaker": "谭嗣同", "text": "我的同事……", "page": 39, "y": 703, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1643, "speaker": "异禀", "text": "有两个不是大哥同事的", "page": 39, "y": 756, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1644, "speaker": "谭嗣同", "text": "也跟我们一起走了。", "page": 39, "y": 806, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1645, "speaker": "舞台提示", "text": "[杨深秀，向前。", "page": 39, "y": 858, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1646, "speaker": "杨深秀", "text": "杨深秀，山西闻喜县人。", "page": 39, "y": 910, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1647, "speaker": "普净", "text": "一位守正不阿，轻生重义的豪杰御史", "page": 39, "y": 961, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1648, "speaker": "杨深秀", "text": "过奖！", "page": 39, "y": 1012, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1649, "speaker": "普净", "text": "在政变已成事实，太后训政举国颤栗之时。", "page": 39, "y": 1063, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1650, "speaker": "杨深秀", "text": "我挺身诘问光绪被黜之故，要慈禧撤帘还政，触怒慈禧，一并构罪", "page": 39, "y": 1115, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1651, "speaker": "普净", "text": "康广仁", "page": 39, "y": 1218, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1652, "speaker": "舞台提示", "text": "[康广仁，向前。", "page": 39, "y": 1270, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1653, "speaker": "康广仁", "text": "31岁，康有为是我的亲哥哥，我名康有溥，字广仁，做过小官，痛恨官场污秽，八股误人，在维新派中担任要职，无心避祸也没有逃难，实在没有被杀的罪状。但是，作为康有为的弟弟，兄弟连累一场。", "page": 39, "y": 1321, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1654, "speaker": "普净", "text": "异禀，上柱香吧。", "page": 39, "y": 1579, "col": 1, "kind": "dialogue", "chapter": 14}, {"id": 1655, "speaker": "舞台提示", "text": "[幕外：一声磬响", "page": 39, "y": 1630, "col": 1, "kind": "stage", "chapter": 14}, {"id": 1656, "speaker": "舞台提示", "text": "[多媒体：字幕“尾声”。", "page": 39, "y": 1681, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1657, "speaker": "舞台提示", "text": "[灯光：照亮舞台", "page": 39, "y": 1732, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1658, "speaker": "舞台提示", "text": "[幕外：鸟鸣中夹杂寺庙诵经的声音，明朗而清净。", "page": 39, "y": 1784, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1659, "speaker": "舞台提示", "text": "[众人做法事。", "page": 39, "y": 1887, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1660, "speaker": "舞台提示", "text": "[舞台：寺庙院内，伫立石碑、石杵、石墩、条案。天幕后，隐约庙宇林立舞台两侧有屏风、晾衣架，架子挂有和尚穿戴的衣物。", "page": 39, "y": 1938, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1661, "speaker": "舞台提示", "text": "[康有为、袁世凯，走上。", "page": 39, "y": 2093, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1662, "speaker": "舞台提示", "text": "[幕外：一声磬响", "page": 40, "y": 240, "col": 0, "kind": "stage", "chapter": 15}, {"id": 1663, "speaker": "康有为", "text": "法源寺，对生者有情！", "page": 40, "y": 291, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1664, "speaker": "袁世凯", "text": "悯忠寺，对死者有意", "page": 40, "y": 344, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1665, "speaker": "康有为", "text": "我为什么会想起你！", "page": 40, "y": 395, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1666, "speaker": "袁世凯", "text": "吾与公，兄弟交也！", "page": 40, "y": 447, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1667, "speaker": "康有为", "text": "你蒙藏交涉不利，被英俄猎取，最终使国家沦为遭到列强瓜分的让地政府。", "page": 40, "y": 499, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1668, "speaker": "袁世凯", "text": "我曾三次致电与你，共商国是，宛如民国初年的三顾茅庐。", "page": 40, "y": 602, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1669, "speaker": "舞台提示", "text": "[幕外：一声磬响。", "page": 40, "y": 706, "col": 0, "kind": "stage", "chapter": 15}, {"id": 1670, "speaker": "康有为", "text": "北上议政，就是让康某做你的军师走狗！", "page": 40, "y": 757, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1671, "speaker": "袁世凯", "text": "我国虽弱，但苟侵我主权，束缚我内政，我必誓死力拒！我再次降低姿态，再三番六次，力邀你帮助国家！", "page": 40, "y": 809, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1672, "speaker": "康有为", "text": "你是窃国、称帝的人民鳖孙！你就是一块钱！", "page": 40, "y": 964, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1673, "speaker": "袁世凯", "text": "康先生，还是放下个人恩怨为国家做点实事儿！（河南话）俺已经去球了！", "page": 40, "y": 1016, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1674, "speaker": "康有为", "text": "你挑了个不错的日子，死在了1916年6月6日", "page": 40, "y": 1120, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1675, "speaker": "袁世凯", "text": "你记得俺死期，倒记得很准确。人生给康先生两次做帝师的机会，你没有珍惜", "page": 40, "y": 1223, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1676, "speaker": "康有为", "text": "至少我还活着。", "page": 40, "y": 1327, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1677, "speaker": "袁世凯", "text": "我忧焚五内，与你们讨袁伐袁有很大关系。无论后世如何评价我袁世凯，我对你康有为一直不错。为这个国家，我尽力了。", "page": 40, "y": 1379, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1678, "speaker": "舞台提示", "text": "[袁世凯，下场", "page": 40, "y": 1533, "col": 0, "kind": "stage", "chapter": 15}, {"id": 1679, "speaker": "舞台提示", "text": "[梁启超，上场", "page": 40, "y": 1584, "col": 0, "kind": "stage", "chapter": 15}, {"id": 1680, "speaker": "康有为", "text": "我如果帮了他，国运是否会强过今夕", "page": 40, "y": 1635, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1681, "speaker": "梁启超", "text": "恩师", "page": 40, "y": 1688, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1682, "speaker": "康有为", "text": "卓如？", "page": 40, "y": 1739, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1683, "speaker": "梁启超", "text": "我是崇拜您的", "page": 40, "y": 1791, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1684, "speaker": "康有为", "text": "我曾骂过你梁贼启超", "page": 40, "y": 1842, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1685, "speaker": "梁启超", "text": "那是因为我写了《辟复辟论》！我指责你帮助张勋复辟。", "page": 40, "y": 1894, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1686, "speaker": "康有为", "text": "你指责我僵化保守，泥古不化，不利于国家进步", "page": 40, "y": 1997, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1687, "speaker": "梁启超", "text": "我指责你。", "page": 40, "y": 2100, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1688, "speaker": "康有为", "text": "你指责我谋逆之首不是贪黩武夫，而是大言不惭！", "page": 40, "y": 242, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1689, "speaker": "梁启超", "text": "历史已经证明了你的失败，孙文主张革命，主张共和，这才是当世之先进。恩师，你曾两次反对我与孙先生交往，国运如此，救世为先，我们同为老乡为什么不能站在同一条战线上……", "page": 40, "y": 345, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1690, "speaker": "康有为", "text": "孙中山是资产阶级民主共和，我是资产阶级维新，我是“帝师”，康圣人……", "page": 40, "y": 604, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1691, "speaker": "梁启超", "text": "老师，您阻碍了探索中国发展的道路，虽然不忍，但我与老师就此缘尽法源寺。", "page": 40, "y": 708, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1692, "speaker": "康有为", "text": "我与袁公因何结怨？复生临死前是否不耻我的逃离？我与卓如为何缘尽此庙？人的冤仇因何而生？为何不解？三十年后……今年是？", "page": 40, "y": 810, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1693, "speaker": "异禀", "text": "1921年", "page": 40, "y": 1018, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1694, "speaker": "康有为", "text": "我想这次来北京，不是暂留、不是小住、不是怀旧，而是告别这是我最后一次发言", "page": 40, "y": 1069, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1695, "speaker": "普净", "text": "拿话筒。", "page": 40, "y": 1173, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1696, "speaker": "康有为", "text": "不用了，保皇派说我激进，维新派说我保守，历史让康有为两端不得为人，这都是些庸俗的评价，庸碌的世人怎么能够理解我的先见之明，因为如果完不成变法，中国将会战乱频生，骨肉相残！你们说我维新急躁，三年！三年不是我信口雌黄，二：年在易学来讲是中国难得的一次天赐良机。圣人是孤独的，我将去江苏茅山修道。这是我，最后一次走动法源寺。", "page": 40, "y": 1224, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1697, "speaker": "异禀", "text": "师父，他们还活着吗？", "page": 40, "y": 1690, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1698, "speaker": "普净", "text": "你看不见？", "page": 40, "y": 1741, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1699, "speaker": "异禀", "text": "活着。", "page": 40, "y": 1793, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1700, "speaker": "普净", "text": "晚清这段历史，讲述的是，家国。", "page": 40, "y": 1844, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1701, "speaker": "异禀", "text": "君臣。", "page": 40, "y": 1896, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1702, "speaker": "普净", "text": "出世。", "page": 40, "y": 1948, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1703, "speaker": "异禀", "text": "人隐（合）极端的国难", "page": 40, "y": 2000, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1704, "speaker": "谭嗣同", "text": "极端的生死。", "page": 41, "y": 245, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1705, "speaker": "梁启超", "text": "极端的失败。", "page": 41, "y": 296, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1706, "speaker": "康有为", "text": "极端的成功。", "page": 41, "y": 348, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1707, "speaker": "普净", "text": "在极端的两极寻找常态，发现平衡这些变法维新人士，住家离法源寺很近。", "page": 41, "y": 400, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1708, "speaker": "康有为", "text": "我是康有为，（广东话）我是广东人。", "page": 41, "y": 503, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1709, "speaker": "梁启超", "text": "（广东话）我也是广东人。", "page": 41, "y": 553, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1710, "speaker": "康有为", "text": "（广东话）自己人。", "page": 41, "y": 606, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1711, "speaker": "梁启超", "text": "（广东话）自己人。", "page": 41, "y": 656, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1712, "speaker": "康有为", "text": "（广东话）不是自己人。", "page": 41, "y": 708, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1713, "speaker": "梁启超", "text": "（广东话）不是自己人。", "page": 41, "y": 759, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1714, "speaker": "康有为", "text": "我住在菜市口米市胡同43号南海会馆。", "page": 41, "y": 810, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1715, "speaker": "梁启超", "text": "我是梁启超，我住在陶然亭边儿上，粉房琉璃街，新会会馆。", "page": 41, "y": 862, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1716, "speaker": "普净", "text": "他们常到庙里走动。谭、梁二位虔诚信佛", "page": 41, "y": 966, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1717, "speaker": "舞台提示", "text": "[幕外：一声磬响。", "page": 41, "y": 1017, "col": 0, "kind": "stage", "chapter": 15}, {"id": 1718, "speaker": "普净", "text": "谭嗣同走后，梁启超写了大量关于佛教的研究论著。", "page": 41, "y": 1069, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1719, "speaker": "异禀", "text": "《中国佛法兴衰沿革说略》、《佛教教理在中国之发展》等。", "page": 41, "y": 1172, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1720, "speaker": "康有为", "text": "这二十世纪一来，我变成了活古董。", "page": 41, "y": 1274, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1721, "speaker": "梁启超", "text": "您是落幕的十九世纪中国第一先知。", "page": 41, "y": 1325, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1722, "speaker": "谭嗣同", "text": "由您成全了我去救助众生的想法。", "page": 41, "y": 1377, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1723, "speaker": "普净", "text": "康先生说过，任何可以因循规律的，都要去因循", "page": 41, "y": 1428, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1724, "speaker": "梁启超", "text": "任何可以变化的，都要去变化，这是我说的！", "page": 41, "y": 1531, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1725, "speaker": "刘光第", "text": "我们尽可能去采行。", "page": 41, "y": 1582, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1726, "speaker": "林旭", "text": "去拼命", "page": 41, "y": 1634, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1727, "speaker": "杨锐", "text": "去达成！", "page": 41, "y": 1685, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1728, "speaker": "梁启超", "text": "我不敢说今天的主张一定可行，但我清楚地知道，昨天的法子不可行。我要去试一试，去革命。", "page": 41, "y": 1736, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1729, "speaker": "康有为", "text": "国家大事，岂可以尝试出之？试到千万人头落地，试到人心已死，再后悔就来不及了。", "page": 41, "y": 1891, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1730, "speaker": "普净", "text": "历史已经证明了改良的失败，这是谭嗣同用血的代价证明的。", "page": 41, "y": 1994, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1731, "speaker": "梁启超", "text": "不止改良行不通，发现革命革得不彻底中国还是不行。", "page": 41, "y": 2096, "col": 0, "kind": "dialogue", "chapter": 15}, {"id": 1732, "speaker": "康有为", "text": "我怀念那一份温暖的古老。", "page": 41, "y": 296, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1733, "speaker": "众人", "text": "（合）我们所处的时代，离名义上的帝国己经遥远，但它离实质的帝国还是那么接近！解决中国问题，就是要寻找出路，任何障碍中国寻求发展的人，都必须回避", "page": 41, "y": 347, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1734, "speaker": "异禀", "text": "佛教讲，有情来下种，因地果还生。", "page": 41, "y": 554, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1735, "speaker": "普净", "text": "无情亦无种，无性亦无生。", "page": 41, "y": 605, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1736, "speaker": "普净", "text": "寺庙是个好道场，祈福、许愿，讨论鬼神、僧俗、出人、仕隐。", "page": 41, "y": 656, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1737, "speaker": "谭嗣同", "text": "寺庙是个好道场，超度、忏悔，讨论生死、朝野、家国、君臣。", "page": 41, "y": 759, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1738, "speaker": "普净", "text": "人我、是非、情理。", "page": 41, "y": 862, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1739, "speaker": "谭嗣同", "text": "常变、去留、因果、经世济民。", "page": 41, "y": 913, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1740, "speaker": "舞台提示", "text": "[幕外：一声磬响。", "page": 41, "y": 965, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1741, "speaker": "普净", "text": "法海真源、法脉相承。", "page": 41, "y": 1016, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1742, "speaker": "舞台提示", "text": "[异禀，递上功德簿", "page": 41, "y": 1068, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1743, "speaker": "异禀", "text": "师父，有位小施主昨天给他岳父杨昌济守了一宿的灵，他给了一些功德钱，我要他在功德簿上留个名。", "page": 41, "y": 1120, "col": 1, "kind": "dialogue", "chapter": 15}, {"id": 1744, "speaker": "舞台提示", "text": "[普净，接过功德簿看。", "page": 41, "y": 1273, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1745, "speaker": "舞台提示", "text": "[多媒体：字幕“毛润之”", "page": 41, "y": 1325, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1746, "speaker": "舞台提示", "text": "[法源寺依旧，人群无论生死，都是游走在历史中，寻寻觅觅", "page": 41, "y": 1376, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1747, "speaker": "舞台提示", "text": "[灯光：慢慢收尽。", "page": 41, "y": 1480, "col": 1, "kind": "stage", "chapter": 15}, {"id": 1748, "speaker": "舞台提示", "text": "[全剧终。", "page": 41, "y": 1530, "col": 1, "kind": "stage", "chapter": 15}];
